INSERT INTO admin_users ("username", "password_hash") VALUES ('admin', '$argon2id$v=19$m=65536,t=3,p=4$0KRkQK2UpXoQqrTquT/kHw$ZNckKgPc9sipGbEgNQXg83kwblyWvI9S4C2NEOuV0gA');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_01', '分析性思考', 'Analytical Thinking', 'nan', '衡量邏輯思考、識別模式、系統性分析資訊以及運用結構化推理解決問題的能力');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_02', '韌性', 'Resilience', 'nan', '衡量從困難中恢復、處理變化並在困難時期保持情緒堅強的能力。反映情緒強度、靈活性以及在壓力下茁壯成長的能力');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_03', '認知彈性', 'Cognitive Flexibility', 'nan', '衡量根據新資訊或變化的環境調整思考策略和行為的能力，顯示心理靈活性和問題解決的多樣性');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_04', '適應敏捷', 'Change Agility', 'nan', '衡量快速適應、保持靈活性並對變化的環境、優先事項和期望做出積極回應的能力');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_05', '自主領導', 'Self-Leadership', 'nan', '衡量一個人透過目標設定、激勵和個人問責來領導自己的能力');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_06', '人際影響力', 'Social Influence', 'nan', '衡量說服、啟發和影響他人思想、態度或行為的能力。反映堅定自信、魅力、領導風範和溝通效能');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_07', '創造性思考', 'Creative Thinking', 'nan', '衡量產生原創想法、發散性思考以及以創新方式應對挑戰的能力');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_08', '卓越追求動機', 'Achievement Motivation', 'nan', '衡量一個人對卓越表現的驅動力、對技能精通的追求以及對卓越的承諾');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_09', '自我覺察', 'Self-Awareness', 'nan', '衡量一個人對自己的情緒、行為、動機以及對他人影響的覺察程度');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_10', 'AI科技素養', 'AI Literacy', 'nan', '衡量理解、使用和批判性評估人工智慧技術的能力');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_11', '同理心', 'Empathy', 'nan', '衡量設身處地的能力；並以他人的參考架構去理解或感受他人正在經歷甚麼');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_12', '積極傾聽', 'Active Listening', 'nan', '衡量專心傾聽、處理資訊並在對話中有效回應的能力');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_13', '好奇心', 'Curiosity', 'nan', '衡量學習、探索和理解新想法、經驗或資訊的渴望');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_14', '終身學習', 'Lifelong Learning', 'nan', '衡量持續追求新知識和技能以促進個人和專業發展的動機');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_15', '系統性思考', 'Systems Thinking', 'nan', '衡量理解和管理複雜系統、模式和相互依存關係的能力');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_16', '可靠性', 'Dependability', 'nan', '衡量一個人的可靠性、一致性和可信度');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_17', '準確嚴謹度', 'Attention to Detail', 'nan', '衡量在完成任務時達到徹底性和準確性的能力');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_18', '協調溝通', 'Interpersonal Communication', 'nan', '衡量基本的溝通能力，如清晰表達、理解他人、回應性互動、自信堅定和有效傾聽');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_19', '協商談判', 'Negotiation Skills', 'nan', '衡量一個人在談判情境中的方法、效能和心態');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_20', '批判性思考', 'Critical Thinking', 'nan', '衡量邏輯推理、資訊分析、批判評估和決策判斷能力');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_21', '社交智商', 'Social Intelligence', 'nan', '衡量社會覺察、情境理解和關係管理能力');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('ANI_22', '高效決策', 'Decision-Making', 'nan', '衡量在問題解決、信心、風險分析和果斷性方面的決策效能');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_01', '盡責', 'Conscientiousness', 'nan', '個人的自制力程度以及把工作做到盡善盡美的慾望。包含成就追求、審慎（深思熟慮）、盡職盡責、衝動控制、條理性、完美主義、自我勝任感、自律。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_02', '成就動機', 'Achievement Striving', 'nan', '衡量一個人對待工作認真的程度、提高工作表現的意願，以及努力達成目標的程度。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_03', '審慎', 'Deliberation', 'nan', '評估一個人是否會於行動前審慎思考。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_04', '義務感', 'Dutifulness', 'nan', '衡量一個人有多大程度遵循良知和規範而行。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_05', '衝動管理', 'Impulse Control', 'nan', '衡量一個人為達長期目標，管理自身衝動、情緒和行為的能力。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_06', '條理性', 'Orderliness', 'nan', '衡量對例行程序、審議和細節方向的偏好。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_07', '完美主義', 'Perfectionism', 'nan', '衡量一個人追求完美和無瑕疵的程度。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_08', '自我勝任感', 'Self Competence', 'nan', '衡量一個人覺得自己是否有能力、有效率且可以掌控局面。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_09', '自律性', 'Self Discipline', 'nan', '衡量延遲滿足、抗拒短期誘惑以實現長期目標的能力。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_10', '誠實謙遜', 'Honesty-Humility', 'nan', '評量受訪者在誠懇、公正、避免貪婪及謙虛面向的個人差異。例如在預期目標、利益下是否能維持誠實、公平對待他人，不會過度炫耀或重視財富、社會地位，或視特權為應得權益。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_11', '誠懇', 'Sincerity', 'nan', '評量為了達成目標而願意去操縱、欺騙他人的意願。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_12', '低物質傾向', 'Material Avoidance', 'nan', '對於財富及地位這類事物的重視程度。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_13', '公正性', 'Fairness', 'nan', '評量為了領先他人是否願意欺騙、偷竊、貪污或利用他人的意願。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_14', '謙虛', 'Modesty', 'nan', '評量對於他人與自身關係上的看法。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_15', '心理資本', 'Psychological Capital', 'nan', '唯一重要正向特質，對態度、行為和表現有積極影響，包含以下四種心理特質：希望、效能、韌性和樂觀情緒。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_16', '希望', 'Hope', 'nan', '對於個人將目標與達成該目標的動機付諸概念化與策略化的能力，其看法為何。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_17', '目標效能感', 'Efficacy', 'nan', '個人對於自己付出努力達成目標的能力有信心的程度。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_18', '韌性', 'Resilience', 'nan', '如何面對壓力或逆境以及降低自身的受損性;包含於衝突、失敗、責任變更(甚或加重)後的挽救的能力。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_19', '樂觀', 'Optimism', 'nan', '個人對事物的解讀方式或是看待生活中不如意的方式。高度樂觀者會解釋成不如意只是暫時的，而悲觀者則通常認為這些不如意將會是永久的且無所不在。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_20', '創新力', 'Innovativeness', 'nan', '用創新的方式做事及發現問題與找出解決方式的慾望;不想受限於既有思考方式以及挑戰主流規則。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_21', '效率取向', 'Approach to Efficiency', 'nan', '想要變得更精確、更可靠、更有效率的欲望。低分者在解決問題時更加遵循規範、精確且有條理。高分者對繁文縟節不太關心，不喜歡總是按照固定的程序和結構行事，且往往以不同尋常的角度來處理任務。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_22', '紀律遵循度', 'Rule Governance', 'nan', '反映一個人願意在既定架構內工作或用傳統方式做事的程度。低分者喜歡以既有且被接受的方法來解決問題，他們在存在明確規則的情況下表現最佳。高分者則不依賴於被接受的方法來解決問題，他們更喜歡在沒有既定規則的情境中處理問題。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_23', '獨創性', 'Sufficiency of Originality', 'nan', '發揮其創新性、以另類觀點看待事情及用不同以往的方式做事的意願。高分者經常找出創新方法解決問題，而低分者的想法往往在規範或既定程序內，較少原創性想法。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_24', '真實性', 'Authenticity', 'nan', '衡量個體的行為與其價值觀及欲望的一致性，儘管有著外界的社會從眾壓力，依然保持一致。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_25', '集體意識', 'Collective Orientation', 'nan', '衡量對個體間凝聚力重視和強調的程度，以及集體優先於個人的程度。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_26', '同理心', 'Empathy', 'nan', '衡量設身處地的能力；並以他人的參考架構去理解或感受他人正在經歷甚麼。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_27', '權益公平感', 'Equity Perception', 'nan', '是指一個人對付出與回報的在意程度，以此來評測出一個人對職場公平/公正的在意程度。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_28', '感謝', 'Gratitude', 'nan', '評估個人表達感激的傾象差異。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_29', '人際適應力', 'Interpersonal Versatility', 'nan', '一個人在多大程度上能夠適應不同類型的人，管理所有人際交往中固有的自然緊張關係，並建立起互利互惠的關係。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_30', '個人責任感', 'Personal Accountability', 'nan', '衡量個人具備責任感和把事情做好的決心的程度。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_31', '個人成長動機', 'Personal Growth Initiative', 'nan', '評估個人對個人成長的主動性以及參與改變和發展自我的渴望。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_32', '心理特權', 'Psychological Entitlement', 'nan', '評量其認為應得到特權及特殊待遇的程度，一般不太考慮到其實際能力、努力或績效高低。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_33', '社會期望反應', 'Social Desirability', 'nan', '評估個體是否誠實回答，還是為了塑造樂觀形象和取得他人認可，而歪曲自己的信仰和答案。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_34', '工作熱忱', 'Work Passion', 'nan', '對工作的熱忱程度。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_35', '生活熱情', 'Zest', 'nan', '衡量個體在日常工作與生活中，是否傾向以積極、充滿熱情與活力的方式行事，並對未來抱持期待與動能。');
INSERT INTO trait_definitions ("trait_id", "name_zh", "name_en", "dimension", "definition") VALUES ('CIA_36', '情緒易激度', 'Temper', 'nan', '衡量一個人在面對煩惱或挫折時，情緒被激起的容易程度。');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_02', 'A', 75, 100, '壓力調適', '面對挫折與壓力能快速復原並維持穩定表現，較能把困難轉化為調整與學習。', '適合高壓、變動或需要長期推進的任務；可作為穩定軍心的角色配置。', '表現較高韌性傾向，面對壓力、挫折或變動情境時，通常能在合理時間內回復到穩定狀態，並從經驗中整理出調整方向與學習重點。', '{"do": "可用於：①說明其在「壓力復原、長期任務持續度、情緒穩定度」上的相對優勢②提供適合任務建議，如長期專案、高變動環境或需要安定團隊情緒的角色③提醒仍需安排休息與資源，而非將其視為可以無限加壓的對象。", "dont": "禁止：①描述為「不會有壓力」「什麼都壓不垮」等誇大說法②鼓勵在缺乏資源或不合理條件下持續硬撐③以韌性高分作為要求其「犧牲健康或私人生活」的理由④推論任何心理診斷或身心狀態。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_02', 'B', 50, 74, '恢復中', '遇到壓力時需要時間調整，通常在獲得支持或釐清方向後能回到穩定狀態。', '安排合理節奏、階段性里程碑與支持資源，有助於維持續航。', '在面對壓力或重大變化時，通常需要一段時間消化與調整；當獲得適當支持、釐清方向與步驟後，多數情況能回到較為穩定的表現並持續前進。', '{"do": "可用於：①說明其在有支援與清晰方向下，仍具備良好續航與恢復力②建議主管或情境安排，如提供階段性里程碑、情境說明與情緒支持③引導個人覺察「什麼樣的壓力、資源或節奏」有助於自己恢復。", "dont": "禁止：①把需要時間調整解讀為「脆弱」「不可靠」②用貶抑或責備語氣描述其反應（例如「太玻璃心」）③推論其適不適合留任或升遷④將一時的狀態當成永久標籤。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_02', 'C', 0, 49, '能量耗損', '長期高強度或高度不確定環境下，較容易出現情緒耗竭或表現波動。', '避免長期高壓獨撐；可搭配同儕支持、分工與恢復機制。', '在長期高壓、持續不確定或資源不足的情境下，較容易出現能量耗損、情緒起伏或表現不穩，需要在負荷、支持與恢復之間有更刻意的管理與設計。', '{"do": "可用於：①協助釐清壓力來源與能量消耗模式，並給出具體的恢復與資源使用建議②建議組織在工作量、排程與支援上做調整（如分工、彈性安排、心理安全）③強調這反映的是「能量管理需求」而非價值或意志力問題。", "dont": "禁止：①將此解讀為「抗壓性差」「不適任關鍵職位」等負面標籤②鼓勵忽略身心狀態或繼續長期過勞③推論任何身心疾病或使用驚悚語言（如崩潰、撐不住）④把短期表現波動放大為個人缺陷。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_28', 'B', 50, 74, '有感但不常說', '內心知道他人幫助重要但表達較保留，通常在重要事件或被提醒時才明確致謝。', '提供具體表達方式（回饋模板、公開致謝場域）可提升社會連結效果。', '對明顯的幫助或支持會覺得需要表示感謝，但對日常小協助或制度性資源未必都會特別放在心上。', '{"do": "可用於：①說明其感謝表現與事件顯著程度有關②建議透過團隊活動或反思機制，增加對日常支持的覺察③鼓勵在覺得被幫助時，適時做出簡單肯定，強化合作關係。", "dont": "禁止：①把沒立即表達感謝等同於「不懂感恩」②忽略文化差異對感謝表達形式的影響③用道德壓力要求其「凡事都要感謝」④不分情境地將其行為解讀為冷漠。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_03', 'A', 75, 100, '快速轉換', '能在不同觀點、策略與方法間切換，快速吸收新資訊並調整做法。', '適合跨領域協作、探索性任務或轉型期的快速迭代工作。', '表現較為突出的認知彈性，能在不同觀點、策略或方法之間切換，面對新資訊或情境變化時，較容易調整思考路徑並嘗試替代方案。', '{"do": "可用於：①說明其在觀點切換、策略調整與跨領域理解上的相對優勢②建議適合投入的任務，例如探索性專案、創新構想討論或轉型期的協作角色③提醒在多方案並行時仍需設立決策標準，避免過度變動方向。", "dont": "禁止：①將其描述為「三心二意」「沒定性」②鼓勵在缺乏共識或評估下頻繁變更策略③把認知彈性與「必然創意十足」畫上等號④推論任何注意力或衝動控制問題。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_03', 'B', 50, 74, '調整中', '願意接受新方式，但需要時間理解與消化，熟悉後表現會明顯提升。', '提供背景、理由與示範，有助於縮短適應時間並降低摩擦。', '在變化情境下具備一定的調整能力，但較需要先理解背景、理由與可能影響，在釐清之後多數情況能接受新做法並逐步調整自己的運作方式。', '{"do": "可用於：①說明其屬於「理解後可調整」的型態，適合搭配充分溝通與示範②提供主管或團隊在引入改變時的操作建議（說明脈絡、給範例、設試行期）③鼓勵個人運用小步試驗或先在安全情境中嘗試新方法。", "dont": "禁止：①把需要理解過程解讀為「固執」或「抗拒」②用急切或壓迫性語言要求立即改變③忽略其對穩定性與可預期性的合理需求④推斷其不適合任何變革相關任務。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_03', 'C', 0, 49, '思維慣性', '面對改變時傾向維持既有做法，對新方法需要更清楚的必要性與步驟。', '適合變動幅度較小或流程穩定的任務；導入改變時需分段推進。', '在思考方式上較容易維持既有路徑與慣用做法，面對改變時，通常需要更明確的必要性說明、具體步驟與足夠時間，才比較容易嘗試與內化新的方式。', '{"do": "可用於：①協助釐清其對穩定結構與既有流程的依賴，並建議在導入改變時採取分段、漸進的方式②鼓勵以「小幅試驗」「雙軌並行」來降低不安全感③提醒主管在溝通變革時增加說明、觀察期與回饋機制。", "dont": "禁止：①直接貼上「守舊」「抗拒學習」等標籤②忽略其在穩定環境中的價值與貢獻③用威脅或恐嚇的方式推動改變④把這個分數當作衡量學習能力或智力的指標。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_04', 'B', 50, 74, '觀察後行動', '通常在理解變化背景與影響後才投入調整，行動較審慎但可持續。', '先給方向與期望，再給可行選項與期限，有助於加速反應。', '在面對變化時傾向先觀察與理解，再進入行動調整階段；通常在掌握變化的背景、影響與期待後，能做出較穩健且可持續的調整。', '{"do": "可用於：①強調其「理解後穩健行動」的風格，適合需要權衡利弊與長期影響的情境②建議主管在調整時先說明原因、預期與界線，有助於加快其決策與跟進速度③鼓勵個人在觀察與行動之間抓到平衡，不必過度延後調整。", "dont": "禁止：①把先觀察的習慣解讀為「反應慢」「沒企圖心」②在尚未說明清楚前，要求立刻承諾或大幅調整③否定其在穩定推進上的價值④將此分數視為對未來發展潛力的限制。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_31', 'B', 50, 74, '被引導就成長', '對成長開放，但多在看見清楚路徑、有人引導或制度推動下才積極投入。', '以學習地圖、導師制與可衡量成長目標最有效；適合穩健培育策略。', '認同持續成長的重要，也願意在有合適機會時投入學習；但在工作繁忙或看不到實質回報時，動力會明顯下降。', '{"do": "可用於：①說明其成長動機與資源、時間與回報期待高度連動②建議在安排訓練時，清楚連結到實際工作與發展機會③鼓勵將學習拆成小步驟，降低啟動成本。", "dont": "禁止：①將其在忙碌時學得少解讀為「不重視成長」②忽略工作量與心理負荷③只用口號式「要終身學習」施壓④在未說明意義下要求參與大量培訓。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_12', 'A', 75, 100, '專注回應', '能專注理解對方內容與意圖，並透過提問與回饋確認關鍵資訊。', '適合面談、需求釐清、協調與衝突化解情境。', '在積極傾聽上表現成熟，能維持高度專注，不打斷對方發言，透過複述、總結與適當提問確認理解，同時留意語氣與非語言訊息，接住對方情緒並給予有建設性的回應。', '{"do": "可用於：①說明其具備接近「積極同理心傾聽／諮詢式傾聽」的能力，在面談、輔導、顧問或協調情境中是重要資源②建議運用複述、開放式提問與總結，協助對方釐清情緒與需求③鼓勵在給建議前先確認「對方想被聽見的是什麼」，讓回應更貼近對方關注點。", "dont": "禁止：①將其傾聽能力視為理所當然的情緒勞務，過度仰賴其處理他人情緒而忽略自身負荷②要求在所有情境下都以高強度情感投入回應③將其描繪成「一定能解決所有他人問題」或做心理治療式承諾④以此分數推論具備專業諮商／治療資格。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_04', 'A', 75, 100, '主動因應', '能快速覺察環境變化並調整優先順序，面對新要求通常能積極回應。', '適合高不確定、節奏快或需頻繁調整資源的情境。', '具備適應敏捷度的明確表現，能較早覺察環境或需求的變化，並主動調整優先順序與資源配置，對新的任務要求通常能以積極、開放的態度面對。', '{"do": "可用於：①說明其在變動情境下的「主動調整、重新排序、快速起跑」的傾向②建議適合投入在轉型專案、變革推動或需要頻繁調整方向的角色③提醒在反應快速的同時，仍需留意與利害關係人對齊，避免超前過多造成落差。", "dont": "禁止：①將其描述為「什麼都接、永遠有彈性」而忽略邊界②鼓勵在資訊不足時貿然大幅改變方向③以此分數合理化過度工作負荷或持續加壓④推論其一定適合所有高變動職務。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_01', 'C', 0, 49, '分析支援', '在資訊複雜或模糊時容易出現焦點分散或結構不足，需要討論、範本或工具協助。', '適合搭配資料整理、拆解模板或團隊共識流程。', '在資訊複雜或模糊時，分析焦點可能較分散，較適合在拆解模板、工具或團隊討論的支援下進行梳理與決策，能更快建立可行的分析結構。', '{"do": "可用於：①提供具體支撐（拆解模板、問題清單、決策樹、範例）②建議用視覺化整理與共識流程（白板、表格、會議紀錄）③強調「需要支援≠不會思考」，把建議聚焦在如何搭建結構。", "dont": "禁止：①說「不會思考/不適合策略」等否定性判斷②把低分當成缺陷或道德評價③推論注意力/心理疾病④要求其在缺乏脈絡與支援下獨立完成高不確定分析。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_01', 'A', 75, 100, '結構清晰', '能穩定運用邏輯與結構化方式拆解問題，辨識關鍵資訊與模式，在複雜或不確定情境下仍能維持分析品質。', '適合承擔問題定義、方案評估與多資訊整合任務。', '表現出穩定的分析性思考，能以邏輯與結構化方式拆解問題、辨識關鍵資訊與模式，面對複雜或不確定情境仍可維持分析品質。', '{"do": "可用於：①解釋其優勢在「結構化拆解、關鍵訊號辨識、方案比較」②給出任務/角色建議（如問題定義、方案評估、多資訊整合）③提醒仍需用資料/事實驗證結論與假設。", "dont": "禁止：①將此特質等同智商、學歷或專業能力高低②保證分析結論一定正確③用貼標/貶抑語氣（如「你就是理工腦」）④推論心理疾病或人格問題。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_01', 'B', 50, 74, '情境分析', '在結構明確或熟悉情境中能有效分析，但在高度模糊或快速變動狀態下需要更多脈絡與引導。', '提供清楚問題框架與資料脈絡，有助於發揮分析能力。', '在情境脈絡較清楚或熟悉時能有效分析與判斷；面對高度模糊或快速變動議題時，較需要補充資訊、問題框架或引導以維持分析效率。', '{"do": "可用於：①建議先澄清目標/範圍/成功標準②提供框架（輸入-處理-輸出、假設清單、比較表）③說明此區間反映「對情境清晰度的依賴」，並給出提升分析品質的支援做法。", "dont": "禁止：①把需要框架解讀為「能力不足」或「不適任」②使用絕對化說法（如「壓力下就完全無法思考」）③將其描述成不負責/不主動④推論任何醫療或心理診斷。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_04', 'C', 0, 49, '穩定導向', '面對頻繁變動時需要較多適應時間，較依賴既有流程與明確指示。', '適合變動較小或規範明確的環境；變更管理需提供緩衝與支援。', '在變化頻繁或方向多次調整的環境中，較容易感到壓力或不安，會更偏好遵循既有流程、清楚指示與穩定節奏，以維持工作品質與心理安全感。', '{"do": "可用於：①說明其對穩定性與預期性的需求，並建議在調整時提供足夠的說明、緩衝期與支援②協助設計較固定的作業節奏或明確 SOP，讓其在穩定框架中貢獻③提醒組織在大幅變革時，需特別關注這類成員的溝通與陪伴。", "dont": "禁止：①以「抗拒改變」「跟不上時代」等字眼貶低其風格②忽略其在穩定運作、流程維護上的價值③用恐嚇或壓力來逼迫迅速調整④將其描述為不適合任何涉及變化的職務。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_05', 'A', 75, 100, '自我驅動', '能自主設定目標、管理進度並調整行動，對成果與承諾有明確自我要求。', '適合高度自主、遠距或需要自我管理的角色與任務。', '展現明確的自主領導狀態，能主動設定目標、規劃步驟並追蹤進度，對承諾與成果有明確的自我要求，較少需要他人頻繁提醒。', '{"do": "可用於：①說明其在自我管理、時間規劃與任務推進上的主動性與可靠度②建議適合投入高度自主、遠距或需要自我規劃的任務與角色③提醒組織仍須提供方向對齊與資源支持，而非完全放任自行承擔所有壓力。", "dont": "禁止：①把高自主等同於「不需要管理、不需支持」②鼓勵長期過度自我要求而忽略休息與健康③以此作為理所當然加重負荷或指派所有「難搞任務」的理由④推論其人格價值或道德優劣。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_05', 'B', 50, 74, '框架依賴', '在目標與期待清楚時表現穩定，但較依賴外部節奏與檢核。', '提供階段性目標、優先序與回饋節點，有助於維持動能。', '在目標與期待清楚時，能穩定完成任務並維持一定自我管理，但在缺乏結構或優先順序不明時，較仰賴外部框架與檢核來維持節奏。', '{"do": "可用於：①說明其適合在有明確目標與節奏設計的情境下發揮穩定表現②建議建立里程碑、檢核點與可視化進度板來支撐自我管理②協助個人學習如何拆解任務與設定自己的節奏，而非單純依賴他人提醒。", "dont": "禁止：①將對結構的需求解讀成「不負責任」或「被動」②用批判語氣描述其為「需要人盯」的對象③忽略組織在目標清晰度與任務設計上的責任④推論其不適合承擔任何自主性較高的工作。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_05', 'C', 0, 49, '外部引導', '需要較明確的指示、節奏與回饋，否則容易分散或延宕。', '適合結構清楚的工作安排；管理上需更明確的分工與追蹤。', '在沒有明確指示、步驟與回饋時，較容易出現分心或延宕，傾向需要清楚的任務拆解、角色分工與追蹤機制，才能較穩定地推進工作。', '{"do": "可用於：①協助界定其在「需要結構與引導」上的特性，並建議具體管理做法（SOP、任務拆解、固定檢核）②強調這反映的是自我調節需求，而非能力或意願缺乏③鼓勵逐步練習小範圍的自我規劃，以累積自主經驗。", "dont": "禁止：①將其標記為「懶惰」「沒有責任感」②忽略環境設計與管理方式對表現的巨大影響③以羞辱或威脅方式要求其「自己想辦法」④推論其不適合任何關鍵任務或長期培養。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_06', 'A', 75, 100, '自然帶動', '能以溝通、信任與說服影響他人，並能在互動中建立支持與共識。', '適合協調資源、跨部門推進與帶動改變的角色。', '展現高人際影響力，能透過溝通、信任與說服自然帶動他人，容易在團隊中形成意見凝聚或推進變革的關鍵角色。', '{"do": "可用於：①說明其在建立共識、帶動氣氛與推進跨部門協作上的優勢②建議投入在需要對齊多方利害關係人、推動改變或代表團隊發聲的情境③提醒需注意溝通透明與一致性，避免因影響力大而讓他人感到被壓迫或資訊不對稱。", "dont": "禁止：①將其影響力等同於權威或否定他人觀點的正當性②鼓勵以操控、情緒勒索或過度包裝來說服他人③忽略組織在權責設計與決策機制上的界線④把高人際影響力當作必然適合所有管理職的唯一判準。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_06', 'B', 50, 74, '任務影響', '在職責或專業範圍內具影響力，遇到超出角色邊界時影響力較弱。', '給予清楚角色定位與授權範圍，有助於穩定發揮。', '在人際互動中，在自身職責或專業範圍內具有一定影響力，當角色定位與授權邊界清楚時，能有效說明觀點並帶動相關對象；超出範圍時影響力較受限制。', '{"do": "可用於：①說明其在人際影響上與「角色清晰度、權責範圍」的連動關係②建議透過清楚賦權與角色說明，提高其在組織內適當發聲的空間③鼓勵在符合職責的前提下，主動提出觀點並練習橫向影響，而非只在被動被詢問時表達。", "dont": "禁止：①將其描述為「沒有影響力」「存在感低」②忽略組織結構與文化對其影響表現的限制③以此分數推論其不適合與人合作或不善溝通④要求在完全沒有授權或支持下承擔高度政治性的影響任務。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_06', 'C', 0, 49, '專業輸出', '影響多來自專業產出而非互動帶動，較少主動推動他人改變。', '適合專注型、個人貢獻或以成果說服的角色配置。', '在人際互動中，影響力多來自專業產出或成果本身，而非主動發起說服或帶動他人，較少在互動中主動推動他人改變或搶佔發言位置。', '{"do": "可用於：①說明其偏向以專業與成果影響他人，適合在重視品質與貢獻的情境中發揮②建議搭配明確的成果呈現管道（簡報、文件、評估報告），讓其影響力被看見③鼓勵在安全情境下，逐步練習表達觀點與說明思路，而非硬性要求改變風格。", "dont": "禁止：①將其標籤為「不擅長人際」「不合群」②要求其立即轉變為高度外向、強勢主導的溝通風格③忽略其在專業深度與穩定輸出上的價值④以此分數推論其不適合任何需要合作或溝通的職務。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_07', 'A', 75, 100, '多元發想', '能提出不同觀點與新穎解法，善於跳脫既有框架思考問題。', '適合創新、概念發想與解法探索階段。', '具備創造性思考的突出表現，能從多元角度觀看議題，提出新穎觀點與解法，較容易跳脫既有框架，為問題帶來不同的可能性。', '{"do": "可用於：①說明其在點子發想、概念設計與問題重新定義上的優勢②建議參與創新專案、策略構想或需要打破慣例的工作階段③提醒仍需搭配可行性評估與落地規畫，避免讓團隊感到變動過多或難以執行。", "dont": "禁止：①將「創意多」簡化成「一定好用」或「一定適合所有情境」②以此作為忽略流程、風險或資源限制的藉口③把他人較保守的反應解讀為阻礙或保守者的錯④鼓勵在完全沒有評估下頻繁更換方向。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_07', 'B', 50, 74, '改良導向', '能在既有方案上進行優化與調整，創意多來自實務經驗與限制條件。', '提供清楚限制與目標，有助於產出可落地的改良方案。', '在既有框架與實務條件下，擅長對現有方案做調整或優化，創意多與實際需求、限制與經驗結合，傾向尋找「更好但可行」的改良路徑。', '{"do": "可用於：①說明其創造力偏向「改良與優化」而非完全顛覆式創新②建議投入在流程改善、產品優化或營運調整等需要務實創意的任務③鼓勵與偏概念型創意者合作，由其負責把想法轉化為可落地方案。", "dont": "禁止：①把這種風格解讀為「缺乏創意」②要求其在完全沒有參考與以往經驗時，獨立提出大膽顛覆方案③忽略實務限制，期待其產出與A區間相同型態的創新輸出④用分數去否定其在改善與精進上的價值。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_07', 'C', 0, 49, '規範取向', '偏好既定流程與標準作法，較少主動提出新構想或冒險嘗試。', '適合高一致性、合規或標準化要求高的任務。', '在思考模式上偏好遵循既定流程與標準作法，較少主動提出新構想或冒險嘗試，更傾向在清楚規則下確保品質與一致性。', '{"do": "可用於：①說明其在標準化、品質管控與合規要求高的情境中具備穩定優勢②建議投入在需要一致輸出、精準執行或風險敏感度高的任務③鼓勵在安全範圍內，以小步調整或微創新方式逐步擴展彈性。", "dont": "禁止：①貼上「沒創意」「保守到不行」等負面標籤②忽略其在穩定營運與風險控管上的重要性③以恐嚇方式要求其頻繁冒險或快速接受高度不確定變化④將此分數視為學習能力或發展潛力的否定。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_08', 'A', 75, 100, '卓越驅動', '對成果品質與表現標準有高度要求，主動追求突破與精進。', '適合高挑戰、高標準或需要拉高團隊門檻的任務。', '表現明顯卓越追求動機，對成果品質與個人表現標準有較高要求，傾向主動設定具挑戰性的目標並持續投入，以追求突破與精進。', '{"do": "可用於：①說明其在自我驅動、目標拉高與持續精進上的優勢②建議安排可見成效與成長空間的任務，以善用其高動機③提醒需留意過度完美或目標過高可能帶來的壓力，並協助建立健康的成就觀。", "dont": "禁止：①將其視為可以無限加壓、不需照顧的對象②鼓勵以過勞或犧牲私人生活換取成就③用分數合理化不平衡的工作分配④把偶爾狀態下滑解讀為「不夠用力」。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_08', 'B', 50, 74, '目標導向', '在目標清楚與回饋機制明確時能穩定投入，動能與里程碑連動。', '設定清楚指標與階段成果，有助於維持節奏與投入。', '在有明確目標與回饋機制時能穩定投入，動機與節奏多與里程碑、成果回饋和外在環境連動，對清楚的期望與進度管理反應較佳。', '{"do": "可用於：①說明其動機表現與「目標清晰度、回饋頻率」之間的關係②建議透過清楚KPI、階段成果與定期回顧來維持投入度③協助個人學習在目標不夠清楚時，主動澄清與設定自己可控的小目標。", "dont": "禁止：①將其描述為「需要人盯才會動」②把所有動機起伏歸咎於個人意志力而忽略目標設計問題③用分數判斷其不適合承擔重要專案④以羞辱方式處理動力下降，而不是檢視系統與情境。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_08', 'C', 0, 49, '需求回應', '能完成基本要求，但較少主動追求更高標準或自我加碼。', '適合職責明確、節奏穩定的工作安排。', '在滿足基本要求與完成指定任務方面能維持一定水準，但較少主動追求更高標準或額外挑戰，動機多與外在要求、制度或環境壓力連動。', '{"do": "可用於：①說明其傾向以「達成既定要求」為主要目標，適合在職責明確、流程穩定的情境下工作②建議透過清楚說明升遷、獎酬或成長機會，逐步建立內在動機連結③鼓勵探索個人有興趣的領域，從小範圍開始嘗試更高標準的挑戰。", "dont": "禁止：①將其標籤為「不上進」「沒企圖心」②忽略組織在激勵設計、職涯路徑與文化上的影響③以比較或羞辱方式逼迫其追求高標準④推論其未來必然缺乏成長或貢獻。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_09', 'A', 75, 100, '自我覺察', '能清楚覺察自身情緒與行為模式，理解其對他人與結果的影響並能調整。', '適合需要反思、回饋吸收與自我調節的角色。', '有高自我覺察，能較清楚地察覺自身情緒、想法與行為模式，理解其對他人與結果的影響，並較有能力在需要時調整表現與互動方式。', '{"do": "可用於：①說明其在情緒管理、反思與行為調整上的潛在優勢②建議投入需要回饋吸收、角色榜樣或教練性質較強的工作脈絡③提醒高覺察不代表永遠狀態穩定，也需要適當支持與休息。", "dont": "禁止：①將高自我覺察解讀為「不會情緒失衡」或「不需要支持」②要求其在任何情境下都必須完美調整自己③利用其覺察能力作為加重情緒與責任負擔的理由④推論其必然適合所有輔導或教練角色。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_12', 'B', 50, 74, '任務傾聽', '在目標明確時能有效傾聽，但在多工或高壓下易出現分心或漏聽。', '用會議結構、重點提示與摘要確認可提升表現。', '在傾聽過程中能維持一定專注，對重要內容與關鍵訊息有不錯掌握；在關係較重要或議題較敏感時，會有意識地多問幾句、確認自己有聽懂，但在其他時候，尤其多工或壓力較大時，較容易回到偏「選擇性傾聽」。', '{"do": "可用於：①說明其具備從「選擇性傾聽」往「積極同理心傾聽」移動的能力，差別多在情境與心力分配②建議在關鍵溝通時刻刻意關閉干擾、放慢節奏，用複述與簡短總結提高理解深度③鼓勵透過練習開放式提問與情緒確認（如「聽起來你有點…？」）來提升同理層次。", "dont": "禁止：①把在高壓或分心情境下的表現簡化為「你不願意聽」②忽視工作環境中的多工要求與資訊轟炸，單純用態度來解讀傾聽品質③以單一互動情境貼上「不會傾聽」的長期標籤④要求其在所有場景都維持高強度傾聽而不考量負荷。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_09', 'B', 50, 74, '情境覺察', '在特定情境或他人提醒下能察覺自身狀態，但不一定隨時保持反思。', '透過回饋節點與引導提問，可提升自我調節表現。', '在特定情境、他人回饋或事件觸發下，能察覺自己的情緒與反應，但不一定隨時保持自動反思模式，較需要外界提示或停頓空間來整理。', '{"do": "可用於：①說明其覺察多與「情境與他人回饋」連動，可透過定期檢視與對話提升自我調節②建議設計反思節點（如1對1談話、檢討會、個人筆記）來協助整理經驗③鼓勵主動提問與尋求回饋，逐步拉高平時的自我覺察頻率。", "dont": "禁止：①將此區間解讀為「不懂反省」②在缺乏具體例證時指責其「沒自覺」③忽略組織提供回饋文化與心理安全的重要性④用片面事件下的反應直接貼上長期標籤。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_09', 'C', 0, 49, '覺察較少', '較少主動覺察自身狀態或對他人的影響，需要更具體的回饋才會調整。', '適合搭配明確行為指引、即時回饋與檢核機制。', '在日常情境中較少主動檢視自身情緒、行為或其對他人的影響，通常需要較具體、明確的回饋或事件，才會啟動覺察與調整的過程。', '{"do": "可用於：①說明其在覺察啟動上較仰賴外部回饋與具體事件②建議主管或同事提供明確、具體且建設性的回饋，而非抽象評價③協助設計簡單的自我檢核工具或提問，引導其在重要時刻多一點停頓與思考。", "dont": "禁止：①將其定義為「完全沒有自覺」「不會成長」②以指責或羞辱方式提供回饋，造成防衛而非學習③忽略組織在回饋品質與文化上的責任④過度解讀單次行為為固定且不可改變的特質。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_10', 'A', 75, 100, '應用理解', '能理解 AI 概念、應用情境與限制，並能評估實務價值與風險。', '適合參與數位轉型、工具導入與流程再設計。', '具備較成熟AI 科技素養，能理解 AI 的核心概念、常見應用情境與限制，並在實務中評估其帶來的價值與風險，協助組織做出較穩健的導入決策。', '{"do": "可用於：①說明其在 AI 概念理解、應用評估與風險意識上的相對優勢②建議投入在數位轉型、工具選型或流程再設計等需要判斷 AI 適用性的任務③提醒 AI 能力主要聚焦在「理解與應用判斷」，並非代表具備模型開發或工程實作能力。", "dont": "禁止：①將其 AI 素養等同於「可以獨立開發模型或架構系統」②以高分作為安排不合理技術責任或額外隱性工作負擔的理由③用「你最懂 AI，所以錯都是你」這類方式推卸組織決策責任④把 AI 素養與個人整體價值或智力高低直接畫上等號。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_10', 'B', 50, 74, '使用導向', '能操作 AI 工具並產生產出，但策略性理解與風險判讀仍需引導。', '提供實例、最佳實務與使用邊界，有助於深化理解。', '在 AI 工具使用上已有一定經驗，能操作並產出成果，但對於更深一層的原理、策略性應用與風險判斷，仍較需要具體案例與引導說明。', '{"do": "可用於：①說明其目前重點在「實際使用」而非完整策略思維，適合透過工作坊、範例與最佳實務來深化②建議提供清楚的使用邊界、隱私與安全指引，幫助其把既有經驗轉成更穩健的判斷③鼓勵在實務中逐步累積「什麼場合適合用／不適合用」的經驗，而不是只看工具方便與否。", "dont": "禁止：①把此區間解讀為「只會亂玩工具」②忽視組織在教育訓練與治理框架上的責任，將所有誤用風險全丟給個人③以是否熟悉最新工具作為對其工作價值的單一評斷④用恐嚇式說法（例如「不會用 AI 就會被淘汰」）施壓。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_10', 'C', 0, 49, '起步階段', '對 AI 概念與應用仍在熟悉階段，需要具體示範與情境說明。', '適合循序導入；先從低風險工具與任務開始。', '目前仍在熟悉 AI 相關概念與應用的初始階段，對名詞與工具可能感到陌生或零散，需要透過具體示範、情境案例與循序練習，逐步建立基本理解與信心。', '{"do": "可用於：①說明其處在「基礎建立期」，適合先從低風險、操作簡單的工具與具體情境開始②建議提供循序漸進的教學、練習任務與問答機會，讓其在安全環境中探索③強調這不代表抗拒或跟不上，而是需要時間與合適資源來累積經驗。", "dont": "禁止：①把此區間標籤為「不懂科技」「抗拒改變」②在沒有給予足夠資源與示範前，就以成效不彰作為責備依據③用貶抑語氣嘲諷其數位能力或世代差異④推論其未來無法適應數位轉型或缺乏學習能力。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_11', 'A', 75, 100, '情感理解', '能從他人立場理解情緒與需求，並在互動中做出適切回應。', '適合需要人際敏感度、團隊支持或客戶互動的角色。', '表現出高度同理心，能從他人角度感受情緒與需求，並在互動中給出適當回應，有助於建立信任關係與支持性的合作氛圍。', '{"do": "可用於：①說明其在人際敏感度、情緒辨識與關係修復上的優勢②建議投入在需要照顧他人感受、維繫團隊氣氛或大量對外互動的角色（例如客服、顧問、管理者）③提醒同理心仍需要搭配界線與判斷，避免過度承擔他人情緒或犧牲自身需求。", "dont": "禁止：①把高同理視為「一定要隨時配合他人」②鼓勵為了維持關係而壓抑合理界線或專業判斷③在衝突發生時，要求其單方面扮演「情緒垃圾桶」的角色④將其同理能力當成理所當然的情緒勞務，而缺乏相對應支持。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_11', 'B', 50, 74, '理性同理', '能理解他人觀點與處境，但情感回應較偏理性與務實。', '在專業導向或任務型合作中表現穩定。', '在理解他人觀點與處境上具備一定能力，能理性掌握對方立場與需求，但情緒回應較偏務實與就事論事，較少表現強烈的情感回應。', '{"do": "可用於：①點出其同理風格偏向「理解與協助解決」而非強烈情感投入②建議運用在專業導向或任務型合作情境，如專案協作、問題分析等③鼓勵在需要情緒支持的情境中，多用一句確認感受或簡短回應情緒，再進入解決方案。", "dont": "禁止：①將此區間解讀為「冷淡」「沒溫度」②在需要實務決策時，反而過度要求情緒性回應而忽略其理性優勢③以單一互動片段判斷其是否「有同理心」④把所有關係維護責任交給其承擔。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_11', 'C', 0, 49, '互動距離', '較少主動感受或回應他人情緒，互動多以任務完成為主。', '適合互動需求較低或分工明確的工作型態。', '在人際互動時較少自然而然地連結到他人的情緒狀態，對感受的敏感度較低，互動重心多放在任務完成、資訊交換或角色職責上。', '{"do": "可用於：①說明其人際風格偏任務導向，適合在角色分工清楚、情緒需求較低的工作情境②建議透過簡單的提問（例如「這樣你覺得還可以嗎？」）來補上基本的情緒確認③提醒組織在需要高情緒勞務的職位上，應評估是否安排足夠訓練或支援，而非單靠個人自行摸索。", "dont": "禁止：①直接貼上「沒同理心」「不在乎別人」等標籤②用道德批判的角度要求其改變，而不提供具體練習與範例③忽略其在穩定、務實與結果導向情境中的價值④將此分數視為無法改善的固定人格缺陷。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_15', 'B', 50, 74, '局部整合', '能掌握主要關聯，但遇到高度複雜系統時需要視覺化或說明輔助。', '用流程圖、關聯圖與假設檢核可提升整體掌握。', '在系統性思考上具備一定能力，能掌握主要關聯與脈絡，但面對高度複雜或資訊龐大的議題時，較需要透過視覺化工具或結構化說明輔助整理全貌。', '{"do": "可用於：①說明其在有框架、有圖像輔助時能有效理解系統運作②建議透過流程圖、關聯圖與假設檢核表來支援思考③鼓勵在面對複雜問題時，先主動要求或自己建立整體圖像再往下分析。", "dont": "禁止：①把對工具與說明的需求視為理解力不足②在資訊高度破碎情境下，仍期待其快速做出全面判斷③以單次混亂經驗評斷其不適合處理複雜議題④用貶抑方式形容其為「只懂一點皮毛」。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_12', 'C', 0, 49, '資訊遺漏', '容易錯過細節或誤解對方重點，需要更頻繁的確認與書面化。', '適合搭配紀錄、摘要與確認流程降低落差。', '在對話中較容易落在「選擇性傾聽」或表面回應的模式，可能只接收到自己感興趣或立刻有關的部分，較少主動複述、總結或確認對方真正的感受與需求。', '{"do": "可用於：①指出其目前傾聽多停在「聽到部分內容」的層次，適合透過簡單技巧（如多問一句、多重述一句）逐步往積極傾聽靠近②建議在重要對話中刻意放慢回應，不急著表達立場，先確認「我剛剛聽到的是…對嗎？」③鼓勵觀察語氣與表情等非語言訊號，幫助自己看見內容背後的情緒與需求。", "dont": "禁止：①將此區間直接標記為「不在乎別人」「完全不會聽」②用道德批判或羞辱的方式要求改變傾聽方式③忽略組織文化、會議節奏與發言空間設計對傾聽行為的影響④據此推斷其不適合所有與人互動或服務相關職務。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_13', 'A', 75, 100, '主動探索', '對新知與新情境保持高度興趣，主動發問、嘗試並擴展理解。', '適合創新、學習、研究與實驗性任務。', '在好奇心上表現強烈，對新知、新情境與不同觀點保持高度興趣，會主動發問、查資料與嘗試新作法，傾向持續拓展自己的理解範圍。', '{"do": "可用於：①說明其在探索、研究與創新情境中的優勢，適合參與新題目或實驗性任務②建議搭配聚焦與優先順序設定，避免能量分散在過多議題③鼓勵將好奇心延伸到「如何落地」與「如何創造實際價值」，讓探索成果更容易被應用。", "dont": "禁止：①將高度好奇視為理所當然，卻不提供時間與空間來探索②忽略其探索需要，僅要求執行重複、單調的任務③把「還在探索」詮釋為「不穩定」或「不務實」④期待其對每個主題都同樣投入，忽視個人興趣差異。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_13', 'B', 50, 74, '回應式探索', '在需求或引導下能展現探索動機，問題越清楚越容易投入。', '提供明確問題與探索方向，有助於啟動好奇。', '在已有需求、清楚問題或外在引導下，能展現一定程度的探索動機，對與工作或生活相關的議題會主動多問一點，但較少對完全無關的主題投入大量精力。', '{"do": "可用於：①說明其好奇心較偏向「情境觸發型」，在相關性高或問題清楚時較易啟動②建議在任務設計上清楚說明探索的目的與可能收穫，有助於提升參與度③鼓勵個人針對有興趣或與發展相關的領域，設定小型探索目標，而非被動等待外在刺激。", "dont": "禁止：①把此區間解讀為「缺乏好奇心」②在任務缺乏意義感時，單純以壓力或命令要求其投入探索③忽略工作設計與回饋對探索動機的影響④用分數作為評論其人格開放度或價值的依據。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_13', 'C', 0, 49, '焦點保守', '偏好既有知識範圍，較少主動延伸探索或嘗試新作法。', '適合穩定、重複性或標準化程度高的任務。', '在學習與工作中傾向聚焦在已知領域與熟悉作法，對額外探索新主題或新工具的優先度較低，較偏好在穩定框架中持續精進既有能力。', '{"do": "可用於：①說明其在穩定、標準化或重複性較高的任務中，能以既有經驗維持品質②建議透過小幅度、低風險的探索（例如每次多嘗試一個不同做法）來逐步擴展彈性③強調此分數反映的是探索優先順序，而非學習能力或意願的否定。", "dont": "禁止：①貼上「沒好奇心」「不求進步」等標籤②忽視其在穩定執行與知識深化上的價值③要求在缺乏支持與說明下，快速接受大量變化或新工具④將此結果解讀為未來無法成長或轉型。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_14', 'A', 75, 100, '持續投入', '主動規劃並投入長期學習與技能更新，能自我驅動累積新能力。', '適合快速演進的職能環境與需要持續升級的角色。', '在終身學習動機上表現積極，會主動規劃學習路徑與資源，持續更新知識與技能，並尋找應用機會，讓學習能回饋到工作與個人發展。', '{"do": "可用於：①說明其在長期學習與自我成長上的驅動力，適合投入在變化快速、需要持續升級的角色②建議提供清楚的發展路徑與舞台，讓其看得到學習如何轉化為實際機會③提醒高學習動機不一定等於成果立刻可見，仍需在選題與聚焦上給予支持。", "dont": "禁止：①把高學習意願視為可以無限加派新任務與責任的理由②忽略其在時間與精力上的限制，期待「什麼都學、什麼都懂」③用學習熱度作為衡量其全部價值的唯一指標④將所有培訓與知識更新的責任完全轉嫁給個人。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_14', 'B', 50, 74, '需求導向', '在工作或角色需求出現時投入學習，學習節奏與外在需求連動。', '設定明確目標與應用場景，有助於提升成效。', '在有明確需求、角色轉換或環境變化時，會投入學習來補足所需能力，學習節奏多與工作要求或外在機會緊密連動。', '{"do": "可用於：①說明其學習傾向偏向「需求驅動型」，在看到用途與必要性時較易啟動②建議在制度上清楚連結學習與角色發展、績效或機會，以提升學習誘因③鼓勵在需求出現前，針對關鍵能力預做一些基本鋪陳，以降低未來壓力。", "dont": "禁止：①將此區間簡化為「不愛學習」②在沒有說明學習意義與用途的情況下，只要求完成訓練時數③忽略組織在設計學習機會與發展路徑上的責任④以分數評斷其未來發展上限。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_14', 'C', 0, 49, '維持現況', '較少主動追求新技能，偏好以既有能力完成任務。', '適合技能穩定、變動較少的角色。', '在現階段較傾向以既有知識與技能應對工作需求，較少主動投入長期或額外的學習計畫，更偏好在熟悉範圍內維持穩定表現。', '{"do": "可用於：①說明其目前重點在穩定運作與運用既有能力，適合在變動較低、技能要求較固定的情境②建議透過短小、明確且與現有工作高度相關的學習活動，降低進入門檻③強調此分數代表學習投入的優先順序，而不是否定其學習能力或未來發展可能。", "dont": "禁止：①貼上「不思長進」「不上進」等價值評斷②忽略組織在提供有吸引力的學習資源與清楚發展誘因上的角色③以比較或羞辱方式強迫參與學習，導致更高抗拒④用這個結果斷言其無法成長或不適合被培養。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_15', 'A', 75, 100, '整體連結', '能理解系統間相互影響，從整體角度看問題並預判連動效果。', '適合流程設計、跨部門協作與複雜議題盤點。', '在系統性思考上表現突出，能從整體結構與關聯角度審視議題，預先意識到一項決策對不同環節可能產生的連動影響。', '{"do": "可用於：①說明其在跨流程、跨部門或長期議題盤點上的優勢②建議投入於需要整體規劃、政策設計或路徑模擬的任務③提醒仍需搭配細節檢核，避免只停留在概念層次。", "dont": "禁止：①將其解讀為一定精通所有專業細節②僅因具整體觀就期待其獨自承擔複雜變革所有決策③以此作為忽略現場實務限制或基層聲音的理由④推論其必然適合所有策略職位。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_15', 'C', 0, 49, '單點聚焦', '思考多集中於單一面向，較少主動考慮系統連動與外溢影響。', '適合職責明確、界線清楚的任務配置。', '目前在系統性思考上較偏向聚焦單一面向或眼前任務，較少自然而然地延伸思考決策對其他環節或長期影響。', '{"do": "可用於：①指出其適合在職責清楚、分工明確的任務中專注執行②建議在關鍵決策前，安排與其他相關角色的討論或檢查清單，協助看見外溢影響③鼓勵逐步練習從「這一點」往外多問一兩層，而非一次要求全面系統掌握。", "dont": "禁止：①將此區間解讀為「眼光短淺」或「只顧自己」②忽略組織在資訊透明度與跨部門協作設計上的責任③以羞辱方式要求其立即具備高階策略視野④把此結果當作否定其參與重要專案的理由。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_16', 'A', 75, 100, '高度可靠', '能穩定兌現承諾，產出與行為高度可預期，團隊信任成本低。', '適合關鍵流程、交付責任與長期任務配置。', '在可靠性上表現穩定，能一貫地兌現承諾、如期完成交付，讓他人對其時間感與責任感有高度信任。', '{"do": "可用於：①說明其在長期任務、關鍵流程與客戶承諾上的信賴度優勢②建議擔任需要穩定交付與承諾管理的角色③提醒組織避免因可靠而持續加重其負荷，並留意資源與界線。", "dont": "禁止：①將其視為可以無限加派任務的對象②在整體流程設計不良時，把所有延誤責任歸於個人③忽略其休息與支持需求，以「你一向很可靠」要求超額付出④推論其可靠性等同於高效率或高產出。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_16', 'B', 50, 74, '條件可靠', '在目標清楚或流程明確時表現可靠，遇到模糊或變動時易波動。', '提供清楚優先序、時程與檢核節點可提升穩定性。', '在目標、流程與期望清楚時，多數情況能維持可靠的交付；但在需求模糊、變動頻繁或優先順序不明時，交付穩定度較容易受到影響。', '{"do": "可用於：①說明其可靠性與目標明確度、流程清晰度高度相關②建議透過優先順序、檢核節點與書面確認支援其穩定交付③鼓勵在不確定時主動詢問與確認，而非自己猜測。", "dont": "禁止：①把在混亂情境下的波動視為「個人不可靠」②忽視管理與流程問題，單純責怪個人③用分數評斷其不適合承擔關鍵任務④忽略其在結構良好環境中的穩定表現。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_16', 'C', 0, 49, '波動較大', '承諾與交付一致性不足，較容易受情境或狀態影響而延誤。', '適合拆解任務、短週期追蹤與更明確的交付標準。', '在交付穩定性上較具波動，承諾與實際完成之間可能會受到狀態、干擾或優先順序變動影響，較需要明確的排程管理與追蹤機制。', '{"do": "可用於：①指出其需要在任務拆解、時間管理與干擾管理上得到更多支援②建議運用短週期追蹤、明確交付標準與提醒機制來提升一致性③強調這反映的是節奏與管理方式需求，而非價值或意願的否定。", "dont": "禁止：①用「不可靠」「講話不算話」等貼標語言定義個人②忽視工作量、角色衝突與環境干擾等結構性因素③單靠責備或施壓期待其自動改善④以此結果否定其在適當支持下的成長可能。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_17', 'A', 75, 100, '精準嚴謹', '能維持高度專注與準確度，主動發現錯誤並確保品質一致。', '適合品質控管、資料處理、合規與高精度交付任務。', '在準確嚴謹度上表現優異，能長時間維持對細節的專注，主動發現錯誤或不一致之處，確保成果的品質與一致性。', '{"do": "可用於：①說明其在品質控管、審核與精細作業上的優勢②建議投入在資料處理、合規檢查或高精度要求的工作③提醒在追求精準的同時，也需與時程與效率做平衡。", "dont": "禁止：①以此期待其在任何情境下都零失誤②忽視工作量與時間壓力對細節品質的影響③將其嚴謹解讀為「挑剔」或人際問題④把注意細節等同於創意或大局思考不足。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_17', 'B', 50, 74, '重點把關', '能在重要環節把關細節，但在多工或時間壓力下容易忽略次要細節。', '以清單化、同儕檢核與分段交付可降低漏失。', '在關鍵環節與主要輸出上能注意到重要細節，但在多工、高壓或時間緊迫時，對次要細節的掌握度較容易下降。', '{"do": "可用於：①說明其能在重點環節發揮把關作用②建議透過清單、雙重檢核或分工，協助在忙碌時維持細節品質③鼓勵事先釐清「哪些地方一定要很精準、哪些可簡化」來分配注意力。", "dont": "禁止：①將偶爾的細節疏漏放大成「不嚴謹」的長期標籤②忽略組織在工時、排程與資源配置上的責任③在要求高精度時，卻不給予足夠時間與工具④以個別錯誤否定其整體專業度。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_17', 'C', 0, 49, '細節落差', '對細節敏感度較低，容易漏掉規格或小錯誤，需要更多檢核機制。', '適合搭配模板、標準作業與品質檢查流程。', '目前在細節覺察與檢核上較不敏銳，若缺乏標準化流程或檢查機制，較容易遺漏小錯誤或規格要求。', '{"do": "可用於：①指出其適合在標準作業清楚、已有檢核機制的情境下工作②建議導入模板、檢查清單與工具來降低錯誤率③鼓勵在關鍵文件或成果上安排同儕審閱，而非單獨承擔所有細節。", "dont": "禁止：①將此結果等同於「不在意品質」②用羞辱或嘲笑方式指出細節錯誤③忽略職務設計中對精確度的不合理期待④據此推斷其在其他能力面向上的價值。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_18', 'A', 75, 100, '清楚協調', '能清楚表達、理解他人並促進共識，溝通能兼顧內容與關係。', '適合跨部門協作、專案溝通與對齊共識的角色。', '在協調溝通上表現良好，能清楚表達想法、理解他人觀點並整理共識，兼顧資訊內容與關係維持，有助於降低誤解與衝突。', '{"do": "可用於：①說明其在跨部門協作、專案對齊與會議主持上的優勢②建議投入在需要整合不同利害關係人觀點的情境③鼓勵善用書面摘要與會後整理，放大其溝通貢獻。", "dont": "禁止：①將其視為理所當然的「溝通窗口」，卻未給予相應角色與資源②要求其在任何衝突中都扮演調解者③忽略組織制度與權力結構對溝通效果的影響④把溝通好等同於必須始終迎合他人。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_18', 'B', 50, 74, '任務溝通', '在工作需求明確時能有效溝通，但高壓或多工時需留意資訊遺漏。', '用議程、摘要與回覆確認可提升溝通品質。', '在任務明確、角色清楚的情境下，能有效傳遞資訊與回應需求；但在高壓、多工或議題較模糊時，資訊的完整度與一致性較容易產生落差。', '{"do": "可用於：①說明其溝通品質與情境條件的關聯②建議透過會議議程、會後紀錄與關鍵訊息重複確認來支援③鼓勵在不確定時多問一句、再複述一次對方的重點，以減少落差。", "dont": "禁止：①把情境造成的誤解一概歸因為「你溝通不好」②在資訊本身就不清楚的前提下，責怪個人沒有講清楚③忽略溝通管道過多、訊息碎片化等結構性問題④以一次溝通失誤否定其長期表現。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_18', 'C', 0, 49, '互動落差', '在複雜或情緒性互動中容易產生理解差異，互動一致性較不穩。', '適合搭配確認機制、書面化與回饋節點降低誤解。', '在複雜、多方或情緒性較高的互動中，較容易出現理解落差或訊息偏差，如缺乏確認機制，可能導致雙方期待不一致。', '{"do": "可用於：①指出其在人際溝通上需要更多結構化支持，如書面說明、確認問題與明確結論②建議在關鍵對話後寫下重點並請對方確認，以減少誤會③鼓勵在重要場合前先準備要說的重點，提高表達穩定度。", "dont": "禁止：①將其標籤為「不會溝通」「溝通有問題的人」②忽略情境、權力關係與文化對溝通行為的影響③以負面評價而非具體建議回應其表現④推論其不適合任何需要對人互動的工作。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_19', 'A', 75, 100, '策略協商', '能平衡利益、尋求雙贏並調整策略，面對衝突仍能維持合作。', '適合對外合作、關鍵協議與資源交換情境。', '在協商談判上表現成熟，能兼顧自身與對方利益，清楚表達立場與底線，同時維持合作關係，擅長尋找雙贏或折衷方案。', '{"do": "可用於：①說明其在價格、條件或資源協調上的優勢②建議投入對外合作、合約協調或內部資源分配等需要談判的情境③提醒談判仍需事前準備與資料支持，而非完全依賴臨場反應。", "dont": "禁止：①將其視為必須在所有衝突情境中出面處理的人②以此為由，把高度風險或壓力談判全數交給其負責③忽略團隊或組織在談判策略與立場設定上的責任④以短期結果評價其全部談判能力。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_19', 'B', 50, 74, '情境談判', '在準備充分或熟悉對象時表現佳，臨場變化大時較依賴框架。', '提供談判目標、底線與替代方案，可提升穩定度。', '在熟悉主題、準備充分或談判結構較清楚時，能有效表達訴求並爭取合理條件；但在臨場變動大或壓力較高時，較依賴事前框架與他人支援。', '{"do": "可用於：①說明其談判表現與準備程度高度相關②建議在重要協商前提供明確目標、底線、替代方案與常見問題回應③鼓勵在談判過程中適度暫停與回到團隊討論，而非勉強單獨承擔。", "dont": "禁止：①把在高壓即興情境中的不穩定表現簡化為「不會談」②要求其在完全沒準備的情況下處理關鍵談判③忽視組織在談判策略、資料與支援上的配置④以個別談判結果作為唯一評價依據。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_19', 'C', 0, 49, '讓步傾向', '衝突情境中較易退讓或避免對抗，可能錯失保護己方利益的機會。', '適合先設定底線與說法，並安排練習與支援。', '在衝突或利益拉鋸的情境中，可能傾向避免對立、選擇讓步以維持關係或降低場面壓力；或是可能以強勢進逼想贏過對方、沒有保留雙贏空間，，因此談判結果對己方在短期或長期可能遭受損失。', '{"do": "可用於：①說明其偏好低衝突與關係維持的談判風格②建議在進入協商前先設定清楚的底線、可讓步與不可讓步項目，並安排必要時可請他人協助發聲③鼓勵透過角色扮演或模擬練習，逐步提升在安全範圍內堅持立場或思考雙贏的能力。", "dont": "禁止：①將其描述為「沒有立場」「不敢發聲」②忽略其維持關係與降低衝突的正面價值③在完全沒有支持的情況下要求其獨自面對高風險談判④用結果指責其個性有問題或推論其不適合承擔責任。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_20', 'A', 75, 100, '審慎評估', '能檢視資訊可信度、比較不同觀點並避免過度直覺判斷。', '適合參與風險評估、決策審查與品質把關。', '在批判性思考上表現成熟，能檢視資訊來源與證據品質，對不同觀點進行比較，不會只依靠直覺或單一說法做決定。', '{"do": "可用於：①說明其在資料驗證、風險評估與決策審查上的優勢②建議投入需要檢視假設、看反例、拆解論點的任務，如專案審查、政策討論、風險委員會③鼓勵搭配清晰的評估標準與多元資料來源，讓其批判性思考轉化為具體決策建議。", "dont": "禁止：①將其批判能力解讀為「挑剔」「唱反調」②期待其在毫無資料的情況下仍能做出絕對正確判斷③用這個分數合理化過度否定他人或持續拖延決策④把質疑與提問視為不服從或負面態度。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_20', 'B', 50, 74, '選擇性檢視', '在關注重點明確時能進行判斷，但時間壓力下可能簡化評估流程。', '保留討論空間與反例檢核，有助避免單一觀點。', '具備一定批判性思考，當議題與重點清楚時，能針對關鍵資訊提出疑問與判斷；但在時間壓力大或資訊量過多時，較容易簡化評估流程。', '{"do": "可用於：①說明其批判深度會受時間與情境影響，在結構較清楚時表現較佳②建議透過簡化的檢核清單（如幾個固定問題）協助在壓力下維持基本評估品質③鼓勵在重大決策前預留短暫「停頓時間」，專門檢查假設與風險。", "dont": "禁止：①因為少數情境下評估不足，就簡化為「沒有批判能力」②在完全沒有時間與資訊支援的情況下要求其做深度風險分析③忽略議題複雜度與資訊品質，把所有判斷結果都歸因於個人能力④用一次錯誤推論其長期判斷力。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_20', 'C', 0, 49, '判斷依賴', '較容易依賴他人觀點或既有結論，較少主動質疑前提與證據。', '適合搭配審查機制、多元意見與推理框架訓練。', '目前較容易沿用現成結論或多數意見，較少主動檢查前提、證據與潛在風險，需要外部框架或他人帶領來啟動更深入的檢視。', '{"do": "可用於：①說明其目前較偏向依賴既有結論與權威意見，適合搭配清楚的評估步驟與示範②建議透過簡單的提問框架（例如「如果相反會怎樣？」「有沒有例外？」）逐步練習質疑前提③鼓勵在安全情境下練習提出不同觀點，而不是一次要求全面顛覆思考方式。", "dont": "禁止：①將此區間標籤為「沒在思考」「盲從」②忽視組織文化、權力結構與資訊不對稱對其判斷方式的影響③用羞辱或嘲諷方式要求其「要有批判性」④據此推論其不適合參與重要討論或決策。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_21', 'A', 75, 100, '情境洞察', '能讀懂社交線索與關係動態，並調整互動策略以促進合作。', '適合跨部門協作、客戶互動與橋樑型角色。', '在社交智商上表現良好，能讀懂場合氛圍與人際動態，敏感察覺權力關係與微妙變化，並調整溝通方式以維持合作與信任。', '{"do": "可用於：①說明其在關係經營、跨部門協作與客戶互動上的情境判讀優勢②建議擔任橋樑型角色，如專案協調、利害關係人管理或對外窗口③鼓勵在維持關係的同時，也適度表達真實立場，以避免過度迎合。", "dont": "禁止：①將其社交敏感度視為理所當然的隱形勞務②要求其在任何情境都優先照顧他人情緒而忽略自身界線③把「看得懂氣氛」等同於必須處理所有人際問題④用此分數推論其一定外向或喜歡高社交強度。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_21', 'B', 50, 74, '基本互動', '能在一般情境維持良好互動，但在複雜權力或衝突情境需要時間適應。', '清楚角色與關係結構、有助於提升互動穩定度。', '在一般職場互動中能維持良好關係，理解基本社交線索與角色分際；但在權力結構複雜、衝突較高或情緒張力大的情境中，較需要時間適應與額外資訊來判讀局勢。', '{"do": "可用於：①說明其社交智商多在「一般情境」表現穩定，在高複雜度場域需要更多脈絡支援②建議在重要會議或政治敏感議題前，提供關係地圖、角色說明與溝通重點③鼓勵在不確定時，採取多聽、多觀察與詢問建議的策略，而非急於表態。", "dont": "禁止：①因在少數複雜情境中不夠靈活，就貼上「社交遲鈍」標籤②忽略組織文化與權力關係對社交壓力的影響③期待其在沒有資訊與支持的情況下獨自處理高度政治性的互動④將社交表現與人格價值直接綁定。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_21', 'C', 0, 49, '線索不敏感', '對社交暗示或關係變化較不敏感，互動策略較固定，易產生落差。', '適合互動規則明確的環境；可用明確回饋降低誤解。', '在社交情境的細微線索（例如眼神、語氣、關係張力）上較不敏銳，互動風格偏固定，容易與他人對情境的解讀產生落差，需要更明確的規則、回饋與說明。', '{"do": "可用於：①指出其在「讀空氣」上需要更多明確線索與回饋，適合在互動規則清晰、期望透明的環境工作②建議同事與主管用直接、具體的方式說明期待，而不是依賴暗示③鼓勵個人透過詢問（例如「現在大家的顧慮是什麼？」）來補足情境理解。", "dont": "禁止：①將此結果簡化為「不懂人情世故」「情商低」②用嘲笑或排斥的方式回應其社交錯位③忽略組織在建立清楚規則與開放溝通文化上的責任④據此否定其在專業貢獻或工作成果上的價值。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_22', 'A', 75, 100, '果斷判斷', '能在資訊有限時做出決策並承擔結果，遇到變化能快速定案調整。', '適合需要快速反應、決策頻繁的角色與任務。', '在高效決策上表現突出，能在資訊不完全的情況下仍做出合理選擇，並在環境變化時快速調整決策方向，願意承擔結果並持續修正。', '{"do": "可用於：①說明其在需要即時反應、決策頻繁的情境（如營運調度、專案現場）上的優勢②建議搭配簡明的決策準則與事後檢討機制，讓快速決策持續優化③鼓勵在重大高風險議題上，加入他人觀點與檢核，以平衡速度與品質。", "dont": "禁止：①以其決策速度為由，鼓勵在關鍵議題上「先做再說」而忽略風險評估②將快速決策等同於衝動或一意孤行③期待其單獨扛起所有決策結果，而忽視團隊與組織的共同責任④把偶爾的錯誤放大為「判斷草率」的固定標籤。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_22', 'B', 50, 74, '審慎選擇', '傾向蒐集足夠資訊後再決策，決策品質穩定但速度受資訊完整度影響。', '設定時程與決策門檻，有助兼顧效率與品質。', '在有足夠資訊與時間時，能做出穩健的決策；傾向先蒐集資料、聽取意見再定案，決策品質通常不錯，但速度會受到資訊完整度與不確定程度影響。', '{"do": "可用於：①說明其傾向審慎決策、重視風險與證據，在穩定環境中特別適合負責重要判斷②建議在時程敏感的情境下，事先設定「資料夠多就要決定」的門檻與期限③鼓勵在資訊難以完全掌握的情況下，運用情境假設與試行方案，而非無限延後決策。", "dont": "禁止：①將審慎與遲疑混為一談，簡化為「反應慢」②忽視議題複雜度與風險，要求其在資訊不足時硬性加快決策③以單次決策延宕評價其整體工作效率④用壓力或羞辱方式逼迫其「快點決定」。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('ANI_22', 'C', 0, 49, '猶豫傾向', '面對多選項時較難快速定案，容易延後或反覆比較。', '提供選項排序、決策框架與期限，可協助定案。', '在面對多個選項或高度不確定的情境時，較容易陷入反覆比較或延後決定，擔心選錯帶來風險，因而需要更多結構化協助來推進決策。', '{"do": "可用於：①指出其目前在決策上偏向降低風險與避免後悔，需要清楚的決策框架（如利弊列表、優先順序）②建議透過設定決策期限、分階段決定（先小後大）來降低壓力③鼓勵在安全情境中練習「做出足夠好而非完美」的決策經驗，累積信心。", "dont": "禁止：①將其描述為「沒主見」「優柔寡斷」②忽略情境風險與過去經驗對其猶豫的影響③在沒有提供任何工具或支持的前提下，單純要求其「要果斷一點」④用這個結果否定其在分析、支持性角色或需要謹慎評估職務上的價值。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_01', 'A', 75, 100, '高度自律', '做事有一致的自我要求，能主動掌握進度、顧品質與收尾，較少需要外部催促也能維持可靠輸出。', '可交付需要穩定產出、長期追蹤、責任界線清楚的任務；適合擔任流程 owner、專案控管與交付把關角色。', '整體呈現高度自律與責任感，做事會主動掌握進度、照顧品質與收尾細節，即使沒有外在催促也能維持穩定輸出。', '{"do": "可用於：①說明其在自我管理、品質控管與長期專案追蹤上的穩定度②建議安排需要穩定產出、責任邊界清楚的任務或流程 owner 角色③鼓勵在維持高標準的同時，也留意工作量與身心負荷，避免過度投入。", "dont": "禁止：①把其盡責當成理所當然，不斷加派任務而不調整資源②將偶爾的延宕或失誤放大成「不負責」③以此分數假設其永遠不需要督導或回饋④把對細節的在意誤解為「愛挑別人毛病」。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_01', 'B', 50, 74, '任務可靠', '在目標、範圍與時程清楚時表現穩定；遇到優先序頻繁變動或責任邊界不清時，效率與投入度可能波動。', '以明確分工與里程碑提升穩定度；適合在既定流程內承擔主力執行與回報節點。', '面對目標、範圍與時程清楚的任務時，多能穩定完成並維持基本品質；當優先順序頻繁變動或權責模糊時，節奏與細緻度會跟著起伏。', '{"do": "可用於：①說明其表現高度仰賴任務清晰度與外部結構②建議透過明確分工、里程碑與定期 check-in，協助其穩定輸出③鼓勵其學會主動釐清優先順序與需求，而不是悶著做。", "dont": "禁止：①在目標本身就模糊的前提下，將所有落差歸因於個人「不夠負責」②用零星案例貼上「時好時壞」的標籤③忽略管理與流程設計的責任，把結構問題丟給個人扛④期待其在混亂環境中依然維持完全同樣的表現。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_01', 'C', 0, 49, '節奏支援', '較容易受情境或情緒影響而出現拖延、鬆散或收尾不足；不是做不到，而是自我監控與維持節奏較吃力。', '搭配短週期拆解、檢核清單、同儕回報機制；先讓完成穩定，再逐步拉高品質。', '執行節奏容易受情緒、環境或干擾影響，偶爾會出現拖延、鬆散或收尾不足的情況，能力並非不足，而是在自我監控與維持節奏上較吃力。', '{"do": "可用於：①指出其需要更多外部化工具（如任務拆解、檢核清單、固定回報節點）來穩定輸出②建議先把「準時完成」與「不漏掉」當成第一優先，再逐步拉高品質標準③鼓勵與主管或同事一起設計適合自己的節奏，而不是單靠意志力撐。", "dont": "禁止：①直接標籤為「懶散」「不可靠」②忽略工作量、干擾度與專注環境對其表現的影響③用羞辱或比較的方式要求「要自律一點」④將此分數視為否定其能力或潛力的理由。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_02', 'A', 75, 100, '卓越進取', '對表現與成果有明顯企圖心，願意多投入以達到更高標準，遇到挑戰傾向主動升級方法與目標。', '適合高挑戰、高成長、需要拉高標準的任務；可作為衝刺型角色。', '對表現與成果抱持強烈企圖，會主動拉高標準、尋找挑戰，願意投入額外心力追求更出色的成績。', '{"do": "可用於：①說明其在目標導向與追求成就上的動能，可作為衝刺型或關鍵任務的主力②建議搭配清楚的成長與回饋機制，把努力和成果連結清楚③提醒在高成就傾向下，也要留意休息與界線，避免過勞或過度自責。", "dont": "禁止：①以其成就動機為由，不斷加壓或延長工時③忽略資源不足、流程問題，只用「你應該更努力」回應落差③將短暫倦怠解讀為「不再上進」④把個人績效完全與人格價值綁在一起。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_02', 'B', 50, 74, '目標驅動', '在目標清楚、回饋可見時會穩定投入；若缺乏指標或看不到進展，動能容易下降。', '以 KPI/OKR、里程碑與可視化進度維持續航；適合中長期專案的穩定推進者。', '對達成目標有穩定重視，當目標具體且看得到成果時，會願意投入努力；若缺乏指標或看不到成效，動能就比較容易下降。', '{"do": "可用於：①說明其動機多與「目標清晰度、意義感與回饋」連動②建議在專案初期一起定義具體指標與節奏，並提供可見的進展回饋③鼓勵其主動提出自己在成就與發展上的期待，避免陷入被動。", "dont": "禁止：①將此區間簡化為「不上進」或「沒企圖心」②在缺乏方向與資源時，用壓力或比較逼其多做③忽略職務設計與獎酬機制對動機的影響④用單一時期的低動力推論其長期表現。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_02', 'C', 0, 49, '穩定達標', '傾向把工作完成在合理範圍，不一定追求更高難度或額外突破；動機更受環境支持與要求牽動。', '適合明確職責、節奏固定的工作；若期待突破，需提供動機意義與可達成的成長路徑。', '整體行事風格偏向穩穩完成要求，對「超標」「突破」的追求較弱，更傾向在合理範圍內把事情做完即可。', '{"do": "可用於：①說明其適合在穩定執行與支持性角色中貢獻，而不宜期待高度競賽式表現②建議將其放在需要穩定完成、而非持續衝高指標的工作內容③鼓勵透過探索「自己覺得有成就感的事」來建立屬於自己的成就定義。", "dont": "禁止：①貼上「不求上進」「躺平」等道德化標籤②忽略職務匹配與成就感來源差異③用高壓業績文化要求其表現出強烈競爭性④將此分數當作否定其職涯發展可能的依據。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_03', 'A', 75, 100, '先思後行', '行動前會評估風險、假設與後果，較少因一時判斷造成返工；在不確定情境能維持判斷品質。', '適合風險控管、決策審查、流程把關與合規情境；可擔任決策前最後一道檢核。', '做決定前習慣先思考情境、風險與可能結果，面對不確定時也能維持判斷品質，不會輕易被一時情緒帶走。', '{"do": "可用於：①說明其在風險評估、策略討論與重要決策上的價值②建議投入錯誤成本高、需要深思熟慮的議題（如人事、合約、長期投資）③鼓勵在已充分思考的情況下，為行動設下明確時限，避免過度拉長決策。", "dont": "禁止：①將其審慎誤解為優柔寡斷②要求在資訊高度不足又風險極高時，仍「秒回決定」③忽略議題複雜度與資訊量，只用決策速度評論其能力④把多問幾句當成「找麻煩」。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_03', 'B', 50, 74, '情境權衡', '在重要決策會拉高審慎程度，但在時間壓力或熟悉任務可能簡化評估；品質受情境影響較大。', '提供決策模板（選項/風險/影響/備案）穩定發揮；適合在快慢要切換的團隊中。', '重要事情會刻意拉慢節奏、多想一下；對熟悉或看似小事的議題，則傾向簡化評估、快速做決定，實際謹慎程度會依情境調整。', '{"do": "可用於：①說明其會依照「重要性」調整審慎程度②建議針對關鍵領域（如人員、預算）設定最基本的思考檢核點③鼓勵在「看似日常但影響深遠」的議題上，也保留一些審慎空間。", "dont": "禁止：①因為個別錯誤就說「都想不清楚」②忽略時間壓力、資訊不足等外因③用完美主義標準要求其所有決策都零失誤④把一兩次的疏忽視為長期固定問題。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_03', 'C', 0, 49, '行動先行', '傾向先做再調整，評估常在行動後補上；在快速節奏下能衝刺，但也較容易忽略隱性風險。', '搭配快速檢核點與同儕 review 降低返工與踩雷；適合需要速度的工作。', '做事風格偏向「先做再說」，經常先行動再在過程中修正，對事前評估風險與前提的時間相對較少，在快速環境能推進，但也較容易忽略隱藏問題。', '{"do": "可用於：①指出其在需要快速試錯、敏捷調整的情境中具行動優勢②建議在高風險或一次性決策前，設置簡單的「停一下先想」流程③鼓勵與較審慎的同事搭配，在速度與風險之間互相補位。", "dont": "禁止：①直接貼上「莽撞」「沒在想」的標籤②忽略制度、時程與壓力對其行動風格的影響③只用事後責備處理錯誤，而不提供前期支援④把此分數當作否定其判斷力的理由。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_04', 'A', 75, 100, '規範堅守', '高度重視承諾、規則與責任邊界，遇到灰色地帶也傾向選擇可被交代、可被信任的做法。', '適合合規、資安、機敏資料等高度信任情境；可放在制度與文化的穩定器位置。', '對承諾、規則和職責界線有強烈重視，遇到灰色地帶時，也會傾向選擇站得住腳、講得清楚的做法。', '{"do": "可用於：①說明其在守信、合規與高度信任情境中的重要性②建議安排需高度可靠與可追溯性的任務（如合約控管、稽核、長期客戶關係）③鼓勵在堅守原則的同時，也學習與組織討論不合理規範。", "dont": "禁止：①把其義務感當成免費勞力，不斷追加責任②用「你有責任」掩蓋制度或資源問題③期待其為了組織利益長期犧牲個人健康與生活④在其提出合理界線時，批評為「不夠有責任感」。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_04', 'B', 50, 74, '規則導向', '大多遵守規範，但在資源不足或目標衝突時會尋求折衷；通常需要明確指示什麼不能動。', '把不可妥協底線講清楚，其餘留彈性可提升效率與配合度。', '大多數情況會遵守規範與承諾，但在資源不足、規則矛盾或多重目標拉扯時，會尋找折衷作法，希望在「守規矩」與「把事情做成」之間取得平衡。', '{"do": "可用於：①說明其在實務現場會同時顧及原則與效率②建議清楚界定「真的不能動的底線」，其他部分保留彈性空間③鼓勵當規範與目標衝突時，用對話尋找更好的做法，而非悶著承擔。", "dont": "禁止：①把情境下的權衡解讀為「沒有責任感」②忽略制度設計與資源條件對行為的限制③用單一事件批評其立場不堅定④要求其在沒有任何空間與支援下，仍獨自扛起所有義務。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_07', 'B', 50, 74, '品質平衡', '在重要任務會提高標準，但能在時間/資源限制下做取捨；品質與效率之間較能取得平衡。', '採分級品質策略（關鍵件高標、一般件可接受）能發揮最大效益；適合專案推進。', '在重要任務上會希望成果好看、站得住腳，但也能在時程或資源有限時接受「足夠好」，不會在所有細節上都追求極致。', '{"do": "可用於：①說明其在品質與效率之間的彈性拿捏②建議在專案啟動時就與團隊對齊品質標準與優先順序③鼓勵維持這樣的平衡，而不是被環境推向過度完美或過度隨便。", "dont": "禁止：①因為不「事事追求極致」就說「不夠用心」②忽略限制條件（時間、人力、資訊）③用他人極端完美標準要求其配合④將小失誤解讀為態度不佳。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_04', 'C', 0, 49, '彈性取捨', '較容易把規範視為可調整的工具，遇到目標壓力可能優先選擇結果導向做法，需要較強的底線提醒。', '以雙人覆核、紀錄透明、權限控管等制度降低風險；適合創新但需控風險。', '面對規範時較常以「工具」而非「原則」來看待，遇到壓力或目標強烈時，容易優先選擇對結果有利的做法，需要更清楚的底線提醒與制度控管。', '{"do": "可用於：①指出其在需要彈性、突破與實作導向的情境中具優勢，但需設好界線②建議透過權限控管、雙人覆核與紀錄透明來降低風險③鼓勵在追求結果的同時，也思考長期信任與風險成本。", "dont": "禁止：①直接標籤為「沒原則」「會亂來」②忽略目標壓力與制度缺陷對其選擇的影響③完全用道德指責代替制度設計④把此分數當作預測其必然違規或不誠信。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_05', 'A', 75, 100, '自制穩定', '能管理情緒與衝動反應，在壓力下仍維持一致行為與判斷，不易因一時情緒做出高代價決定。', '適合高壓、客訴、談判等需要穩定情緒輸出的角色；可作為團隊情緒穩定器。', '衝動與情緒來時，多半能先踩煞車、評估一下後果，再決定要不要說或要不要做，短期誘惑不容易完全蓋過長期考量。', '{"do": "可用於：①說明其在情緒管理、風險行為與重要承諾上的穩定度②建議在需要冷靜判斷與高自制的角色中善用此特質③鼓勵在自我壓抑與健康表達之間找到平衡，不必永遠當「情緒黑洞」。", "dont": "禁止：①把其穩定當成無限承受情緒與壓力的理由②忽略其內在耗損，只期待「你一定撐得住」③批評偶發情緒失控為「不應該」而不看長期表現④把高自制等同於不需要支持。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_05', 'B', 50, 74, '情境波動', '一般狀態自制力良好，但在連續高壓、衝突或睡眠不足時，反應可能變快、語氣變硬或耐心下降。', '建立高壓期節奏（輪班、緩衝、降噪）與復盤機制；在有支持系統下承擔前線任務。', '平時多能控制自己的反應與衝動，但在長期壓力、嚴重疲勞或連續挫折的情況下，情緒與行為有時會一時失衡。', '{"do": "可用於：①說明其衝動管理與壓力、體力高度連動②建議建立壓力預警機制（例如自覺快爆時先暫停決定）③鼓勵在事後檢討時，把重點放在調整做法，而不是單純自責。", "dont": "禁止：①只用單一事件否定其平常的自制力②忽略制度與工作負荷對其情緒穩定的影響③以「你不可以這樣」作為唯一回應，而不討論實際調整策略④把情緒反應視為人格缺陷。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_05', 'C', 0, 49, '衝動風險', '較容易被情緒推著走，出現衝動回應、倉促承諾或行為過頭；事後常需要修補或解釋。', '降低高衝突暴露、提供情緒停損流程（先暫停/先寫後說/第三方介入）；用規範保護本人與團隊。', '當情緒被挑起或短期誘惑出現時，較容易順著當下感覺行動，事後才意識到後果或產生懊惱，需要更多「多一拍思考」的協助與設計。', '{"do": "可用於：①指出其在衝動管理上需要具體的環境與流程輔助（例如預設等待時間、找人商量）②建議設計簡單的自問機制，如「這樣做之後一週後我會怎麼看？」③鼓勵用負責但不自我否定的方式看待過去失誤，從中練習新的反應模式。", "dont": "禁止：①貼上「沒自制力」「不成熟」的標籤②忽略壓力、情緒與環境刺激對行為的影響③單靠責罵或羞辱要求其改變④將此分數與任何臨床診斷畫上等號。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_16', 'A', 75, 100, '目標路徑清晰', '能把目標具體化，並同時具備推進動機與替代路徑思考；遇到阻礙時能改道而不放棄。', '適合策略化推進、拆解路徑與持續優化的任務；可負責專案規劃與排除障礙。', '對未來有相對清晰的目標感，也能思考多條可行路徑，遇到阻礙時傾向調整做法而不是放棄方向。', '{"do": "可用於：①說明其在目標設定與路徑規劃上的優勢②建議參與中長期計畫與改善專案的設計與推進③鼓勵在修正路徑時，同步檢視目標是否仍符合自身價值與現實。", "dont": "禁止：①期待其永遠保持清晰方向、從不迷惘②用「你不是很有目標嗎」壓過其目前困境③忽略資源與外部環境對達成目標的影響④將短暫失去動力視為不被允許。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_06', 'A', 75, 100, '流程有序', '偏好清楚流程與例行節奏，能把資訊分類、把任務排程並維持一致做法，降低遺漏與混亂。', '適合流程設計、營運管理、專案行政與品質控管；可建立團隊共通作業標準。', '對秩序與結構有明顯偏好，會主動整理流程、資料與環境，讓事情有條有理地進行，以降低遺漏與混亂。', '{"do": "可用於：①說明其在流程整理、檔案管理與專案規畫上的貢獻②建議擔任需要維持秩序與結構的角色（如 PM、系統整理、SOP 設計）③鼓勵在需要彈性的情況下，也允許自己保留部分「尚待探索」空間。", "dont": "禁止：①把其對條理的堅持解讀為「龜毛」「難相處」②忽略組織本身的混亂對其壓力的影響③期待其單獨扛起全部整理和制度化工作④把偏好秩序等同於缺乏創造力。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_06', 'B', 50, 74, '重點整理', '會整理重點與基本秩序，但不一定每件事都系統化；在多工時需要工具或提醒來維持條理。', '提供共用看板、固定回報節點與簡單模板即可顯著提升；適合兼顧彈性與秩序的型態。', '在重要事情上會維持基本的規畫與整理，但不會追求所有事物都高度結構化，會依情境在「順手」與「有系統」之間調整。', '{"do": "可用於：①說明其在條理與彈性間具有一定平衡感②建議透過簡單工具（行事曆、任務清單）維持必要結構③鼓勵在多人協作或關鍵專案時，稍微提高條理程度以避免資訊遺漏。", "dont": "禁止：①因為不「極度整齊」就認定其沒有組織能力②忽略系統與工具本身的限制③用單次檔案找不到的狀況否定其整體工作風格④在未提供任何支援的情況下要求高度紀律整理。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_06', 'C', 0, 49, '彈性隨性', '較不靠固定流程工作，容易臨場處理；彈性高但也可能出現紀錄不足、交接不清或遺漏細節。', '設定最低限度的紀錄與交付格式（不求完美，求可追溯）；適合探索或外部開發。', '對固定流程、分類與整理沒有太強的內在動機，習慣依當下需求與感覺處理事物，資訊與物品較容易分散，需要「最低限度的秩序設計」來避免影響工作。', '{"do": "可用於：①指出其在創意發想或需要靈活應變的工作中可保有彈性，但在大量資訊情境需要外加結構②建議從關鍵檔案與重要流程開始，建立最基本的整理規則③鼓勵逐步加入「讓自己少找東西」的小習慣，而不是一次要求全面大改。", "dont": "禁止：①直接貼上「邋遢」「沒組織」的標籤②忽略工作環境、工具與流程本身的雜亂③在未給予任何結構支援下，要求與高度條理者一樣的標準④以此分數否定其在專業或創意上的價值。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_07', 'A', 75, 100, '品質苛求', '對細節與品質要求高，會反覆檢查與優化以達到無瑕疵；在高標準場景能顯著提升可靠度。', '適合品質把關、重要交付、品牌/法遵/對外文件等；可作為最後審稿者。', '對成果品質與細節有高度在意，容易把標準拉在相對嚴格的位置，會不斷微調、修正，直到接近心中理想狀態。', '{"do": "可用於：①說明其在品質控管與精緻輸出上的優勢②建議在關鍵輸出（如對外簡報、正式文件）善用其高標準③鼓勵一開始先區分「需要完美」與「夠好就好」的情境，避免耗損過多心力。", "dont": "禁止：①把其完美傾向視為無限壓榨的理由②忽略時間與資源限制，只要求結果「零失誤」③用個別小缺點否定整體努力④鼓勵長期熬夜或超時工作來維持完美表現。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_07', 'C', 0, 49, '完成優先', '更重視推進與交付，細節品質通常做到可用即可；在快速迭代場景有效率，但可能忽略小錯累積。', '適合 MVP、試點、快速產出；需搭配檢核/測試/他人 review 避免品質風險放大。', '對小細節瑕疵的容忍度較高，做事更在意整體完成與可運作，而不會為了打磨到完美而卡住進度，偏向「先有再優化」的風格。', '{"do": "可用於：①指出其在快速迭代、原型開發或試錯情境中具有優勢②建議搭配對細節敏感的成員，共同平衡整體品質③鼓勵在重大、一次性輸出時，稍微拉高檢查標準以降低風險。", "dont": "禁止：①把這種風格直接等同於「隨便」「沒品質概念」②忽略職務本身是否真需要極高完美標準③在未說清楚品質期待前事後責怪④以單一缺失否定其整體貢獻。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_08', 'A', 75, 100, '勝任自信', '對自身能力與掌控感較有信心，遇到挑戰願意承擔並主動找方法；較少因不確定而退縮。', '適合需要自主判斷、獨立推進與對外代表的角色；可賦予較高授權與主責範圍。', '普遍對自己的能力與影響力抱持信心，相信只要有時間與資源，大多數挑戰都能找到解法並處理好。', '{"do": "可用於：①說明其在承接新任務、面對變動與帶頭嘗試方面的優勢②建議提供具挑戰但可達成的機會，讓其把勝任感轉化為實際成果③提醒在高自信下仍要留意資源與現實限制，避免壓力累積。", "dont": "禁止：①把其自信當成不需支援的理由②在結果不理想時，用更高標準回頭指責「你不是很有能力嗎」③期待其一個人扛起所有困難專案④將自信與自負簡化為同一件事。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_08', 'B', 50, 74, '需要確認', '能力多半足夠，但在新領域或高風險任務會希望獲得確認；得到支持後能穩定輸出並逐步建立信心。', '提供可求助窗口、階段性肯定與清楚成功標準能快速拉升；適合導師制或同儕合作下成長。', '面對熟悉或曾經成功過的任務時，普遍有一定把握；遇到全新、複雜或風險較高的挑戰時，會在意資源、支援與方向是否明確。', '{"do": "可用於：①說明其勝任感與經驗、準備程度及環境支持高度連動②建議在新任務前提供清楚目標、學習資源與可詢問對象③鼓勵回顧自己過去克服困難的經驗，讓信心不只綁在熟悉領域。", "dont": "禁止：①把謹慎與確認解讀為「沒信心」②忽略制度、資訊與支援不足對其心理狀態的影響③只用「你要相信自己」簡化問題④用單一挫敗經驗否定其能力。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_08', 'C', 0, 49, '信心不足', '容易懷疑自己是否能做好，遇到不確定任務可能遲疑或依賴他人決定；需要更多安全感才敢推進。', '以小步成功累積並提供明確指引與正向回饋；避免一開始就丟高風險責任。', '面對挑戰時較容易先想到「我可能不行」或「別人比較適合」，對自己能否處理好事情的把握度較低，需要更多具體支持與成功經驗累積。', '{"do": "可用於：①指出其在勝任感上需要更多具體回饋與小步成就來建立自信②建議主管在分派新任務時拆小步驟、給清楚指引與即時肯定③鼓勵其將「沒做過」與「做不到」分開看，避免預先放棄。", "dont": "禁止：①貼上「沒自信」「太弱」的標籤②忽略過往負面回饋或失敗經驗對其信心的影響③用嘲諷或比較逼其「振作」④依此分數斷定其不適合作為培養對象。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_09', 'A', 75, 100, '延宕誘惑', '能為了長期目標延遲滿足，面對短期誘惑仍可維持節奏與自我約束，較少因一時舒服而偏離計畫。', '適合長期推進、重複投入與自我管理任務；可交付需要持續交付的工作。', '能長期維持自訂節奏，為了重要目標安排時間、抗拒短期干擾，即使沒有人盯，也會自己推進到位。', '{"do": "可用於：①說明其在長期專案、自我成長與習慣養成上的穩定度②建議安排需要持續投入與高度自主管理的任務③鼓勵在自律與彈性之間保留調整空間，避免把自己綁太死。", "dont": "禁止：①把其自律當成無限加工作量的理由②忽略其同樣會感到疲憊與需要休息的事實③將偶爾鬆動解讀為「變懶」④假設其完全不需要外在支持系統。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_09', 'B', 50, 74, '情境自控', '在目標清楚或環境支持下能維持自律，但在壓力大、干擾多或缺乏回饋時，容易出現鬆動與拖延。', '用短週期里程碑與外部承諾機制（回報、共學、檢核點）提升持續性。', '在有期限、有人一起推進或會被檢核的任務上，多能穩定完成；對完全自訂、沒人關心的長期目標，則較容易被日常瑣事打斷。', '{"do": "可用於：①說明其自律表現與外在結構（時程、檢核、他人參與）高度相關②建議透過結伴、定期回顧或公開承諾來支援長期目標③鼓勵將大目標拆小步驟，減少拖延與中斷。", "dont": "禁止：①把需要外在結構的特性簡化為「沒意志力」②忽略制度與工作設計對行為的影響③只用指責回應延誤，而不協助重整計畫④用短期狀態推論其長期人格特質。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_09', 'C', 0, 49, '短期拉扯', '較容易被短期誘惑牽動，明知道長期目標重要仍可能在當下選擇立即回報；自律維持較吃力。', '拆小任務、降低啟動成本並用環境設計減少誘惑；以明確獎勵建立習慣。', '在維持固定節奏與長期計畫上較有難度，行動常受當下心情、突發事件或環境干擾影響，計畫與實際執行之間容易出現落差。', '{"do": "可用於：①指出其在需要高度自律的任務中，必須透過工具與環境設計來補強②建議採用「短時段、短目標、多次重新開始」的方式，而不是一次逼自己完美堅持③鼓勵尋找適合自己的支持系統（例如夥伴約定、提醒工具）。", "dont": "禁止：①批評為「沒自制」「不長進」②忽略心理狀態、壓力或生活變動對執行力的影響③要求一次性徹底改變而不提供漸進方案④以此分數否定其負責任或成長的可能性。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_10', 'A', 75, 100, '誠正節制', '在利益與目標可見的情境下仍能維持誠懇與公正，對財富、地位與特權不會過度執著，也較少炫耀或佔便宜。', '適合需要高度信任的工作（資源分配、敏感資訊、合規與治理）；可作為文化示範者。', '整體價值觀傾向重視誠實、公平與謙遜，對貪圖不當利益、濫用特權或炫耀地位較為排斥。', '{"do": "可用於：①說明其在信任、倫理與風險控管上的重要性②建議安排在需要高度誠信與長期信賴的職務（如金流、合約、關鍵客戶）③鼓勵組織在制度與文化上與其價值相符，減少價值衝突感。", "dont": "禁止：①以其高誠實謙遜為由，忽視公平報酬與合理待遇②在制度不公時只要求個人「要有道德」③把其視為可無限承受價值衝突的防火牆④假設其永遠不會做出錯誤判斷。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_10', 'B', 50, 74, '原則彈性', '多數時候能維持公平與誠實，但在強壓績效或利益衝突下，可能在達標與原則間做權衡。', '把不可妥協底線講清楚（利益揭露、流程透明），並提供可行達標路徑。', '整體而言重視誠實與公平，但在壓力大、競爭激烈或灰色地帶情境中，會同時在意現實與原則，試圖在兩者之間找平衡。', '{"do": "可用於：①說明其價值觀與現實考量之間的拉扯狀態②建議組織釐清倫理底線與可接受做法，減少個人單獨承擔的壓力③鼓勵在困惑情境中透過對話，而不是獨自吞下矛盾。", "dont": "禁止：①因其猶豫或折衝，就貼上「不誠實」標籤②忽略文化、獎酬與權力結構對行為的影響③用道德壓力掩蓋制度缺陷④把單一次的妥協視為長期人格問題。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_12', 'A', 75, 100, '重價值不重物', '相對不把財富與地位視為主要追求，決策更看重意義、成長或關係品質，較不易被物質誘因牽動。', '適合使命導向或長期投入工作；激勵方式偏成就感、自主與成長資源。', '對金錢、頭銜與外在排場的重視度相對較低，更傾向用意義感、關係與內在成就感來衡量一份工作值不值得。', '{"do": "可用於：①說明其在追求有意義工作與內在報酬上的傾向②建議以成長機會、影響力與價值實現作為重要激勵來源③提醒組織仍須提供公平報酬，避免以「使命」為由忽略基本待遇。", "dont": "禁止：①以其低物質傾向為藉口壓低薪資或福利②用「你不是不看重錢嗎」來逼其接受不合理條件③假設其完全不在意物質生活品質④忽略其對基本安全感的正當需求。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_10', 'C', 0, 49, '利益傾斜', '較容易重視利益、地位或外在象徵，可能合理化先拿到再說的做法，對公平與謙遜的自我要求較弱。', '在規範清楚、權限可追溯的環境運作；加強監督、審核與利益衝突管理。', '對財富、特權與自身利益的重視度較高，在作決定時容易優先考量「對自己是否划算」，對利用規則邊界或強調自身地位的接受度較高。', '{"do": "可用於：①指出其在強競爭、高獎酬環境中可能具有推進成果的動力，但需要明確的倫理與合規框架②建議透過制度設計與監督機制，界定可接受與不可跨越的行為界線③鼓勵其思考長期信任與聲譽對自身利益的影響。", "dont": "禁止：①直接將其等同於「不誠實」「會做壞事」②忽略組織獎勵結構對價值偏移的影響③以羞辱方式處理價值議題，而不提供具體標準與討論空間④把此分數視為其必然會違法或嚴重失當的預測。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_11', 'A', 75, 100, '直率不操弄', '較少為了達成目標去操縱或欺騙他人，溝通偏直接透明，傾向用真實資訊建立合作。', '適合互信與長期合作情境（跨部門、客戶關係、治理）；可降低猜疑與內耗。', '在人際互動上偏好以真誠、直接的方式溝通，不太傾向刻意操弄、隱瞞或欺騙他人來達成目的。', '{"do": "可用於：①說明其在建立深度信任與長期關係上的優勢②建議讓其參與需要穩定、真誠互動的合作與夥伴關係管理③鼓勵在保持誠懇的同時，也學會適度保護自己，不被過度要求透明。", "dont": "禁止：①期待其在任何情境都完全坦白而不顧自身風險②忽略組織政治與權力現實③將必要的策略性表述誤解為不誠懇④把偶爾的保留視為人格反轉。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_11', 'B', 50, 74, '策略拿捏', '多數時回應誠懇，但在競爭、壓力或政治情境中，可能用較策略性的表達方式保護自身立場。', '提供清楚溝通規範（哪些可保留、哪些必須公開）與協作準則，維持信任又不失彈性。', '整體不偏好欺騙或操弄，但在敏感、權力不對等或關係脆弱的情境中，會斟酌要說多少、怎麼說，以兼顧真實與關係。', '{"do": "可用於：①說明其在誠懇與情境顧慮之間維持某種平衡②建議釐清組織對資訊透明與保密的實際期待，降低個人壓力③鼓勵在不安時尋求對話，而不是一味壓抑或過度隱瞞。", "dont": "禁止：①把策略性保留一概解讀為「不老實」②忽略法律、商業機密與角色責任對發言空間的限制③用理想化標準要求其在任何情境完全透明④用單一事件否定其整體誠懇度。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_11', 'C', 0, 49, '目的導向', '較容易把包裝或操弄視為達成目標的工具，可能選擇性揭露或用話術影響他人判斷。', '需在透明流程與稽核機制下運作；在客戶/治理領域需更嚴格行為規範。', '對於「只說對自己有利的一部分」或美化資訊的接受度較高，溝通常被視為推進目標的工具，而非單純交換真實狀態的管道。', '{"do": "可用於：①指出其在談判、銷售與需要強勢說服的場域可能具優勢，但須留意長期信任與誠信風險②建議透過明確規範與例外情境說明，界定不能被犧牲的誠信底線③鼓勵其思考「短期成交」與「長期信任」之間的取捨。", "dont": "禁止：①直接等同於「騙人」「不可信」②忽略組織本身對短期成效的高度壓力③只用道德批判要求其改變，而不提供具體示例與學習資源④用此分數斷言其一定會嚴重違反誠信。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_12', 'B', 50, 74, '務實平衡', '能理解物質與地位的重要性，但不會完全被其主導；會在價值、生活需求與回報之間做合理取捨。', '清楚薪酬制度與可見成長路徑最有效；也能接受績效激勵但需要公平透明。', '既重視合理薪酬與生活品質，也會把工作內容、成長空間與環境氛圍納入考量，在物質與非物質報酬之間尋求平衡。', '{"do": "可用於：①說明其在評估機會時會綜合考慮多面向②建議在職涯溝通時，同時談報酬、發展與意義感③鼓勵其清楚表達對薪資與環境的期待，而不是壓抑需求。", "dont": "禁止：①將對合理報酬的要求貼上「現實」「勢利」標籤②忽略市場行情與貢獻價值③只用理想或使命感要求其忽略物質條件④用此分數評價其人格高低。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_12', 'C', 0, 49, '高度物質導向', '較重視財富、地位或外在象徵，對回報敏感，可能把物質激勵視為投入與忠誠的主要交換條件。', '適合獎酬明確、成果可量化角色；避免模糊承諾，並以公平制度降低比較摩擦。', '對薪酬、福利、頭銜與外在認可的敏感度較高，容易把這些視為「有沒有被重視」的重要訊號，物質與地位在決策中占較大比例。', '{"do": "可用於：①指出其在獎酬明確、競爭導向的環境中可能動機強勁②建議清楚解釋薪酬架構、升遷條件與獎勵機制，減少不確定感③鼓勵其同時培養對內在成就與專業成長的重視，讓滿足來源更穩定。", "dont": "禁止：①直接貼上「拜金」「很勢利」的標籤②忽略其過往可能被低估或不公平對待的經驗③用道德批評否定其對物質條件的要求④把此分數當作預測其一定會為利益犧牲原則的依據。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_13', 'A', 75, 100, '原則守公平', '即使想領先或達成目標，仍傾向拒絕欺騙、偷竊、貪污或利用他人的手段，重視對等與規則一致。', '適合資源分配、制度設計、採購與治理等角色，提升信任與長期穩定。', '對公平與正義有強烈敏感度，對欺負弱勢、作弊或佔他人便宜的行為常會感到不舒服，傾向維護制度與互動中的公正。', '{"do": "可用於：①說明其在維護制度正當性與團隊公信上的重要性②建議在流程設計、規則檢討與倫理議題中納入其觀點③提醒在高度不公情境下，其挫折與憤怒感可能更強，需要支持與對話空間。", "dont": "禁止：①把其對公平的堅持視為「不識相」或「太理想」②忽略組織結構與決策不透明對其壓力的影響③期待其單獨扛起對抗不公的任務④因其提出質疑就標籤為「麻煩人物」。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_13', 'B', 50, 74, '情境權衡', '大多願意遵守公平規則，但在強烈競爭或目標壓力下可能出現擦邊球心態，視環境容忍度調整行為。', '明確規則與後果（紅線、稽核、透明），並提供可行達標方法避免手段化。', '原則上不贊同不公平的作法，但在權力不對等、風險較高或氛圍緊繃的情境中，有時會選擇觀望、沉默或有限度表達。', '{"do": "可用於：①說明其在價值與安全感之間的拉扯②建議建立安全管道（如匿名回饋、正式申訴流程），降低其發聲成本③鼓勵其在可掌握的範圍內練習表達，逐步累積為公平發聲的經驗。", "dont": "禁止：①把沉默直接解讀為「贊同不公」②忽略權力結構與心理安全感不足③用「你怎麼不早說」責怪其沒出聲④將一次沉默視為長期價值觀問題。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_13', 'C', 0, 49, '手段傾向', '較容易把領先視為第一順位，可能合理化不公平手段或利用他人換取優勢。', '高風險領域需加強權限控管、雙人覆核與稽核；角色配置宜更謹慎。', '對「世界本來就不會完全公平」這件事接受度較高，傾向優先確保自己不吃虧，對制度或利益分配不均的敏感度相對較低。', '{"do": "可用於：①指出其在高度競爭或差異報酬環境中可能較能適應，但也存在關係與文化風險②建議明確說清楚組織不可違反的公平底線③鼓勵其思考長期合作、信任與團隊士氣對結果的影響。", "dont": "禁止：①直接貼上「沒良心」「沒是非」標籤②忽略其可能曾經歷長期不公平而產生的防衛③只用指責要求其「要有正義感」④以此分數推論其一定會做出嚴重不公行為。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_14', 'A', 75, 100, '低自我中心', '對自身與他人的相對位置看法較平衡，不太需要透過炫耀或壓過他人來證明價值，較能接受他人貢獻。', '適合團隊協作、共同署名與跨部門合作，降低內耗與功勞爭奪。', '較自然地把自己視為團隊的一員，而非特別應該被優待的人，習慣低調表達貢獻，不會刻意凸顯自己。', '{"do": "可用於：①說明其在團隊合作、學習與接納回饋上的優勢②建議在需要降低階級距離、建立信任氛圍的情境中善用此特質③鼓勵在合適場合也能清楚說出自己的貢獻，避免長期被低估。", "dont": "禁止：①因為其謙虛就忽略或壓低其成果與待遇②用「你很謙虛」包裝客觀上的不公平③期待其永遠把他人放在自己前面④用文化期待壓抑其合理的自我主張。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_14', 'B', 50, 74, '自信含蓄', '能肯定自己但表達較保留；在需要展現影響力或爭取資源時，可能猶豫如何拿捏分寸。', '給明確發聲場域與表達框架（成果呈現、角色授權），提升影響力而不違背風格。', '整體能保持不誇大、不自我膨脹的態度，但在需要爭取機會或介紹自己的場合，也有能力適度呈現個人成果。', '{"do": "可用於：①說明其在謙虛與自我行銷間較能拿捏分寸②建議在重要場合協助其更具體呈現亮點，以免低估自己③鼓勵持續維持這種彈性，不因環境壓力走向過度自貶或過度自誇。", "dont": "禁止：①因其在某些場合展現自信就批評為「不謙虛」②忽略角色本身對曝光與表現的要求③用單一互動經驗判斷其整體人格④要求其完全抹去自我存在感。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_14', 'C', 0, 49, '自我凸顯', '較傾向強調自身貢獻與地位，可能把被看見視為重要需求，對他人表現的接受度較敏感。', '以透明功勞分配與評價制度降低衝突；安排在對外代表或競爭型任務可能更合適。', '較常覺得自己的付出與能力應該獲得更多關注與禮遇，習慣主動凸顯自身貢獻與重要性，期待被特別看見。', '{"do": "可用於：①指出其在爭取資源、機會與可見度時的主動性優勢，但須留意團隊感受②建議透過具體回饋幫助其調整表達方式，讓自我肯定不至於壓過他人③鼓勵其在展現自己之外，也刻意練習看見與肯定周遭成員。", "dont": "禁止：①直接標籤為「自大」「目中無人」②忽略其過去可能長期被低估而需要用力爭取③用羞辱方式壓抑其自我肯定④以此分數推論其無法良好合作。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_15', 'A', 75, 100, '正向資源充沛', '具備較高的希望、效能感、韌性與樂觀傾向，面對挑戰能維持動能與信心，並把挫折視為可處理的問題。', '適合承擔轉型、開創、逆風推進與需要帶動士氣的角色；可作為團隊動能來源。', '整體心理資源相對充足，面對壓力與挑戰時，多半能帶著希望感、自信與韌性前進，把挫折視為可以調整與學習的機會。', '{"do": "可用於：①說明其在變動環境與高壓任務中的心理支撐作用②建議擔任需要帶動士氣、面對不確定性的角色③提醒在照顧他人、當大家精神支柱的同時，也要有人照顧他。", "dont": "禁止：①把其心理資本視為可以無限加壓的本錢②用「你撐得住」忽略其困難或疲憊③期待其永遠保持樂觀不准低潮④視求助或疲倦為「不應該」。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_15', 'B', 50, 74, '可被激發', '一般狀態能保持正向，但在長期壓力或不確定下動能可能下降；獲得支持與看見進展後會回升。', '以清楚目標、可見進度、支持系統與正向回饋拉升狀態；適合穩健推進型任務。', '在一般情況下能保持一定程度的樂觀與復原，但遇到長期壓力、連續挫敗或高度不確定時，心理動能會明顯下降，需要外在支持與時間恢復。', '{"do": "可用於：①說明其心理狀態與壓力總量與時間長度高度相關②建議安排合理恢復期與支持資源，避免長期處在高壓而不調整③鼓勵建立自己的紓壓與支持系統，在動能下降時有地方補充。", "dont": "禁止：①把在高壓之下的疲憊解讀為「不堅強」②忽略工作量、角色衝突與生活事件③只用「想開一點」簡化其困境④將偶爾低潮視為無法信任的理由。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_15', 'C', 0, 49, '資源不足', '較容易感到無力或悲觀，遇到挫折時動能下降較明顯，對未來期待感相對薄弱。', '先從可達成小目標建立成功經驗，搭配支持、教練式管理與壓力源盤點；避免一開始丟高不確定任務。', '對未來與自身影響力較容易抱持保留或悲觀態度，遇到壓力與挫折時，容易覺得「事情不會變好」或「自己也改變不了太多」。', '{"do": "可用於：①指出其在面對壓力與變動時需要更多支持與成功經驗累積②建議透過小而具體的目標與逐步成就感，慢慢擴大心理資源③鼓勵組織提供安全嘗試與允許失敗的空間，而非只要求「要正向」。", "dont": "禁止：①將其標籤為「負面」「難帶」②忽略過往挫折、資源不足或系統問題對其心理狀態的影響③用雞湯或責備要求其立刻樂觀④以此分數判定其不適合承擔重要任務。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_16', 'B', 50, 74, '動機可續航', '有目標動機，但路徑規劃有時需要外部引導；當方法不順時可能卡住，重新對齊後能再推進。', '用路徑拆解、選項清單與障礙排除會議提升連續性；適合在有策略框架的團隊成長。', '對未來大致有想像或方向，但在具體步驟與策略上仍在摸索，遇到環境變化或挫折時，較容易感到卡住，需要更多討論與陪伴釐清。', '{"do": "可用於：①說明其在願景與路徑之間存在過渡期②建議提供職涯諮詢、導師制度或教練式對話，協助把方向拆成可行步驟③鼓勵從短期可實踐的小目標開始，降低不確定感。", "dont": "禁止：①將其猶豫解讀為「沒目標」「沒企圖心」②忽略機會結構與資訊不對稱③只用「自己要想清楚」回應其困惑④以此分數否定其長期發展。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_16', 'C', 0, 49, '路徑不足', '可能有想達成的目標，但較難把動機與策略化路徑連結；遇到阻礙時容易停滯或轉向。', '先建立短期可達成目標與清晰下一步，搭配教練式提問與資源支持，逐步建立路徑思考能力。', '目前較難具體描述長期想追求的目標，對未來多半停留在模糊或「先顧好眼前再說」的狀態，較少主動規劃遠期方向。', '{"do": "可用於：①指出其可能正處於「優先處理當下」的階段②建議透過探索活動、不同嘗試與陪談，一點一點幫助其長出較有個人感的目標③鼓勵從短期小目標開始，讓「未來可以被塑造」的感覺慢慢變清楚。", "dont": "禁止：①標籤為「沒未來性」「沒理想」②忽略其現實壓力、資源或資訊限制③用批判或嘲諷逼其立即說出長期藍圖④把此分數視為固定且不可改變。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_17', 'A', 75, 100, '敢承擔會達成', '對努力能換來結果有明確信心，遇到高標目標傾向主動拆解與推進，較不容易因不確定而退縮。', '適合推進型任務與需要自我驅動的角色；可給較高自主權並期待自我解題。', '面對具有挑戰的目標時，多半相信「只要我願意投入，就有機會做到」，傾向主動拆解目標並推進，而不是因不確定而退縮。', '{"do": "可用於：①說明其在承接挑戰性任務與帶頭推進方面的潛力②建議提供明確標準與資源，讓其效能感轉成具體成果③提醒在失敗時，不要把所有責任全往自己身上扛，以免效能感反向受損。", "dont": "禁止：①把其高效能感視為可以忽略支援與環境條件的理由②在結果不佳時，以更重的道德壓力批評「你本來就做得到」③期待其一人填補所有制度缺口④用短暫挫折推論其信心已崩壞。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_17', 'B', 50, 74, '需要確認再加速', '能力感多半足夠，但在新領域或高風險情境會希望先確認方向；一旦標準清楚就能穩定輸出。', '以成功標準、階段檢核與教練式回饋拉升信心與速度；適合在導師制團隊中成長。', '對熟悉或曾經成功的類型較有把握，遇到全新領域或高風險任務時，會先關注方向是否正確、支援是否足夠，再決定要投入多少。', '{"do": "可用於：①說明其效能感與「掌握度」高度相關②建議在新任務上提供導入說明、示範與可詢問對象，縮短不確定期③鼓勵其把過去克服困難的經驗帶到新的情境中，協助建立信心。", "dont": "禁止：①將謹慎視為「沒自信」或「不敢扛責」②忽略資源與資訊不足對投入意願的影響③只用「你要勇敢試」而不調整外在條件④以此分數否定其接新角色的可能性。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_17', 'C', 0, 49, '容易自我懷疑', '對能否完成目標缺乏把握，面對挑戰可能遲疑、過度求證或依賴他人決策，影響推進節奏。', '用小步成功累積、降低啟動門檻並提供明確指引與正向回饋；避免一開始就丟高不確定責任。', '對「即使努力也未必成功」的感受較強烈，面對較大的目標時容易預期失敗，因而降低投入意願或傾向選擇風險較低的選項。', '{"do": "可用於：①指出其效能感可能受過往「努力與結果落差」經驗影響，需要透過小成功經驗重新建立②建議設計可控性較高、步驟清楚的目標，減少徒勞感③鼓勵其記錄具體的進步與做到的事情，而不是只放大失敗。", "dont": "禁止：①把其保守選擇簡化為「不努力」②忽略機會不均、資源限制與系統問題③用嘲諷或比較方式施壓「你要有自信」④把此分數視為無法恢復的信心問題。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_18', 'A', 75, 100, '逆境復原快', '遇到壓力、衝突或失敗後能快速回到可工作狀態，並把打擊轉成修正與補救行動。', '適合高壓前線、轉型推進、責任變更頻繁角色；可作為續航與穩定支點。', '面對壓力、挫折或變化時，雖然會受影響，但多能在合理時間內調整心態、找到因應方式並回到可運作狀態。', '{"do": "可用於：①說明其在變動環境與高壓任務中的復原能力②建議在變革或關鍵專案中安排其扮演穩定力量的角色③提醒組織不要因其韌性而忽略資源、人力與休息配置。", "dont": "禁止：①把其韌性當成可以無限加壓的理由②用「你撐得住」忽略其耗損③假設其永遠不會出現耗竭或低潮④在其提出需要幫忙時感到「意外」並責怪。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_18', 'B', 50, 74, '恢復需要時間', '受到壓力時會有明顯影響，但在獲得支持、釐清方向後能逐步回穩；表現受情境差異影響。', '以合理節奏、同儕支持與階段里程碑降低負荷；適合穩健推進配置。', '面對壓力與打擊時會明顯受影響，需要時間與支持才能恢復，但在方向釐清、支持到位後，多能逐步回穩。', '{"do": "可用於：①說明其恢復速度與壓力強度、持續時間及支持程度高度相關②建議在高壓階段預先安排緩衝與支援機制③鼓勵其把需要幫助視為正常反應，而不是弱點。", "dont": "禁止：①把在高壓下恢復較慢解讀為「抗壓性差」②忽略工作與生活中長期壓力來源③只用「要想開」而不處理結構問題④把一次的低潮視為不能再被信任。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_18', 'C', 0, 49, '耗損累積快', '在長期高壓或連續變動下容易出現能量耗竭，補救與恢復較吃力，表現波動可能增大。', '設計緩衝與分工、避免長期獨撐；用復盤與支持資源提升挽救能力。', '長期或高強度壓力較容易累積成耗損感，一旦被壓垮，恢復需要較多時間與資源，情緒與表現波動也相對明顯。', '{"do": "可用於：①指出其在長期高壓環境中的風險，需要特別留意工作設計與負荷管理②建議建立穩定的支持系統（如信任的人、專業資源、自我照顧習慣）③鼓勵用溫和、不評價自己的態度面對脆弱，從中練習新的調適方式。", "dont": "禁止：①把其狀態標籤為「玻璃心」「不抗壓」②忽略組織在壓力管理與資源配置上的責任③用比較與羞辱逼其「硬起來」④以此分數作為不適合培養或信任的理由。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_19', 'A', 75, 100, '把不順視為暫時', '對挫折的解釋偏向可改善、可轉機，較能維持希望感與行動力，不易被單次失敗打垮。', '適合帶動士氣、在不確定中推進的任務；可作為團隊動能來源。', '看事情時比較容易先看到可能性與希望，面對挫折也傾向解讀為暫時的阻礙，而不是全面否定自己或未來。', '{"do": "可用於：①說明其在壓力與變動中維持希望感與行動動能的能力②建議在變革、轉型或高不確定專案中，善用其穩定團隊士氣的特質③鼓勵把樂觀轉化為行動計畫，而不是只停留在「應該會好」的想像。", "dont": "禁止：①把其樂觀看成「什麼都不怕」而不討論風險②用樂觀掩蓋現實問題或資源不足③在對方感到沮喪時，用「你不是很樂觀嗎」否定其當下感受④暗示只要樂觀就不需要制度與支援。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_19', 'B', 50, 74, '現實中保有期待', '多半能保持正向，但在連續不順或高壓時會短暫消沉；看見進展與資源後能恢復。', '以可視化進度、明確下一步與支持系統維持動能；適合穩健節奏。', '面對多數情況時能維持基本正向看法，但在連續挫折或高度不確定時，心情與信心會隨情境明顯波動。', '{"do": "可用於：①說明其樂觀程度與事件頻率、壓力強度高度連動②建議在關鍵階段提供資訊透明與具體進展，減少不必要的悲觀解讀③鼓勵透過記錄小成功、與他人對話來調整看事情的角度。", "dont": "禁止：①把偶爾的低落解讀為「很負面」②忽略環境與事件累積對其心態的影響③只用「想開一點」要求其振作，而不處理問題本身④把樂觀程度簡化為個人意志力強弱。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_19', 'C', 0, 49, '容易悲觀解釋', '傾向把不如意視為長期且普遍，可能降低嘗試意願與抗挫力，遇阻礙容易預期失敗。', '從可控小目標建立成功經驗，搭配教練式提問與資源支持；避免長期無回饋任務。', '在面對壓力、變動或不確定時，較容易先想到可能的風險與失敗結果，對「事情會變好」的想像較不自然。', '{"do": "可用於：①指出其在風險覺察上具敏感度，但也較容易陷入悲觀循環②建議引導其平衡「最壞情境」與「可行對策」，從可控部分著手③鼓勵透過具體行動與小成果，慢慢修正「事情都不會變好」的內在腳本。", "dont": "禁止：①直接貼上「負面」「愛抱怨」標籤②忽略其過往挫折或資源不足對世界觀的影響③用雞湯式鼓勵要其立刻變樂觀④把此分數當作不適合承擔重要任務的單一依據。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_20', 'A', 75, 100, '主動挑戰框架', '喜歡用新方法做事，會主動發現問題、提出替代解法並挑戰主流規則，不易被既有慣例限制。', '適合探索、轉型、產品/流程革新；放在發想與實驗段落發揮。', '遇到問題時自然會往新方法、新角度思考，不太滿足於「一向都這樣」，喜歡在限制中找到創新的突破口。', '{"do": "可用於：①說明其在創新專案、流程改善與新服務設計上的潛力②建議安排有空間試驗與迭代的任務，讓其創意能真正落地③鼓勵同時學會評估風險與成本，讓創新不只好玩也具可行性。", "dont": "禁止：①把其創新力當成無限「幫忙發想」的資源，而不給實驗空間②把所有守規或穩定作法都貶低為「不創新」③忽略其創意實作所需時間與支援④要求其在高度僵化環境下仍源源不絕產出新點子。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_20', 'B', 50, 74, '改良式創新', '願意提出新點子，但多從現有流程中找改良機會；限制明確時更容易產出可落地方案。', '給清楚目標與限制條件並搭配原型驗證，提升落地率；適合改善型任務。', '在熟悉範圍內遇到問題時，偶爾會提出不同作法；但若風險較高或規則限制較多時，會傾向先確認安全做法再談創新。', '{"do": "可用於：①說明其創新傾向受情境安全感與資源影響②建議提供明確框架（哪些可試、哪些是底線），讓其較敢提出改進想法③鼓勵在小範圍試驗、A/B 測試中練習把點子變成具體行動。", "dont": "禁止：①把不主動「顛覆一切」解讀為「沒創意」②忽略文化氣氛與主管態度對其創新意願的影響③只在出問題時要求其「想點新招」④以少數不成功的嘗試否定其創新能力。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_20', 'C', 0, 49, '慣例優先', '較偏好沿用成熟做法，面對新方法可能先觀望；創新動機較低但穩定性較高。', '適合標準化與高一致性作業；推動創新可先小規模試點降低不確定。', '做事風格較偏向沿用既有作法與慣例，面對「完全沒做過的嘗試」會感到遲疑或擔心風險，對創新本身不一定感到興奮。', '{"do": "可用於：①指出其在需要穩定執行、流程遵循的工作上可提供穩定度②建議若希望其參與創新，先從「微調現有流程」而非大幅顛覆開始③鼓勵用逐步嘗試與明確風險控管，降低對創新的不安感。", "dont": "禁止：①貼上「保守」「沒創意」的單一標籤②在未提供資訊與支援下強迫其快速接受大變革③忽略其對穩定與可預測性的合理需求④用此分數否定其在改善與優化上的貢獻可能。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_24', 'B', 50, 74, '顧自己也顧關係', '通常能維持自我一致，但在高社會壓力或權威情境會調整表達以保留合作空間。', '提供安全表達空間與明確決策流程，有助兼顧真實與合作；適合協調角色。', '重視真實與一致性，但也會考量場合、角色與關係，在誠實表達與維持和諧之間尋找平衡。', '{"do": "可用於：①說明其在真實自我與社會期待之間有彈性調整能力②建議釐清哪些情境可以更做自己、哪些需更策略表達③鼓勵其在長期壓抑時，找到安全場域說真話，減少耗損。", "dont": "禁止：①將必要的修飾一概視為「不真誠」②忽略角色責任與關係風險對其表達選擇的影響③用理想化標準要求其「永遠說真話不計代價」④以一次不完全坦白否定其整體真實性。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_21', 'A', 75, 100, '跳脫程序求快', '高度在意更快更省更有效，不喜歡被程序綁住，會用不同角度簡化流程以達成結果。', '適合快速迭代、流程優化與降本增效；可主導改善與自動化提案。', '對提升流程效率、縮短等待與減少浪費特別敏感，會主動思考「怎樣更快、更準、更省力」。', '{"do": "可用於：①說明其在流程優化、標準化與自動化上的優勢②建議讓其參與或主導效率改善專案，將觀察轉化為具體機制③鼓勵在追求效率時，兼顧品質、人際感受與必要的思考空間。", "dont": "禁止：①把效率視為唯一價值，鼓勵其忽略人與品質②在制度與工具落後的前提下要求其獨自扛起所有改善責任③將對低效率的敏感誤解為「愛抱怨」④忽略某些議題需要「慢下來」才能做出好決定。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_21', 'B', 50, 74, '效率規範平衡', '能在規範內追求效率，必要時提出簡化建議，但仍保留關鍵程序以降低錯誤。', '以分級規則（哪些必做、哪些可省）最有效；適合流程微調與落地執行。', '在明顯拖沓或浪費的情況下會感到不耐，願意調整做法，但若現況尚可接受，通常不會刻意追求極致效率。', '{"do": "可用於：①說明其在效率與實際付出之間會權衡成本效益②建議在關鍵流程上與其一起定義「值得優化的地方」，提高參與感③鼓勵用小步改善而非一次大改，讓效率提升更貼近實務。", "dont": "禁止：①因不「追求每一秒都被最佳化」而貼上「不重效率」標籤②忽略改善本身需要時間與心力③在沒有參與的情況下只要求其配合新流程④用單一事件評價其長期工作風格。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_21', 'C', 0, 49, '精準依程序', '做事偏向遵循規範與既定步驟，重視精確與條理；效率提升多透過穩定流程而非破格捷徑。', '適合高精度、合規、品質把關或需要穩定一致輸出的任務。', '對效率或流程優化的敏感度較低，只要事情能完成，就不太在意是否有更快或更省力的方式。', '{"do": "可用於：①指出其在節奏穩定、壓力較低的環境中較能自在工作②建議在需要效率的關鍵流程，提供清楚指標與具體做法，而不是只喊「要快」③鼓勵透過簡單工具（範本、捷徑）讓效率自然提升，而非完全依賴個人自覺。", "dont": "禁止：①貼上「拖延」「效率差」的道德化標籤②忽略任務複雜度、資訊混亂度對節奏的影響③期待其在沒有任何工具與教學下，自行達到高效率標準④把此分數視為無法勝任高要求工作的絕對指標。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_22', 'A', 75, 100, '自在於無規則', '不依賴傳統或被接受的方法，面對缺乏規則的情境仍能找到做法並推進。', '適合新創、0→1、策略探索或規則尚未建立的任務；可放在開荒位置。', '在清楚的規則、流程與架構下工作會感到安心，傾向尊重制度、依循既有規範來處理事情。', '{"do": "可用於：①說明其在合規、風險控管與制度落實上的重要性②建議安排在需要嚴謹遵守標準作業的任務或角色③鼓勵在面對不合時宜規範時，嘗試用建設性方式提出調整建議。", "dont": "禁止：①把其對規則的尊重當成可以塞所有行政雜事的理由②忽略制度本身的不合理，只要求其「要照做」③將其質疑視為「不服從」而不討論內容④把高紀律遵循度當作缺乏彈性的同義詞。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_24', 'A', 75, 100, '價值一致', '行為與自身價值觀、欲望較一致，即使面臨從眾壓力仍能維持立場與一致性表現。', '適合誠信、文化示範與長期信任角色；在價值衝突場景提供穩定判準。', '言行多半能與內在價值與真實感受保持一致，即使環境有壓力，也比較難長期違背自己真正相信的事。', '{"do": "可用於：①說明其在信任建立與角色正直上的重要性②建議安排在需要高可信度與價值導向的任務（如顧問、關係管理）③鼓勵其在價值衝突情境中尋求對話與支持，而不是一個人硬撐。", "dont": "禁止：①把其真實性當成可以要求「完全透明」的理由②忽略文化與權力現實對表達空間的限制③在其提出價值質疑時視為「不配合」④鼓勵其長期犧牲自我以換取組織穩定。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_22', 'B', 50, 74, '可切換模式', '在有規則時能配合，在無規則時也願意嘗試；但需要明確目標與邊界才能穩定輸出。', '給方向與原則（目的/底線/驗收）讓其在框架內自由發揮；適合跨情境角色。', '基本會遵守重要規範與流程，但在規則與現實衝突時，會評估情境與風險，尋找可行折衷，而非一味僵硬或完全忽略。', '{"do": "可用於：①說明其在「守規」與「務實」之間具有一定彈性②建議與其一起界定哪些是不能碰的底線，哪些可以討論與調整③鼓勵在遇到衝突情境時，把思考過程說出來，增加透明度與信任。", "dont": "禁止：①因為有彈性就說「不守規矩」②忽略制度矛盾、時間壓力對行為選擇的影響③只看結果是否完美符合流程，而不看其評估過程④用單一事件給出「不可靠」的定義。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_22', 'C', 0, 49, '規則清楚最好', '偏好依循既有且被接受的方法，規則越清楚越能發揮；面對模糊規則容易卡住或降低效率。', '適合制度化、作業明確、合規高的環境；對變更管理需更完整溝通。', '對既有規則與流程的依附度較低，面對限制時較容易想著「有沒有別的方法」，對高度制式、僵化的環境較難長期適應。', '{"do": "可用於：①指出其在需要突破僵化流程、面對未定義問題時具優勢②建議在高風險領域設立清楚界線，讓其明白哪些地方不能逾越③鼓勵其將挑戰規則的能量用在提出具體改善方案，而不是只是否定。", "dont": "禁止：①直接貼上「叛逆」「不聽話」的標籤②忽略規則本身是否合理③完全用個人意願取代制度設計的討論④在沒有說明風險的前提下，單純要求其「不要亂動流程」。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_23', 'A', 75, 100, '原創解題者', '常能以另類觀點重新定義問題，並提出非既定路徑做法；原創想法輸出頻率高。', '適合概念發想、策略破題與需要差異化的任務；在早期探索階段發揮。', '思考與表達時常能跳脫既有框架，提出與主流不同但具啟發性的觀點或解法。', '{"do": "可用於：①說明其在策略討論、產品構想與問題定義上的創意資產②建議在早期構想階段讓其多參與發想，再搭配他人評估可行性③鼓勵在維持獨特觀點的同時，也學會用對方聽得懂的語言表達。", "dont": "禁止：①把其與眾不同的想法視為「不切實際」而直接否定②只在有問題時才臨時要其「給點創意」③忽略其在落地執行上可能需要支援④把創意等同於必須承擔所有變革責任。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_23', 'B', 50, 74, '情境催化原創', '在刺激足夠或問題設計得好時能產出新想法；若限制不清或缺乏材料，容易回到常規解法。', '用工作坊、對比案例與明確限制條件提升原創品質；適合被題目引導的創意輸出。', '在適合的題目與氛圍下，能提出一些與眾不同的想法；平常多半還是以實務可行與現有做法為主。', '{"do": "可用於：①說明其原創性會受主題興趣與心理安全感影響②建議創造低風險、可試錯的場域，邀請其分享不同看法③鼓勵其將偶爾的靈感記錄下來，累積成可被討論與應用的素材。", "dont": "禁止：①因為平時較務實就認定其「沒創意」②忽略團隊文化對發言勇氣的影響③只在會議最後壓時間時才請其「提想法」④用一次沉默評價其創造力。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_23', 'C', 0, 49, '常規解法偏好', '傾向在規範或既定程序內思考，較少自發產出原創解法；重視可行與穩定。', '適合落地、標準化、維運與品質一致性工作；創新需求可由他人提供再負責執行。', '多半偏好沿用已證實可行的作法，對太跳躍或過於另類的觀點較難產生共鳴，原創性表現相對內斂。', '{"do": "可用於：①指出其在維持穩定、落實既有最佳實務上具可靠性②建議若希望其參與創意思考，可從「現有做法的微調」入手，而不是要求大幅顛覆③鼓勵其在聽到新點子時，先詢問邏輯與目的，再決定是否採納。", "dont": "禁止：①貼上「墨守成規」「沒想像力」標籤②忽略其在風險敏感與實務可行性上的價值③強迫其接受沒有說清楚的劇烈變革④以此分數否定其在優化、標準化工作中的重要性。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_24', 'C', 0, 49, '易受從眾牽引', '較容易因外界期待而調整言行，內外一致性較弱；可能避免衝突而壓抑真實想法。', '適合規則清楚、壓力較低環境；管理上降低懲罰式文化並鼓勵回饋。', '在強烈外在期待或壓力下，較容易優先配合情境需要，而壓抑或暫時擱置自己的真實想法與感受。', '{"do": "可用於：①指出其可能長期處在高社會期待或關係壓力之中②建議提供安全、非評價性的對話空間，讓其練習逐步表達真實自己③鼓勵分辨「為了關係調整」與「完全犧牲自我」之間的界線。", "dont": "禁止：①直接貼上「假」「雙面」標籤②忽略權力不對等與文化壓力③要求其立刻完全做自己而不顧現實風險④將此分數視為無法信任的絕對指標。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_25', 'A', 75, 100, '團隊優先', '重視凝聚力與共同目標，傾向把集體利益放在個人之前，願意為團隊付出與協調。', '適合跨部門協作、共同 KPI 與共享資源團隊；可擔任凝聚與協調角色。', '自然會把「我們」放在「我」之前，重視團隊凝聚與共同目標，願意在合理範圍內為集體利益調整個人安排。', '{"do": "可用於：①說明其在團隊合作、跨部門協作與文化建構上的關鍵角色②建議在溝通中清楚說明決策如何影響「整體」，能更激發其投入③鼓勵其同時照顧自己的界線，避免長期只顧團隊忽略自我需求。", "dont": "禁止：①把其集體導向當成理所當然，不斷要求多做犧牲②忽略其在團隊衝突與不公情境中的壓力③以「團隊為重」否定其個人合理訴求④將不同意見視為「不團隊」。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_25', 'B', 50, 74, '合作務實', '願意合作，但會視任務與回報做取捨；在公平制度下能維持良好協作。', '以清楚分工與共同目標對齊最有效；適合合作＋個人責任並存制度。', '重視團隊合作與關係，但在個人利益或發展受到明顯影響時，也會思考如何取得平衡。', '{"do": "可用於：①說明其會在團隊與個人之間做現實權衡②建議在任務分配與獎酬上說清楚彼此的得失，避免其長期感到吃虧③鼓勵其以理性表達而非壓抑來處理衝突。", "dont": "禁止：①因為提出個人需求就認定其「不顧團隊」②忽略制度設計與分配機制對其感受的影響③用道德壓力要求其無條件付出④把一次保留視為不適合團隊。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_25', 'C', 0, 49, '個人導向', '更重視個人目標與自主性，對集體要求投入度較低；偏好清楚個人責任與回報。', '適合個人貢獻型角色；若需合作，說明互賴關係與利益對齊。', '思考時較常以個人目標與利益為優先，對「為團隊多做一些」的動機較依賴具體回饋或明確交換。', '{"do": "可用於：①指出其在個人績效導向情境中可能動機較強，但在高度團隊導向文化中需要更多對齊與說明②建議清楚界定合作帶來的具體好處（學習、資源、評價），提升合作意願③鼓勵其在爭取自我利益的同時，也思考長期關係與名聲。", "dont": "禁止：①直接貼上「自私」「不合群」標籤②忽略其過往可能被濫用或吃虧的經驗③只用道德批評要求其「要為團隊著想」④把此分數視為無法參與任何團隊工作的證明。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_26', 'A', 75, 100, '能進入他人框架', '能以他人的參考架構理解其處境與感受，互動時會調整語氣與回應方式以貼近對方需要。', '適合客戶溝通、帶人管理、衝突調解與需要情緒敏感度的角色。', '容易從他人立場出發理解對方的感受與處境，能聽出話語背後的情緒與需求，並給出相對貼近的回應。', '{"do": "可用於：①說明其在輔導、溝通協調與客戶關係中的價值②建議在衝突情境中善用其橋樑角色，協助彼此被理解③鼓勵其建立自我界線與自我照顧，避免長期承擔過多情緒負荷。", "dont": "禁止：①把其同理心當成情緒垃圾桶，凡事都請他吸收②忽略其自身的情緒需求③在制度不公時只要求其「多體諒」④將其情緒耗竭視為「不專業」。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_26', 'B', 50, 74, '理解為主', '能理解他人觀點，但情緒共感表達較偏理性；在任務型對話中表現穩定。', '提供回饋技巧與提問框架可提升同理回應的可見度；適合專業導向協作。', '在關係重要、對象熟悉或情境明顯時，多能感受到他人情緒並做出恰當回應；在距離較遠或訊號較弱時，理解度會下降。', '{"do": "可用於：①說明其同理表現與關係親近度、訊息清晰度高度相關②建議在跨部門或陌生對象互動時，提供更多背景資訊與情境說明③鼓勵其用提問而非猜測來了解他人。", "dont": "禁止：①把在陌生場景下的判斷失誤解讀為「沒同理心」②忽略文化差異與溝通習慣對表達的影響③只要求「要設身處地想」卻不提供資訊④用單一案例否定其關懷能力。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_26', 'C', 0, 49, '線索較少', '不容易捕捉他人情緒或隱含需求，互動多以事情推進為主，可能無意中造成距離感。', '適合互動需求較低角色；在服務/帶人場景建議搭配溝通訓練與回饋機制。', '自然注意力較多放在自己當下的任務、感受與想法上，不太會自發地揣摩他人心情，需要比較明確的訊號才容易察覺。', '{"do": "可用於：①指出其在專注任務上的優勢，同時在人際情境需刻意練習「多看一眼、多問一句」②建議提供清楚的人際線索與反饋，幫助其理解互動影響③鼓勵其把「想問清楚」當作一種尊重，而不是多此一舉。", "dont": "禁止：①直接貼上「冷漠」「沒感覺」標籤②忽略其成長背景與文化對表達情感方式的影響③在沒說明期待的情況下責怪其「不懂人情世故」④以此分數判定其不適合任何關係導向工作。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_27', 'A', 75, 100, '共益付出', '在合作中更重視整體成果與長期互惠，願意先付出、讓利或承擔額外責任，以促成共同完成目標。', '適合共創與跨部門協作、短期回報不明但長期價值高的任務；可放在需要先扛先推的角色位置。', '對他人與團隊相當願意投入時間與心力，即便不一定有立即回報，也樂於主動幫忙與支援。', '{"do": "可用於：①說明其在團隊合作、支援同事與承接額外任務上的高度意願②建議在重要專案或關鍵時刻善用其願意多走一里路的特質③鼓勵組織在接受其付出的同時，給予合理感謝與資源，避免長期過勞或被視為理所當然。", "dont": "禁止：①把其願意付出當成無限制增加工作量的理由②忽略其也有疲累與界線，只期待「有事找他就對了」③用道德壓力強調「你那麼願意幫忙就再多撐一點」④在制度設計上假設有人會永遠自願補洞，不處理結構問題。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_27', 'B', 50, 74, '互惠平衡', '願意付出，但也會留意互惠是否合理；當看到對方回應與制度公平時，投入度與合作意願會提升。', '以透明分工、可見回饋與資源對齊穩定投入；適合制度清楚的團隊協作。', '願意在合理範圍內為他人與團隊付出，但會衡量情境與自身狀態，選擇在合適的時候伸出援手。', '{"do": "可用於：①說明其付出傾向會隨工作量、公平感與關係重要性而調整②建議與其清楚談期待與分工，讓付出與回報相對平衡③鼓勵其在自己願意幫忙的前提下，也能適時說明目前的負荷狀況，避免內心累積壓力。", "dont": "禁止：①因為不「每次都答應」就貼上「不願付出」的標籤②忽略其實在多數情況下仍願意支援他人③只在忙碌時臨時請求幫忙，卻沒有長期在制度上照顧④用比較的方式指責「別人都願意，你怎麼不行」。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_27', 'C', 0, 49, '回報敏感', '對付出與回報對等性較敏感，容易在意自己是否吃虧；互惠不明確時可能降低投入或轉為保守合作。', '適合權責清楚、回報機制透明環境；需明確界定投入範圍與回饋，避免累積不滿。', '對額外付出較為保留，傾向先確認是否與自身責任、回報或目標明確連結，才會考慮投入更多時間與心力。', '{"do": "可用於：①指出其在付出時較強調界線與資源運用效率，適合在角色與責任清楚的環境中工作②建議若希望其多一些投入，需說明付出與目標、回報或專業成長的連結③鼓勵其在維護自身界線的同時，也思考關係與團隊長期合作的效益。", "dont": "禁止：①簡單貼上「自私」「不肯幫忙」的標籤②忽略其過往可能因過度付出而感到被利用的經驗③用道德控訴要求其無條件犧牲④把此分數當成無法合作或不適合團隊工作的直接證據。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_28', 'A', 75, 100, '經常表達感激', '容易看見他人付出並主動表達感謝，強化互惠與人際正向循環。', '適合文化建立、團隊氛圍與客戶關係經營；可作為正向回饋示範者。', '對他人的幫助與資源供給比較容易感到感激，會主動表達謝意並記得他人的好。', '{"do": "可用於：①說明其在建立互信與正向互動氛圍上的貢獻②建議讓其在團隊中成為正向回饋與感謝文化的帶動者③鼓勵其在表達感謝時也具體說明「哪裡幫助到自己」，增加互動品質。", "dont": "禁止：①把其願意感謝視為理所當然、反而加重負擔②以「你應該更感恩」來壓抑其合理不滿③忽略制度與實質待遇問題，只期待情緒上的感恩④把感恩當成避免改變的不成文要求。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_28', 'C', 0, 49, '較少注意感謝', '較不容易察覺或表達感謝，互動多聚焦在任務完成；可能忽略他人投入的情感需求。', '可加入回饋儀式與互相肯定機制；適合任務導向角色但需補足情感回饋。', '對他人提供的協助或制度支援較少產生明顯的感激情緒，可能更傾向視為「應該的」或互利交換的一部分。', '{"do": "可用於：①指出其在強調權責與交換的互動中較感自在，但在關係經營上可能少了些溫度②建議透過具體例子協助其理解感謝對關係的正向影響③鼓勵其在重要時刻試著用簡短話語表達肯定，不需誇張也能拉近距離。", "dont": "禁止：①直接貼上「忘恩負義」標籤②忽略其價值觀中對「互惠、權責分明」的重視③用羞辱方式強迫其表達感謝④將此分數視為無法建立良好人際的必然結果。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_29', 'A', 75, 100, '能與各型人合作', '能適應不同性格與風格的人，懂得管理互動張力並建立互利的合作關係。', '適合跨部門、客戶多元與橋接衝突角色（PM、顧問、BD、HR）。', '在人際互動中能快速調整說話方式與互動風格，面對不同性格與背景的人，都有機會建立合作或信任關係。', '{"do": "可用於：①說明其在跨部門協作、客戶應對與關係經營上的靈活度②建議安排在需要橋接多方利害關係人的角色③鼓勵在調整自己迎合他人時，也要留意不過度消耗自我。", "dont": "禁止：①把其適應力誤解為「沒有立場」「到處討好」②忽略其在人際壓力下的疲憊感③期待其一手處理所有人際問題，而不調整制度④將偶發的誤判視為長期失職。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_29', 'B', 50, 74, '熟悉圈內更順', '在熟悉或風格相近的場域表現良好；遇到差異很大的對象需要時間摸索互動節奏。', '提供對象背景、互動目的與界線可縮短磨合期；適合在穩定合作網絡中擴張。', '在熟悉或相對類似的人際環境中互動順暢；面對風格差異較大或權力距離較大的對象時，需要一些時間摸索相處方式。', '{"do": "可用於：①說明其人際適應與情境熟悉度高度相關②建議在新環境或新對象互動初期給予明確指引與範例③鼓勵透過觀察與適度試探，逐步找到合適的相處節奏。", "dont": "禁止：①因在陌生情境中略顯拘謹就說「人際能力不好」②忽略組織氛圍與權力結構對其互動表現的影響③只在出現衝突時才檢討其人際，而不提供教練式支持④將單次不順視為無法代表公司對外。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_29', 'C', 0, 49, '互動張力較高', '面對不同類型的人容易緊繃或不知拿捏，互動策略較固定，合作建立成本較高。', '適合互動規則清楚環境；可用情境腳本、角色演練與回饋提升。', '在人際情境中的調整彈性相對有限，面對不同風格與期待的對象時，較容易感到尷尬、不知如何應對或乾脆選擇少互動。', '{"do": "可用於：①指出其在人際多樣性高的環境中可能需要較多支持與指引②建議提供具體對話範例、情境演練或觀摩機會，讓其建立安全感③鼓勵其從少數關係開始練習，而不是要求自己對每個人都能自在自如。", "dont": "禁止：①貼上「不會做人」「EQ 低」標籤②忽略其內向、焦慮或過去人際經驗帶來的影響③在未提供任何訓練或支持下，要求其立刻處理複雜關係④以此分數否定其在專業或技術面上的價值。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_30', 'A', 75, 100, '對結果負全責', '對把事情做好有強烈決心，遇到問題會主動承擔、補救與追根究柢，而非推給情境或他人。', '適合主責角色、交付導向任務；可降低管理追催成本。', '對自己承諾過或該負責的事情會主動扛起來，不容易把錯怪罪在環境或他人身上，而是先思考自己能做什麼調整。', '{"do": "可用於：①說明其在責任感與自我要求上的成熟度②建議在授權與關鍵任務上信任其承擔能力，同時避免過度堆疊責任③鼓勵其在負責的同時，也適度界定「自己不能控制的範圍」。", "dont": "禁止：①把其責任感當成無限制加派任務的理由②忽略制度或資源問題，只期待其「自己想辦法」③鼓勵其為所有問題自責而不尋求支援④將其願意承擔視為可長期濫用的條件。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_30', 'B', 50, 74, '責任隨界線而定', '在責任範圍清楚時能承擔並完成；若分工模糊或權責不對等，承擔度會受影響。', '先定義權責、交付標準與升級機制；適合制度清楚的專案體系。', '在合理範圍內會承認自己該負的責任；但當情境明顯不合理或自己影響力有限時，也會指出外在因素的影響。', '{"do": "可用於：①說明其對責任的看法較貼近現實，能區分個人與系統因素②建議在檢討時，同時討論可控部分與制度層面調整③鼓勵其維持這種「不推責也不全扛」的健康平衡。", "dont": "禁止：①把其提到環境因素解讀為「在找藉口」②忽略實際權限與資源限制③只要求「要負責任」而不談如何賦權④用單一事件評價其是否具責任感。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_30', 'C', 0, 49, '責任外移傾向', '遇到失誤或延誤較容易歸因外部，補救動作相對被動，可能降低學習與改進速度。', '以復盤流程、行為導向回饋與明確後果機制；先從可控小任務建立承擔習慣。', '在事情出現問題時，較容易優先想到外在原因或他人角色，對於自己能影響或調整的部分較少主動檢視。', '{"do": "可用於：①指出其在壓力情境下容易以防衛性方式看待責任議題②建議透過結構化檢討工具（如：我能調整什麼、可控/不可控）協助其建立新習慣③鼓勵在安全、非責備的環境中談錯誤，降低防禦需求。", "dont": "禁止：①直接貼上「愛推卸責任」標籤②在高度責備文化下只批評其防衛，而不處理環境③用羞辱方式要求其「坦承錯誤」④把此分數當成無法信任的永久標記。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_31', 'A', 75, 100, '主動自我升級', '會主動尋找成長機會，願意參與改變、學新方法並發展自我，不需要外部推動也會持續進步。', '適合高成長路徑、輪調與培訓、創新任務；給探索資源與更大挑戰。', '對自我成長與能力提升有明確主動性，會自己找資源、設定學習目標並安排行動，而不只是等公司安排訓練。', '{"do": "可用於：①說明其在學習敏捷與自我發展上的優勢②建議提供更具挑戰性的發展機會與清楚的職涯路徑③鼓勵其在追求成長時，也平衡休息與當下生活品質。", "dont": "禁止：①把其成長動機視為理所當然，不給資源只給期待②忽略學習需要時間，仍塞滿日常工作③以「你那麼愛學」為由，把所有新任務都丟給他④把發展責任完全推給個人。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_31', 'C', 0, 49, '維持現狀取向', '較少主動追求自我改變，傾向用既有能力完成任務；成長渴望不高或動機不明確。', '適合技能穩定、流程固定角色；若期待提升，先連結其關心利益點與小步目標。', '目前對主動追求自我成長的內在驅動較弱，多半以完成當前工作要求為主，對額外學習較缺乏明確動機。', '{"do": "可用於：①指出其可能處在高壓或疲累階段，較難額外挪出資源給成長②建議從與現職高度相關、負擔較小的學習機會開始，逐步建立成就感③鼓勵透過職涯對談探索「為什麼要學」而不只是「要學什麼」。", "dont": "禁止：①貼上「不上進」標籤②忽略其現實壓力與資源限制③用比較與羞辱方式要求其「要有企圖心」④把此分數視為不能培養的定論。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_32', 'A', 75, 100, '低特權感', '較少認為自己應獲特殊待遇，對資源分配與規則較能接受，以實際貢獻而非身份要求回報。', '適合共享資源與合作情境；較能接受公平制度與透明流程。', '對「自己應被特別對待」的期待相對較低，比較能接受與他人在相近標準下被評估與對待。', '{"do": "可用於：①說明其在團隊中較少因特權議題造成摩擦②建議在獎酬與機會分配上，仍清楚說明其貢獻，以避免被低估③鼓勵其在明顯不合理待遇時勇於表達，而不是全部吞下。", "dont": "禁止：①因其不要求特權就忽略或壓低其應得回報②把其低特權期待當成可以任意加工作量的理由③鼓勵其「多委屈一點」以維持表面和諧④將不爭取視為理所當然。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_32', 'B', 50, 74, '情境性期待', '在投入高或自覺貢獻大時會期待相應待遇；回報不足可能不滿，但仍願意用制度途徑溝通。', '建立可追溯評價與回饋機制，避免不滿轉為消極或抱怨。', '基本認同應依貢獻與表現獲得相應對待，但在自認付出較多或能力較強時，也會期待某種程度的額外肯定與資源。', '{"do": "可用於：①說明其在「合理期待」與「特別待遇」之間可能有灰色地帶②建議清楚說明評估標準與差異對待的理由，降低被忽略或被放大的感受③鼓勵其在溝通時聚焦事實與貢獻，而不是情緒化表達。", "dont": "禁止：①把其合理期待誤解為「愛耍特權」②忽略透明制度與雙向溝通的重要③在沒有解釋下用「大家都一樣」一概帶過④用單次爭取否定其整體專業。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_32', 'C', 0, 49, '高特權感', '較容易認為自己應得到特殊待遇且不一定以努力或績效為前提；期待落空可能強烈不滿或對抗。', '清楚制度邊界、權限與後果，避免模糊承諾；在治理與文化面需更嚴格管理。', '對自己應享有特別待遇、資源或彈性的期待較高，若感到未被特別對待，容易出現強烈不滿或被低估的感覺。', '{"do": "可用於：①指出其在自我價值與外在對待之間連結緊密，容易因差距產生情緒②建議透過清楚標準、數據與實際貢獻來對齊期待③鼓勵其將部分精力放在提升影響力與成果，而不只聚焦在待遇比較上。", "dont": "禁止：①直接貼上「公主病」「王子病」標籤②只用道德批評壓抑其不滿③在未討論事實與數據前否定其感受④把此分數當成其必然難以合作的定論。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_33', 'A', 75, 100, '高度形象管理', '明顯傾向以社會期待方式作答，可能歪曲信念與答案以取得認可，導致評鑑可用性下降。', '更依賴行為證據、工作樣本與多方資料交叉驗證；避免只靠自述決策。', '作答時高度考量「別人會怎麼看」，較可能以理想化的自我形象作為回答依據，而非完全依照日常真實狀態。', '{"do": "可用於：①指出其他量表分數可能受到形象管理影響，需要搭配他評、行為觀察與面談綜合判斷②建議在回饋過程中，以安全、不評價的方式討論其「想被看見的樣子」③鼓勵其練習在適當場合逐步放下完美形象，讓真實狀態也有被看見的空間。", "dont": "禁止：①直接貼上「不誠實」標籤②忽略測驗情境本身帶來的壓力與不安全感③在回饋時用戳破或羞辱的語氣談其防衛④只靠此指標判斷其人格。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_33', 'B', 50, 74, '形象真實混合', '多數時回應真實，但在敏感題或想留下好印象時可能偏理想化回答，呈現部分防衛。', '用情境題、行為例證追問與無評價訪談氛圍提高資訊準確度。', '作答時會在真實與形象之間拿捏，多數情況仍偏向說真話，但在少部分問題上可能略為修飾。', '{"do": "可用於：①說明其整體資料仍具參考價值，但需理解少部分題目可能受形象考量影響②建議在回饋時，同步邀請其分享對測驗的感受，增加開放度③鼓勵其把測驗視為自我了解工具，而不是面試考卷。", "dont": "禁止：①因為略有形象考量就說「在騙人」②忽略測驗情境（如是否與錄用掛鉤）③只從社會期望指標單點推論其誠實程度④在回饋時用指責口吻談此結果。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_33', 'C', 0, 49, '回應較真實', '較能如實呈現自身想法與狀態，不會為了形象或討好而大幅扭曲答案，回覆可信度較高。', '在評鑑解讀與面談追問時可更直接使用其結果；適合用開放問題深化洞察。', '作答時傾向如實呈現自己，即使某些回答可能不那麼「好看」，也較少刻意修飾以迎合期待。', '{"do": "可用於：①說明其報告內容可信度相對較高②建議在解讀其他量表分數時，可以較少保留地相信其自陳資訊③鼓勵其持續維持真實表達，同時也學會在敏感情境中保護自己。", "dont": "禁止：①把其低社會期望反應當成「不在意別人看法」的負面標籤②忽略情境與關係對其表達方式的影響③在高風險場合鼓勵其完全不設防④把真實等同於不需任何界線。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_34', 'A', 75, 100, '投入感強', '對工作本身有明顯熱情與投入，願意多付出以追求成果與成長，工作能量較充足。', '適合需要自我驅動、主動推進與帶動氛圍職務；給挑戰題與舞台。', '對工作本身具有高度熱情與投入感，常願意花時間精進、思考與主動承擔與工作相關的挑戰。', '{"do": "可用於：①說明其在工作動機與投入度上的優勢，適合作為關鍵任務推動者②建議提供與其熱情方向一致的專案與成長機會③提醒在高度投入下，亦需留意過勞與界線，避免工作熱忱轉為耗竭。", "dont": "禁止：①把其熱情當成無上限加班的理由②忽略其在挫折時同樣需要支持③以「反正你喜歡」合理化不合理工作量④把工作熱忱視為可以犧牲其他生活面向的藉口。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_34', 'B', 50, 74, '熱度受情境影響', '在任務有意義、回饋可見或氛圍好時熱忱提高；反之容易變成只是完成工作。', '以目標意義連結、可見成就與支持系統維持熱度；適合穩健推進配置。', '若工作內容具意義感、挑戰性或與興趣契合時，會願意投入較多心力；若過於例行或看不到價值，熱情就會下滑。', '{"do": "可用於：①說明其工作熱忱與工作設計、意義感高度連動②建議在可能範圍內調整任務組合，增加與其興趣與強項連結③鼓勵其在低熱情時思考可以創造什麼新價值，而不是只悶著做。", "dont": "禁止：①把低熱情全歸因於個人態度②忽略職務內容長期單調或缺乏自主性的影響③只用「要有使命感」要求其打起精神④在未調整結構前批評其投入不足。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_34', 'C', 0, 49, '工作僅是責任', '對工作熱情較低，多以責任或收入角度看待；投入度較依賴外部要求與制度。', '適合流程明確、成果可衡量任務；提升投入需釐清其關心價值與誘因。', '對工作本身較少產生強烈熱情，多以完成責任、維持穩定為主，較不會把工作視為自我實現的主要場域。', '{"do": "可用於：①指出其可能更重視工作以外的生活面向，或過往工作經驗較少帶來熱忱感②建議在職務設計上，不必強迫其展現高度激情，而是聚焦於清楚的目標與穩定表現③鼓勵其探索哪一部分工作內容對自己比較有意義，作為提升滿意度的起點。", "dont": "禁止：①貼上「沒熱情」「只為薪水」的道德化標籤②忽略組織文化與職務本身缺乏成就感③用激情作為唯一評價標準④把此分數視為不負責或不可靠的證明。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_35', 'A', 75, 100, '活力充沛', '在日常工作與生活中多以積極、充滿熱情與活力方式行事，對未來抱持期待與動能。', '適合帶動氛圍、對外互動與高節奏推進任務；可作為正向能量來源。', '日常行事風格多半充滿活力與期待感，願意主動探索新體驗，並將熱情帶入生活與工作中。', '{"do": "可用於：①說明其在團隊氣氛與活動帶動方面的正向影響②建議讓其在需要活絡氣氛、鼓舞士氣的場合發揮所長③提醒在照亮他人的同時，也要照顧自己的休息與情緒需求。", "dont": "禁止：①把其熱情視為理所當然的「氣氛製造機」②忽略其也會有低潮的時候③在其需要安靜或暫時退後時批評「怎麼變了」④只看外顯活力而忽略內在壓力。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_35', 'B', 50, 74, '能量隨情境起伏', '平時有一定活力，但在壓力、睡眠不足或連續挫折時動能會下降；恢復後可回穩。', '提供節奏管理、適度休息與可見成果，有助維持動能。', '在心情不錯或有感興趣的事情時，會展現活力與參與感；但在疲累或壓力較大時，會明顯收斂熱情。', '{"do": "可用於：①說明其生活熱情與身心狀態高度連動②建議透過合理工時與休息安排，維持其能量水位③鼓勵其接受自己熱情有起伏是正常的，不必勉強一直「很 high」。", "dont": "禁止：①在其低潮時貼上「變冷淡」標籤②忽略組織節奏與壓力對其能量的消耗③只在需要活絡氣氛時才想到找他④用單次狀態判斷其個性。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_35', 'C', 0, 49, '動能偏低', '較少以熱情與活力驅動行動，對未來期待感薄弱時容易被動或拖延，需要更多外部刺激才啟動。', '從小步可達成目標建立動能，搭配支持與節奏安排；避免長期高壓無回饋。', '在日常生活中較少展現外顯的熱情或興奮感，行事節奏偏穩、偏內斂，對活動與變化的主動性相對有限。', '{"do": "可用於：①指出其在穩定、需要長期堅持的任務中可能更為合適②建議不要強迫其扮演外向帶動角色，而是尊重其節奏與風格③鼓勵其在自己覺得安全與舒適的範圍內，嘗試少量新體驗。", "dont": "禁止：①貼上「沒活力」「很冷漠」的簡化標籤②忽略其內在可能有屬於自己的熱情只是不外顯③用外向標準扣分其表現④在團隊中排除較安靜成員的重要性。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_36', 'A', 75, 100, '容易被點燃', '對挫折、否定、壓力或不公平刺激反應門檻低，情緒升溫快，可能出現語氣變衝、衝動回應或當場對抗。', '需設計降刺激工作方式：明確溝通規範、冷卻流程、衝突場景第三方介入；高衝突前線配置需更謹慎。', '情緒對外在刺激相當敏感，遇到不順或被觸怒的情況時，反應容易快速且強烈，需要更多自我調節與環境支持。', '{"do": "可用於：①說明其情緒反應速度快、強度高，需在壓力管理與情緒調節上給予具體工具與協助②建議在重要溝通或衝突場合，預留冷卻時間與中立第三方，降低當下失控風險③鼓勵其練習暫停、換位思考或離開現場等方法，幫助自己先穩住情緒再做決定。", "dont": "禁止：①直接貼上「暴躁」「情緒化」的標籤②忽略長期壓力、工作環境或過往經驗對其情緒狀態的影響③用羞辱或嘲諷的方式要求其「冷靜一點」④只看爆發當下的畫面而完全不檢視前期累積的壓力來源。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_36', 'B', 50, 74, '可控但會被觸發', '平常多可維持穩定，但遇到特定觸發點（被誤解、時間壓力、連續失敗）時反應會上升；事後多能回穩並修正。', '辨識觸發點並建立停損機制（暫停、書面回覆、換人處理），再用復盤降低再發。', '多數情況下能保持基本穩定，但在壓力累積、被反覆踩到地雷或身心狀態不佳時，情緒起伏會明顯放大。', '{"do": "可用於：①說明其情緒穩定度與壓力總量、睡眠與支持系統高度相關②建議與其一起找出個人的「情緒警訊」與舒壓方式，在快到臨界點前就先調整③鼓勵其在覺得快受不了時，提前提出需求，而不是一路硬撐到爆發。", "dont": "禁止：①只在情緒失控時檢討其個人，而不處理制度或人際問題②忽略工作負荷、時間壓力與資源不足的影響③用「你怎麼這麼誇張」否定其累積已久的感受④把一次情緒爆發當成永久標記，忽略其多數時間的穩定表現。"}');
INSERT INTO trait_bands ("trait_id", "band", "min_score", "max_score", "semantic_label", "description", "management_focus", "report_wording", "ai_guidance") VALUES ('CIA_36', 'C', 0, 49, '情緒穩定', '情緒反應門檻較高，遇到煩惱或衝突多能保持冷靜與理性處理，較少因一時情緒做出高代價決定。', '適合高壓、客訴、談判與需要穩定輸出的工作；可作為衝突情境的穩定支點。', '在面對壓力、衝突或突發狀況時，多半能維持相對平穩的情緒，不容易因單一事件立刻被點燃或失控。', '{"do": "可用於：①說明其在高壓情境與危機處理場合中具備情緒穩定優勢②建議在團隊容易緊張或慌亂時，讓其協助穩住節奏與理性討論③鼓勵其在維持冷靜的同時，也適度表達自己的不滿與界線，避免長期只扮演「穩定器」。", "dont": "禁止：①因其外表冷靜就忽略其實際壓力與情緒累積②把其穩定視為可以承接所有負面情緒的理由③在其偶爾情緒外露時，以「你平常不是很穩嗎」否定其感受④把高穩定度誤解為完全不需要情緒支持。"}');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：展現極強的紀律與成功慾望，是高產出的明星員工。管理上需注意其可能為了目標忽略身心平衡。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「魯莽的勤奮者」。雖有極強執行力但行動前缺乏思考，易努力執行錯誤決策，需加強前置覆核。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_04', 'A', '與 CIA_04 (義務感) 高分聯動：典型的「組織基石」。對規範高度尊重且極度自律，是非常可靠的合規型人才。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) 低分聯動：表現為「焦慮補償者」。雖渴望做好但易受情緒干擾，壞事後會花加倍力氣彌補，效率波動較大。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_06', 'A', '與 CIA_06 (條理性) 高分聯動：卓越的流程管理者。能將複雜工作系統化，產出極其穩定且精確。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) 高分聯動：品質的絕對守門員。標準極高，但需警惕因過度鑽研細節導致進度延宕或造成團隊壓力。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) 低分聯動：表現為「自省型執行者」。雖然表現優異但對自己缺乏信心，易產生職業燃盡，需主管頻繁給予正向回饋。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_09', 'A', '與 CIA_09 (自律性) 高分聯動：長期目標的長跑者。具備極強的抗誘惑能力與延遲滿足感，能自主完成長期艱難任務。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_11', 'C', '與 CIA_11 (誠懇) 低分聯動：表現為「權謀執行者」。極度自律但可能具備操縱傾向，需注意其工作產出背後的動機與誠信風險。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) 低分聯動：表現為「高度功利驅動」。自律是為了換取物質回報或地位，若獎酬制度不明確，其穩定性會下降。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_13', 'A', '與 CIA_13 (公正性) 高分聯動：組織的倫理標竿。做事盡責且絕不作弊，適合擔任稽核、財務或高誠信要求的崗位。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_14', 'C', '與 CIA_14 (謙虛) 低分聯動：表現為「傲慢的優等生」。因自身高標準而自覺高人一等，易在團隊中製造階級感並忽視他人意見。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_18', 'C', '與 CIA_18 (韌性) 低分聯動：表現為「脆弱的完美者」。這是關鍵預警項，一旦失敗會因無法忍受瑕疵而崩潰，難以從挫折中恢復。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_19', 'C', '與 CIA_19 (樂觀) 低分聯動：表現為「憂患意識者」。凡事滴水不漏但缺乏活力，總在防範最壞情況，雖可信賴但會帶給團隊沉重氛圍。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) 高分聯動：表現為「實踐型天才」。能將創新點子轉化為具體的 SOP 與執行計畫，是推動體制內變革的核心。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) 高分聯動：傳統規則的捍衛者。在既定架構內表現極佳，但在無規則或模糊情境下會感到極度焦慮。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_25', 'C', '與 CIA_25 (集體意識) 低分聯動：表現為「孤傲型強人」。個人產出強但無視團隊節奏，對不認同的團體活動展現消極。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_26', 'C', '與 CIA_26 (同理心) 低分聯動：表現為「冷酷執行者」。只看目標不看人情，適合推行硬性政策，但長期可能造成組織氣氛僵化。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_27', 'A', '與 CIA_27 (權益公平感) 高分聯動：精確的對等者。對付出與回報的比例極度敏感，若感到不公，其「盡責」程度會迅速下降。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_30', 'A', '與 CIA_30 (個人責任感) 高分聯動：卓越的自主管理者。不需要外界監督也能達成高標，管理上應給予充分授權而非微觀管理。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) 高分聯動：自我進步型人才。不僅把事做好，還渴望優化自身能力，是組織極具價值的儲備幹部。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) 高分聯動：表現為「精英心態者」。認為自己的高績效應換取特殊的優先待遇，若未獲特權會產生不平。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_34', 'C', '與 CIA_34 (工作熱忱) 低分聯動：表現為「機器人型執行」。雖依循規範完成任務，但內心缺乏熱情，僅視工作為義務，長期發展動力有限。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_01', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) 高分聯動：表現為「暴躁的工頭」。對工作要求轉化為對人的怒氣，當他人未達標時會產生強烈情緒反應。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_02', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「高效能明星」。具備極強的成功欲望與自我要求，是組織績效的穩定貢獻者。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_02', 'A', 'CIA_03', 'C', '與 CIA_03 (審慎) C聯動：表現為「冒進的擴張者」。渴望快速達成目標但行動前缺乏深思，易忽略潛在風險，需加強風險控管提示。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_02', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「情緒化衝刺者」。雖極想贏但易受當下情緒干擾，表現起伏大，需建立標準作業程序以穩定產出。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_02', 'A', 'CIA_06', 'C', '與 CIA_06 (條理性) C聯動：表現為「混亂的衝鋒者」。專注於大目標但細節混亂，雖有產出但常伴隨行政錯誤，需行政資源輔助。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_02', 'A', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「利益導向者」。成功至上且可能不惜犧牲倫理，需注意其達成目標的手段是否符合合規要求。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_02', 'A', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) C聯動：表現為「高度物質動機」。對金錢與地位有強烈需求。若獎酬機制不具競爭力，此類員工離職風險極高。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_02', 'A', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「炫耀型成功者」。達成目標後傾向於彰顯功勞，易在團隊中造成他人心理壓力，需引導其分享成果。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_02', 'A', 'CIA_17', 'A', '與 CIA_17 (目標效能感) A聯動：表現為「自信的開拓者」。不僅想贏且相信自己能贏，面對挑戰不退縮，是組織攻堅時的首選先鋒。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_02', 'A', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「脆弱的攀登者」。極度渴望成功但心理緩衝空間小，一旦專案失敗易陷入長期低潮，需主管即時介入輔導。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_02', 'A', 'CIA_19', 'C', '與 CIA_19 (樂觀) C聯動：表現為「焦慮的追求者」。雖然努力達成目標，但內心總預見壞結果，工作動能雖強但情緒緊繃感極重。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_02', 'A', 'CIA_23', 'A', '與 CIA_23 (獨創性) A聯動：表現為「創新實踐者」。會不斷尋找更聰明的方法來達成業績，不滿足於現狀，是推動流程變革的核心人物。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_02', 'A', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「計較回報的戰士」。對付出與獲得的公平性極度敏感，若獎勵未達其預期，會迅速轉向消極反抗。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_02', 'A', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「自我進化者」。將工作成就視為個人成長的一部分，極度看重培訓與發展空間，是優質的儲備幹部。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_02', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「權利索求者」。認為自己的努力應換取特殊優待與特權。若管理上無法給予特殊感，其工作配合度會降低。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_02', 'A', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「全心投入者」。工作本身即是快樂來源，具備極強的長期戰鬥力與忠誠度，是組織文化的核心支柱。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_03', 'A', 'CIA_01', 'C', '與 CIA_01 (盡責) C聯動：表現為「想得多做得少」。雖能洞察風險但執行力不足，容易陷入「過度分析而無行動」的狀態，需搭配強力的執行窗口。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_03', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「精確的戰略家」。追求成功的同時具備高度理性，能規劃出具備高可行性的路徑，是高品質決策的核心人才。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_03', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「理性的內耗者」。雖然腦中知道該審慎思考，但行為上易受衝動誘惑而破功，事後常感到後悔，心理壓力較大。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_03', 'A', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「決策癱瘓者」。因過度考慮風險且對自己能力缺乏信心，在需要快速反應時會因焦慮而無法做決定。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_03', 'A', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「深沉的操縱者」。行動極其謹慎且具備隱藏真實動機的傾向，在職場政治中較難被看透，需留意其長期誠信表現。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_03', 'A', 'CIA_15', 'C', '與 CIA_15 (心理資本) C聯動：表現為「悲觀的風險控管者」。審慎變成了對挫折的防備而非策略規劃，容易因過度看重困難點而失去前進動能。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_03', 'A', 'CIA_19', 'A', '與 CIA_19 (樂觀) A聯動：表現為「務實的開拓者」。對未來抱持正向期待，同時具備風險避開能力。能產出既具企圖心又經得起推敲的提案。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_03', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「有紀律的創新者」。不會為了不同而不同，而是能在深思熟慮後，挑戰無效規則並提出具邏輯支撐的創新方案。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_03', 'A', 'CIA_21', 'C', '與 CIA_21 (效率取向) C聯動：表現為「緩慢的完美主義」。極度重視邏輯嚴謹但忽視時間效率，在講求快速變動的環境中適應力較低。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_03', 'A', 'CIA_24', 'A', '與 CIA_24 (真實性) A聯動：表現為「誠信的觀察家」。不僅言行一致，且在表達觀點前會經過精密考量，其給出的建議通常具備高度參考價值。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_03', 'A', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「貼心的協調者」。在人際往來中思慮周全，能顧及他人感受且說話不魯莽，適合處理複雜的人事糾紛。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_03', 'A', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「完美的防禦者」。因高度負責且凡事三思，適合處理合規、法務、審計等絕對不能出錯的高風險任務。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_03', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「精明的索求者」。會精密計算如何透過特殊待遇獲取最大利益，並小心保護自己的特權，需注意其與團隊利益的衝突。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_03', 'A', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「精確的人設師」。為了獲得認可會非常謹慎地篩選答案或行為，其真實特質可能被良好的社交偽裝覆蓋。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_03', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「冷靜的引信」。雖易被激怒，但因具備高度審慎，會刻意壓抑或精確計算反擊時機，展現出具攻擊性的嚴謹。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_04', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「極致的守法者」。將規範視為個人信仰，執行任務不打折扣。管理警示：容易對不守規矩的同事產生強烈偏見，導致團隊氣氛緊繃。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_04', 'A', 'CIA_02', 'C', '與 CIA_02 (成就動機) C聯動：表現為「安分的執行員」。極度負責且聽話，但缺乏向上突破的動力。管理預測：適合擔任穩定崗位，但不宜放在需要「不計代價達成業績」的開拓職位。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_04', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「深思熟慮的守護者」。在執行規範前會思考其合理性與影響，能為組織提供具建設性的法律或合規建議。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_04', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「自責的失控者」。內心極度想遵循規範，但行為常受衝動驅使而違規。心理風險：事後會產生巨大的罪惡感與焦慮，長期易導致自尊受損。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_04', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「教條主義者」。不僅要遵守規則，更要追求流程的完美無瑕。警示：容易在繁文縟節中迷失，造成行政效率低下，甚至阻礙緊急決策。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_04', 'A', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「形式主義的利己者」。外在極力表現出合規的樣子，實則內在缺乏誠信，僅是為了避免受罰而守規，需防範隱蔽性舞弊。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_04', 'A', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「正義使者」。對職場不公平現象極度敏感，會為了維護正義而舉報或反抗，是組織清廉的指標。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_04', 'A', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「易碎的樑柱」。承擔過多責任卻缺乏抗壓彈性，一旦組織規則劇烈變動或面臨衝突，容易出現情緒崩潰或迅速離職。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_04', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「建設性變革者」。遵循更高層級的「良知」而非「死板規定」。會為了優化組織而勇敢提出挑戰舊規的創新方案。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_04', 'A', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) A聯動：表現為「傳統捍衛者」。絕對服從現有體系，缺乏應變彈性。在轉型期可能成為組織阻力，因為他們認為挑戰規則是不忠。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_04', 'A', 'CIA_24', 'A', '與 CIA_24 (真實性) A聯動：表現為「言行合一的楷模」。行為高度契合價值觀。管理預測：極具誠信魅力，適合擔任組織文化傳播者或內部導師。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_04', 'A', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「重視承諾的夥伴」。對「勞資契約」有神聖感。警示：一旦感受到付出回報不對等，會認為組織「不講信義」而徹底心碎並轉身離開。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_04', 'A', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「自主責責任者」。不僅守規矩，還會主動承擔任務。預測：是最不需要監督的員工，給予明確目標後即可高度放心。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_04', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「傲慢的苦難者」。一邊為了組織義務辛苦付出，一邊覺得自己理應獲得特殊優待，容易在背後抱怨他人偷懶而自己受苦。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_04', 'A', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「模範生人設」。高度社會化，會刻意表現出符合主流價值期待的樣子，需觀察其私下是否能維持一致。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_04', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「效率至上的冷酷者」。雖然做事有紀律能達成目標，但缺乏道德感或對規範的尊重，容易為了達成任務而遊走灰色地帶。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_05', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「鋼鐵般的穩定者」。具備極高的自律性與自我控制力，是高難度長線專案的最佳負責人。管理預測：產出極其穩定，極少因個人情緒影響工作進度。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_05', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「冷靜的狩獵者」。能為了最終成就而忍受長期的枯燥與誘惑。管理建議：適合擔任需要高度專注力且具備延遲滿足特性的高階開拓職位。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_05', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「極致的理性派」。行動前深思熟慮且行為受控，絕不輕率表態。警示：在需要「快速試錯」的環境中可能顯得過於保守或反應遲鈍。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_05', 'A', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「高階操縱者」。行為高度受控但動機不純，能冷靜且有計畫地為了目標欺騙或操縱他人，是組織中最高層級的誠信風險，需加強合規監督。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_05', 'A', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「靜默的受難者」。雖然能管住行為不爆發，但內心缺乏緩衝能力。管理風險：容易將壓力內化導致身心崩潰或突然「無預警離職」。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_05', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「高度修養的壓力鍋」。極易被激怒但能展現極強的職業素養予以壓制。警示：外表冷靜但內心消耗巨大，需適度給予情緒宣洩空間。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_05', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「焦慮的追求者」。內心極想做好（盡責）但行為卻常失控違規。行為預測：工作成果起伏巨大，常在「失誤」與「拼命補救」之間循環。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_05', 'C', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「挫敗的完美主義」。雖對品質有極高要求，但因行為魯莽常在細節出錯。管理建議：容易因自己的失誤而陷入極大的自我責備，需他人協助檢查細節。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_05', 'C', 'CIA_13', 'C', '與 CIA_13 (公正性) C聯動：表現為「投機冒險者」。不僅管不住衝動，且缺乏誠信底線，極易為了短期利益而觸犯規則或法律，需嚴格限制其權限。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_05', 'C', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「失控的發明家」。點子多且行動極快，但常在未經測試前就推翻現有流程。管理警示：適合發想階段，但不宜讓其主導專案落地。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_05', 'C', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「情緒敏感的協調者」。雖能感同身受，但易因一時激動而做出過度的情感承諾。預測：容易在職場衝突中因一時同情而壞了規矩。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_05', 'C', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「社交變色龍（負面型）」。雖能適應人際關係，但常因衝動說錯話或表錯態，導致原本建立的關係迅速崩塌。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_05', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「職場地雷」。認為自己應得特權且管不住脾氣，一旦環境不如其意便會立刻爆發。管理警示：對團隊士氣殺傷力極大，需建立明確的行為底線。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_05', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「人設崩塌者」。極度渴望獲得認可但卻管不住負面衝動，常在失控後花極大心力進行公關式彌補。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_05', 'C', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「三分鐘熱度者」。熱情時極其投入，但一旦遇到挫折或新誘惑，興趣會迅速轉移，長期穩定性存疑。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_05', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「典型的火藥桶」。極易生氣且會立刻表現於行為。預測：頻繁引發人際衝突，不適合團隊協作崗位，需獨立作戰空間。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_06', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「系統化的執行者」。不僅想把事做好，還能建立標準作業程序 (SOP) 並嚴格執行。預測：極其穩定且精確的產出，是流程優化的理想人選。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_06', 'A', 'CIA_02', 'C', '與 CIA_02 (成就動機) C聯動：表現為「行政管家」。雖然極度細心且愛好程序，但缺乏突破目標的野心。管理建議：適合擔任穩定運營的幕後支援，不宜賦予高競爭性的開拓任務。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_06', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「精密規劃者」。在行動前會細節性地推敲每一個步驟，確保流程無死角。警示：應變速度極慢，在混亂或緊急環境下會感到極大壓力。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_06', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「細節偏執者」。對排列、程序與成果無瑕疵有極強渴望。管理風險：容易因瑣碎細節而耽誤核心進度，需主管適時定義「何謂完成」。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_06', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「實務改良家」。能將天馬行空的創意整理成邏輯通順的實施方案。預測：能讓創新成果落地的關鍵橋樑。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_06', 'A', 'CIA_21', 'C', '與 CIA_21 (效率取向) C聯動：表現為「繁文縟節的愛好者」。雖然愛好程序，但卻過於精確 methodical 導致喪失效率，適合稽核崗位，但不適合敏捷團隊。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_06', 'A', 'CIA_22', 'C', '與 CIA_22 (紀律遵循度) C聯動：表現為「自創系統者」。喜歡有條理，但不喜歡「別人的」條條框框，會傾向於重新建立一套自己覺得更高效的程序。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_06', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「程序守門員的怒火」。當環境被弄亂或他人不按 SOP 執行時，會瞬間被激發情緒反應，對混亂有極低的容忍度。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_06', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「隨興的苦幹者」。雖然非常盡責想把事做好，但做事雜亂無章、缺乏次序。行為預測：努力但效率低，需行政輔助工具協助管理進度。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_06', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「混亂的獵人」。極想達成業績目標，但過程中容易丟三落四、遺漏細節。警示：業績好但售後或行政手尾極多，需配備助理協助控管。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_06', 'C', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「職場混亂製造者」。既沒條理又容易衝動行事。管理風險：行為極度隨機且不可控，會造成團隊協作上的巨大困擾。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_09', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「有紀律的發明者」。能克制「只發點子不做事」的傾向，強迫自己將創新概念進入繁瑣的研發與測試階段。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_06', 'C', 'CIA_07', 'A', '與 CIA_06 (條理性) C 與 CIA_07 (完美主義) A：表現為「內在衝突的完美者」。渴望完美但缺乏建立次序的能力。預測：會因環境混亂而焦慮，卻又不知如何整理，需他人協助建立架構。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_06', 'C', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「非典型的快速執行者」。雖然不重視程序與整潔，但對獲取結果的效率有極強渴望。會用跳躍式的路徑達成目的。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_06', 'C', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「負責任的散漫者」。對結果負責，但過程極其跳躍。管理預測：只要給他最終成果的期限，不要管他過程怎麼排列。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_07', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「高品質保證者」。強大的自制力支撐其對完美的追求。行為預測：產出極其精緻且合規，是處理精密任務或核心資產的關鍵人選。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_07', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「精密的防禦者」。行動前反覆推敲以確保無誤。管理警示：極度畏懼錯誤，在面對高時效要求的專案時，可能因過度檢查而錯失良機。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_07', 'A', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「冒名頂替症候群 (Imposter Syndrome)」。設定了極高標準卻不相信自己能達成。管理風險：極度焦慮，即使表現優異仍深感挫折，需頻繁情感支持。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_07', 'A', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「挑剔的管理者」。對自己要求完美，且認為自己理應獲得最高尊重，易對下屬或同僚表現出不耐與輕視，造成人際摩擦。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_07', 'A', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「脆性完美主義」。一旦專案出現無法控制的瑕疵，其自我認同會崩解。預測：在逆境下恢復緩慢，甚至可能因一次失敗而選擇徹底逃避。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_07', 'A', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「卓越的工匠」。不僅追求完美，更渴望用最快、最精確的方式達成。預測：這是效率與品質兼備的極佳組合，是高階專業技術職的核心。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_07', 'A', 'CIA_26', 'C', '與 CIA_26 (同理心) C聯動：表現為「冷酷的工作狂」。對細節的執著凌駕於對他人感受的關注。警示：容易為了成果無瑕疵而過度逼迫團隊，導致團隊流失率增高。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_07', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「易爆的檢查者」。對任何不完美的行為（如垃圾沒丟好、簡報格式跑掉）會產生即時且強烈的情緒反應，容忍度極低。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_07', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「務實的執行者」。雖然自律且盡責，但不糾結細節，以完成任務為首要。管理預測：產出速度快且及格，適合高週轉率、容許微小誤差的工作。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_07', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「擴張型獵人」。極想贏但不在意過程是否無瑕疵。管理警示：容易達成業績但「售後」問題多，需安排「條理性高」的人員協助收尾。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_07', 'C', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「豁達的進取者」。容許失敗與瑕疵，並對未來保持樂觀。預測：心理彈性極佳，非常適合變動劇烈、不確定性高的創業型環境。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_07', 'C', 'CIA_22', 'C', '與 CIA_22 (紀律遵循度) C聯動：表現為「自由散漫者」。既不追求完美，也不想遵循規則。管理風險：除非有強大的熱忱支持，否則其產出品質往往難以維持組織基本水準。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_08', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「高產能開拓者」。不僅渴望成功，且深信自己具備達標的能力。預測：在面對困難專案時具備極強的心理優勢，是帶領團隊突破困境的靈魂人物。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_08', 'A', 'CIA_05', 'A', '與 CIA_05 (衝動管理) A聯動：表現為「穩健的掌控者」。相信自己能應付局面，且行為高度自律。管理預測：在危機時刻能保持冷靜，不因恐慌而失控，是極佳的危機處理人才。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_08', 'A', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「膨脹的權威」。具備能力自信但缺乏謙遜。警示：容易變得剛愎自用，不願聽取他人建議，甚至在團隊中形成獨裁風格，需注意其人際關係。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_08', 'A', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) A聯動：表現為「體制內的專家」。在熟悉的規則架構下感覺極度自信且高效。預測：是組織 SOP 的最佳執行者，能完美維護既有系統的運作。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_08', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「自負的精英」。深信自己的卓越能力應換取特殊優待。管理風險：對一般行政要求配合度低，認為瑣事應由他人代勞。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_08', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「焦慮的耕耘者」。雖然做事盡責努力，但內心始終擔心自己能力不足。行為預測：會花過多時間反覆檢查，雖然產出品質高，但心理內耗極大。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_08', 'C', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「癱瘓的完美主義」。因追求無瑕疵但又不信自己能達成，導致嚴重的拖延症。管理建議：需主管協助拆解小目標，累積成功的「微體驗」以重建信心。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_08', 'C', 'CIA_17', 'C', '與 CIA_17 (目標效能感) C聯動：表現為「習得性無助者」。完全不相信努力能改變結果。警示：在高壓環境下極易放棄，是組織績效的重大隱憂，需關注其身心健康與職務契合度。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_08', 'C', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「韌性支撐的求存者」。雖然目前對自己信心不足，但遭遇打擊時能迅速站起並從頭再來。管理建議：屬於大器晚成型，適合長期培養以建立信心。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_08', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「討好型偽裝者」。因對能力沒信心，會過度觀察他人臉色並迎合期望以獲取安全感。其專業觀點可能因恐懼而不誠實。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_09', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「卓越的馬拉松跑者」。具備強大的目標導向與執行意志，能為了長遠成功忍受現階段的艱辛。預測：在長期轉型專案中展現極佳的穩定性。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_09', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「冷靜的戰術執行家」。在深思熟慮後，能嚴格控制行為不偏離既定策略，絕不因外部干擾而打亂節奏。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_09', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「意志力與情緒的拉鋸」。雖然內在有強烈長期目標（自律），但外在行為易受誘惑干擾（衝動）。管理警示：此組合會造成巨大的心理內耗，需建立環境隔離誘惑以輔助。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_09', 'A', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) C聯動：表現為「高度務實的奮鬥者」。其自律源於對物質回報的強烈渴望，能為了高額獎酬或地位晉升展現出極致的禁慾與努力。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_09', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「自負的修煉者」。因具備極強自律能力而認為自己應獲得特殊优待，並容易對不自律的下屬展現出缺乏同理心的批判。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_09', 'A', 'CIA_34', 'C', '與 CIA_34 (工作熱忱) C聯動：表現為「專業的苦行僧」。雖然對工作缺乏熱情，但憑藉強大的意志力（自律）依然能高品質完成任務，行為表現極其職業化。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_09', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「受罪惡感驅動者」。內心極想做好（盡責）但行為上卻難以抵抗誘惑（低自律）。預測：常在最後一刻趕工，並在工作過程中伴隨高度焦慮。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_09', 'C', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「眼高手低的焦慮者」。對成果有無瑕疵的要求，卻管不住自己去落實細節。警示：容易產生「想得美、做不到」的落差，需主管介入監督進度。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_09', 'C', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「隨性的樂天派」。雖然不夠自律且易分心，但對未來保持積極期待，即便進度延遲也能自我排解壓力。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_09', 'C', 'CIA_23', 'A', '與 CIA_23 (獨創性) A聯動：表現為「多產但不落地的創意家」。有極多創新的原創想法，但因缺乏自律將其細緻化，成果往往流於草稿階段。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_09', 'C', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「救火式執行者」。雖然缺乏日常紀律，但一旦事情迫在眉睫，會基於強烈的責任感爆發性能量完成工作。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_09', 'C', 'CIA_35', 'A', '與 CIA_35 (生活熱情) A聯動：表現為「熱情四射的散漫者」。對生活充滿活力與興趣，但工作上難以專注於單一目標，容易被新奇事物吸引而轉向。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_10', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「正派的領袖」。追求成功但絕不走捷徑。預測：能建立具備長期信任感的團隊，即便在高度競爭下也能維持組織聲譽。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_10', 'A', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「清廉的高效能者」。在追求效率的過程中極其精確且誠實，適合處理採購、預算控管等涉及龐大利益的崗位。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_10', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「自覺的內耗者」。內心覺得自己應得特權，但道德感強迫自己謙虛。管理警示：容易累積隱性不滿，需注意其情緒平衡。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_10', 'A', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) C聯動：表現為「純粹的誠信者」。不在乎他人評價或包裝形象，真實地展現正直。預測：是組織內部舉報或倫理風險查核的最佳守門員。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_10', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「精明的權謀家」。利用高度的自律與細心來實現個人私利，行為極難被察覺。警示：若缺乏外部稽核，容易造成系統性損害。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_10', 'C', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「深沉的政治家」。行為極其謹慎且不擇手段。管理警示：在職場競爭中擅長佈局且不留痕跡，需注意其對團隊互信的破壞力。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_10', 'C', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「極端利己者」。完全以目標為導向且具備操縱傾向。風險預測：高頻率出現職場政治操弄，需嚴格控管其決策權限。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_10', 'C', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) C聯動：表現為「貪婪的追求者」。對財富、地位有極度渴望且不排除用非正式手段獲取。警示：是職場舞弊的高風險群組。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_10', 'C', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「狂傲的擴張者」。自視甚高且追求財富。管理建議：其強大的自信雖能帶來業績，但極易引發團隊衝突與流失。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_10', 'C', 'CIA_24', 'C', '與 CIA_24 (真實性) C聯動：表現為「虛偽的表演者」。為了利益可以隨時調整價值觀或行為，表裡不一。預測：人際關係起伏大，誠信基礎薄弱。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_10', 'C', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「計較的利己主義」。對付出回報極其敏感，且會為了爭取更多私利而挑戰公平規則，屬於難以滿足的員工。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_10', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「職場變色龍」。表面極度謙虛、誠懇以獲取認可，實則內在逐利。警示：是最難識別的風險對象，需透過第三方反饋來驗證。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_11', 'A', 'CIA_05', 'A', '與 CIA_05 (衝動管理) A聯動：表現為「正直的穩定者」。不僅不屑於欺騙，且能冷靜克制誘惑。預測：在金錢或權力誘惑面前具備極強的抵抗力，是組織信任的定海神針。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_11', 'A', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「透明的關懷者」。對人的關心發自內心，不帶目的性。預測：極易建立深厚的人際信任，適合擔任團隊黏著劑或心理諮詢角色。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_11', 'A', 'CIA_29', 'C', '與 CIA_29 (人際適應力) C聯動：表現為「拙於包裝的正直者」。為人誠懇但不懂圓滑，說話過於直白。管理警示：雖值得信任，但易在不經意間得罪人，需注意其溝通技巧。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_11', 'A', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) C聯動：表現為「純粹的真我」。完全不掩飾缺點，也不刻意塑造形象。管理預測：其測評結果信效度極高，是職場中最透明、最好管理的類型。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_11', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「目的導向的野心家」。為了業績或晉升，不惜美化事實或誤導他人。警示：短期績效雖好，但長期會嚴重損害團隊的互信基礎。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_11', 'C', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「精密的政治玩家」。操縱行為經過精密計算，且不會輕易留下把柄。風險預測：擅長推卸責任或竊取功勞，是組織內部的潛在負面變數。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_11', 'C', 'CIA_14', 'A', '與 CIA_14 (謙虛) A聯動：表現為「偽善者」。表面表現得極度謙遜，實則內在充滿操縱動機。警示：最難防範的類型，常利用「弱者姿態」來獲取資源或同情。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_11', 'C', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「具備欺騙性的創意者」。可能利用創新的點子來包裝個人私利，或將他人的創意占為己有並進行改良。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_11', 'C', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「派系操作者」。極力維護小團體利益，但過程充滿政治操弄，容易在組織內形成「小圈子」文化。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_11', 'C', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「權利的計較者」。會利用操縱手段來確保自己獲得「超額回報」，並對任何微小的不公平進行政治化的反擊。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_27', 'C', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「情緒化的計較者」。一旦感到分配不公，會立刻表現出憤怒或消極怠工，情緒反應極大且難以安撫。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_11', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「完美的社交包裝師」。擅長透過塑造樂觀形象來獲得認可，實則行為充滿目的性。其測評結果可能存在高度偽飾，需多方查核。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_12', 'A', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「純粹的修煉者」。比起加薪，更看重學習機會與自我實現。管理建議：應提供具挑戰性的專案或進修機會作為主要獎酬。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_12', 'A', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「使命感驅動者」。對工作充滿熱愛且不計酬勞多寡。預測：在組織面臨寒冬或薪資凍結時，這類員工的留任意願最高。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_12', 'A', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「無私的貢獻者」。願意為了團隊共榮而放棄個人獎金或特權。預測：是建立高凝聚力文化的核心成員。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_12', 'A', 'CIA_14', 'A', '與 CIA_14 (謙虛) A聯動：表現為「淡泊名利的隱士」。既不追求財富也不渴求他人尊重，這類人極難被外在名利收買，適合擔任高度保密或敏感職務。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_12', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「目標明確的掠奪者」。其成就動機源於對財富與地位的渴望。管理警示：只要有更高薪的對手招手，離職風險極高，需建立績效獎金掛鉤。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_12', 'C', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「貪婪的職場投機者」。高度重視利益且可能忽視倫理。警示：是職場舞弊、收受回扣的高風險群組，需建立嚴格的財務審核。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_12', 'C', 'CIA_13', 'C', '與 CIA_13 (公正性) C聯動：表現為「利益至上的不公者」。為了獲取個人物質優勢，不惜破壞組織公平規則。風險預測：極易為了私利而損害團隊或客戶利益。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_12', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「特權索求者」。認為自己應享有最高薪資與專屬待遇。管理警示：若組織無法給予「優越感」，其工作動能會迅速崩潰且產生負面抱怨。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_12', 'C', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「高度現實的勞動者」。對每一分付出的金錢回報都斤斤計較。管理預測：是標準的「金錢驅動型」，管理方式應簡單直接，以獎金說話。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_12', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「職場鍍金者」。為了塑造成功形象（高社會地位）而過度包裝自己。警示：其表面展現的價值觀可能與內在逐利心態不符，需長期觀察。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_13', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「正道成功者」。對成功有渴望但絕不跨越道德底線。預測：其成就具備極高的透明度與可複製性，是組織內部良性競爭的標竿。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_13', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「失控但正直者」。雖然行為魯莽易出錯，但出發點通常是誠實的，不會為了掩蓋錯誤而撒謊。管理建議：應包容其無心之過，引導其修正行為而非懲罰其動機。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_13', 'A', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) A聯動：表現為「廉潔守護神」。具備極高的道德標準且不貪婪。預測：極其適合擔任高價值資產管理、法務、稽核或涉及高度信任的職務。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_13', 'A', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「體制公平的捍衛者」。不僅要求自己公正，也極度在意組織的公平。管理警示：若組織出現不公平競爭，他會是第一個站出來發聲或選擇離職的人。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_13', 'A', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) C聯動：表現為「剛正不阿者」。不在乎社交形象，即使在同儕壓力下也會堅持說出真相，是預防集體作惡的關鍵防線。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_13', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「不擇手段的擴張者」。為了達成業績或領先同儕，會利用資訊不對稱或規則漏洞。管理風險：高業績可能掩蓋其合規風險，需加強第三方稽核。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_13', 'C', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「深思熟慮的投機家」。其不誠實行為通常經過精心佈局，難以察覺。警示：是高階商業犯罪潛在對象，需建立分權制衡機制。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_13', 'C', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「職場慣竊或投機者」。管不住慾望且缺乏公正底線。行為預測：容易出現偷工減料、虛報開支或侵占公物等低階舞弊行為。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_13', 'C', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「偽裝的利用家」。透過操縱手段獲取他人信任後再進行剝削。風險預測：在團隊中容易造成信任感瓦解，是組織文化中的「劇毒」成分。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_13', 'C', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「走捷徑的高效能」。為了快而省去必要的安全或倫理程序。管理警示：雖能快速達標，但可能留下巨大的法律或安全後患。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_13', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「貪婪的特權者」。認為自己的「特殊」地位應換取超越規則的利益，且不會對利用他人感到愧疚。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_13', 'C', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「熱情的利己者」。雖熱愛工作，但其動機可能源於工作帶來的灰色利益獲取機會。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_14', 'A', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「內斂的高手」。具備極強能力卻不張揚。預測：在團隊中極受尊敬且具備高影響力，是理想的導師（Mentor）型人選。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_14', 'A', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「僕人式領導」。真心平視他人並感同身受。預測：能創造極高的心理安全感，非常適合帶領高知識產能或需要創意協作的團隊。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_14', 'A', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「低調的協調者」。能身處不同階層而不顯突兀。管理建議：在跨部門溝通中具備極強的潤滑作用，能有效降低組織摩擦。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_14', 'A', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「終身學習者」。因謙虛而自覺不足，能持續吸收新知。管理預測：具備極佳的受教性（Coachability），是組織持續進化的核心力量。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_14', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「狂妄的野心家」。成功後傾向於擴張自我，排斥他人功勞。警示：容易造成「一將功成萬骨枯」的情形，需注意優秀部屬的流失。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_14', 'C', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「權勢型操縱者」。自視甚高且擅長權術。風險預測：會利用職位或資訊不對稱來打壓異己，對組織文化透明度有強烈破壞性。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_27', 'C', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「利己主義者」。不僅計較獲得，還可能為了獲取更多而犧牲他人或組織利益。風險預測：是潛在的誠信風險對象。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_14', 'C', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「過度自負的樂觀」。相信自己無所不能且未來必勝。警示：容易忽略客觀風險警訊，導致組織在重大決策上出現盲目的毀滅性策略。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_14', 'C', 'CIA_24', 'C', '與 CIA_24 (真實性) C聯動：表現為「虛飾的名利徒」。為了維持高人一等的形象而不斷包裝或誇大事實。行為預測：在面對錯誤時會全力推諉，以保護其自傲的形象。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_14', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「職場獨裁傾向者」。自認優越且理應享有特權。管理警示：會強烈要求特殊化管理，破壞組織的制度統一性，挑戰管理權威。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_14', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「偽裝的菁英」。內心傲慢但外在包裝得很得體。警示：這種「隱性傲慢」會在長期合作或高壓下暴露，需注意其對團隊長期信任的損害。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_14', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「自尊極度敏感者」。因自視甚高，任何輕微的指正或異議都會被其視為嚴重的冒犯，引發劇烈的情緒反應。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_15', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「無敵的開路者」。具備強大成功慾望且擁有充足心理資源支持。預測：面對高難度挑戰時不會輕言放棄，是組織推動艱鉅任務的最佳人選。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_15', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「務實的樂觀主義者」。既對未來抱持正向期待，又能冷靜分析潛在風險。預測：能制定出具備激勵性且紮實可行的計畫。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_15', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「韌性十足的變革者」。創新過程中失敗率極高，高心理資本提供了失敗後的快速復原力。預測：能帶領團隊在反覆試錯中找到新路徑。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_15', 'A', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「正向能量傳播者」。能以自身的樂觀與韌性感染團隊，在逆境中穩定軍心。管理建議：適合作為組織文化大使或危機應變核心。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_15', 'A', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「天生贏家型員工」。對工作充滿熱情且心態極其健康，離職風險與燃盡風險極低。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_15', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「焦慮的耕耘者」。雖極其努力工作，但內心缺乏支撐資源。警示：一旦遇到無法控制的挫折，極易陷入自我否定，需高度關注其心理健康。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_15', 'C', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「崩潰邊緣的完美者」。追求完美但心理資源不足以承載失敗。風險預測：只要成果有一點瑕疵，其崩潰感會比一般人強烈數倍，易出現逃避行為。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_15', 'C', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「清高的受害者」。堅持正直但在不公環境中缺乏韌性與樂觀。預測：容易因職場政治感到灰心喪志，轉向消極應對。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_15', 'C', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「苦命的承擔者」。責任感強迫其接下工作，但內心深感無力與悲觀。警示：是「職場過勞」的高風險群組。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_15', 'C', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「渴望成長但自卑者」。想變好但總擔心自己做不到。管理建議：需提供明確的成長路徑與頻繁的小成功（Small Wins）來補足信心。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_15', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「易碎的火藥桶」。對逆境耐受力差且易被激怒。風險預測：在壓力下不僅容易放棄，還會伴隨激烈的情緒宣洩，對團隊穩定性極大傷害。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_16', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「目標導向的戰略家」。不僅想把事做對（盡責），且腦中總有多套達成目標的路徑。預測：在遇到阻礙時會迅速切換執行策略，而非死守一條死路。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_16', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「周密的夢想家」。具備宏大的目標動機，但每一步都經過精確計算。管理預測：能提出既具備野心又能避開風險的長遠計畫。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_16', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「急躁的開拓者」。對達成目標充滿渴望與策略，但執行時易因情緒波動而偏離軌道。管理警示：雖有點子且想贏，但需他人協助維持執行節奏。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_16', 'A', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) A聯動：表現為「正派的願景家」。其規劃的達成路徑完全符合倫理，不屑於透過損人利己的方式達成目標，是組織誠信文化的好榜樣。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_16', 'A', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「不屈的導航員」。遭遇重大挫折（韌性）後，能迅速產生新的目標動機與執行方案（希望）。預測：是組織度過經營危機的靈魂人物。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_16', 'A', 'CIA_23', 'A', '與 CIA_23 (獨創性) A聯動：表現為「創新的策略師」。善於用非傳統的方法達成目標，能看見別人看不見的替代方案。預測：適合解決結構性難題或處理複雜的商業併購。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_16', 'A', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「鼓舞人心的領導者」。不僅自己有希望，還能站在他人立場設計出讓團隊成員都有共鳴的達成路徑，大幅提升團隊動能。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_16', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「盲目的攀登者」。極想成功（成就動機）但缺乏達成目標的路徑規劃能力（低希望）。管理警示：容易像無頭蒼蠅般瞎忙，需主管協助給予明確的操作指引。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_16', 'C', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「絕望的苛求者」。對結果要求完美，但對「如何達成」缺乏信心。風險預測：常因看不見完美的達成路徑而陷入極度悲觀，並出現嚴重拖延。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_16', 'C', 'CIA_19', 'C', '與 CIA_19 (樂觀) C聯動：表現為「習得性無助的典型」。對未來不抱期待，也不相信自己能找到出路。管理警示：動能完全熄火，若持續在高壓職位，極易引發嚴重的心理健康問題。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_16', 'C', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「空有願望的成長者」。想變好但找不到具體方法。管理建議：應提供結構化的培訓與導師指導（Mentorship），幫他畫出成長路徑。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_17', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「強效執行者」。具備極高的達成信心且配合嚴明的紀律。預測：對承諾的目標有極高的達成率，且過程穩定不需督促。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_17', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「深思熟慮的自信者」。其信心建立在充分的準備與分析之上，而非盲目自信。預測：能承擔高風險決策，因為他已看清路徑並相信自己能控場。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_17', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「過度擴張的冒險家」。相信自己能搞定一切但行為容易失控。警示：容易承諾超過自身負荷的任務，需主管協助控管承諾邊界。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_17', 'A', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「信念堅定的專家」。對能力（08）與努力達成目標（17）都有極高信心。預測：展現出強大的氣場與說服力，適合帶領變革或開拓性任務。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_17', 'A', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「脆性自信者」。在順境中信心爆棚，但一旦努力後仍失敗，自信會迅速崩塌。管理建議：需在失敗初期即時介入，防止其陷入自我懷疑。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_17', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「敢於突破的發明者」。相信非傳統的方法可行且自己能推動它。預測：能打破僵化的 SOP，透過創新的手段達成他人認為不可能的目標。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_17', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「傲慢的精英」。相信自己能力出眾且理應獲得特殊回報。警示：容易低估團隊貢獻，認為成功全是個人努力的結果。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_17', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「強勢的專家」。對自己極度自信，因此對「不專業」或「進度慢」的同事容忍度極低，易因恨鐵不成鋼而爆發脾氣。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_17', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「焦慮的攀登者」。非常想成功（成就動機）但內心不信自己做得到。行為預測：工作中伴隨高度壓力與自我懷疑，需頻繁獲得成功經驗來補足信心。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_17', 'C', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「冒名頂替症候群」。要求無暇疵但深怕被看穿能力不足。風險預測：常因恐懼失敗而導致嚴重的任務拖延或過度準備（Over-preparing）。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_17', 'C', 'CIA_19', 'C', '與 CIA_19 (樂觀) C聯動：表現為「習得性無助者」。不相信未來會變好，也不相信自己有能力改變。管理警示：動能趨近於零，在變動環境中容易率先放棄，需透過小目標建立信心。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_17', 'C', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「求知若渴的學徒」。強烈想變好但現在沒信心。管理建議：是極佳的培訓對象，適合給予結構化的技能引導與正向回饋。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_18', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「長線抗壓執行者」。即便計畫出錯，也能在修復情緒後迅速回歸紀律。預測：在高度不確定且高壓的專案中，產出品質最為持久。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_18', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「愈挫愈勇的開拓者」。失敗被其視為達成最終成功的養分。預測：是組織進攻困難市場、開發新客戶時最穩定的先鋒。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_18', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「健康的完美主義」。追求高品質但能容忍過程中的挫折，並從瑕疵中學習。預測：具備極強的自我優化能力。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_18', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「無畏的實驗家」。創新即代表不斷失敗，高韌性確保其在實驗重重受阻時，仍能維持探索的動力。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_18', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「快速冷靜者」。雖然容易受到挫折激怒（易激度高），但能迅速從情緒中復原並重回理性。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_18', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「易碎的樑柱」。做事盡責但抗壓性極差。警示：一旦遭遇重大失敗，其「盡責」會轉化為強烈的自我否定，需高度防範燃盡（Burnout）。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_18', 'C', 'CIA_05', 'A', '與 CIA_05 (衝動管理) A聯動：表現為「沉默的受難者」。雖能管住行為不爆發，但內心緩衝能力極低。管理風險：壓力會持續累積而非排解，易導致無預警離職。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_18', 'C', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「习得性無助者」。既不信自己有能力，也無法承受壓力。管理預測：在變動環境中會最先喪失功能，需安排在穩定、低壓職位。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_18', 'C', 'CIA_19', 'C', '與 CIA_19 (樂觀) C聯動：表現為「悲觀的受災戶」。對未來不抱期待，且遭受打擊後一蹶不振。警示：會擴大團隊的負面氛圍，需注意其對士氣的殺傷力。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_18', 'C', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「心碎的公平追求者」。對不公平現象極度在意，且一旦受到不公對待，修復心理創傷的速度極慢，易產生長期怨懟。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_18', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「玻璃心的巨嬰」。認為應受特權對待，一旦被指責或遭遇普通挫折，會感到嚴重的心理受傷與憤怒。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_19', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「務實的樂觀者」。對未來充滿期待，但每一步都經過精確計算以避險。預測：能提出具備野心且高度可行性的商業提案，不會盲目衝動。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_19', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「進取的完美主義」。追求極致品質，且相信透過努力必能達成。管理建議：其正向心態能緩解完美主義帶來的焦慮，是高品質產出的核心。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_19', 'A', 'CIA_13', 'C', '與 CIA_13 (公正性) C聯動：表現為「投機的冒險家」。相信「壞事不會發生在自己身上」，因此更敢於走捷徑或忽視規則。警示：高樂觀掩蓋了道德風險，需加強合規稽核。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_19', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「變革的傳教士」。相信創新必能改變現狀，且不畏懼初期的挫折。預測：在組織轉型中是極佳的動員者與願景傳播者。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_19', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「陽光的火藥桶」。雖然容易被激怒，但因具備正向歸因，怒氣消散極快，不會記恨或長期陷入負面情緒。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_19', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「防禦性的勤奮者」。因不相信未來會自然變好，所以靠極度努力來對抗焦慮。警示：雖產出穩定但心理壓力極大，需適時給予紓壓支援。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_19', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「焦慮的攀登者」。極想成功但總預感會失敗。預測：行為上雖衝刺，但內耗嚴重。成功後常感如釋重負而非喜悅，需關注其身心健康。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_19', 'C', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「抑鬱的放棄者」。既不信自己有能力，也不信環境會好轉。管理風險：極易陷入「習得性無助」，在變動中完全喪失動能，需優先輔導。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_19', 'C', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「陰鬱的操縱者」。因對人性悲觀，更傾向於使用權術或欺騙來保護個人利益。預測：職場防禦心極強，難以建立深度夥伴關係。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_19', 'C', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「韌性支撐的求存者」。雖然對未來不樂觀，但遭受打擊時能硬撐並站起來。管理建議：屬於「實戰型」人才，雖然口頭消極，但行為上極其堅韌。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_19', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「戴著面具的悲觀者」。內心充滿不安，但為了獲得認可而表現出正向樂觀的樣子。警示：這類員工最難察覺其真實壓力水準。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_20', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「實踐型變革者」。不僅有點子，且能透過自律將創意標準化、流程化。預測：能產出既具新意又具備極高完工度的成果。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_20', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「策略型創新者」。在挑戰現狀前會先進行縝密的風險評估。預測：其提出的變革方案通常具備高度可行性，容易獲得高層支持。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_20', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「不穩定的發明家」。雖有大量創新構思但缺乏行為剎車，容易在未經驗證下頻繁更動流程。警示：會對團隊造成執行上的混亂，需專人負責收尾。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_20', 'A', 'CIA_13', 'C', '與 CIA_13 (公正性) C聯動：表現為「游走灰色地帶的破壞者」。利用創新力來鑽規則漏洞或損人利己。管理警示：其創意可能帶來合規風險，需嚴格控管其變革權限。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_20', 'A', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「無畏的變革推手」。對創新充滿樂觀與韌性，即便方案被否決也能迅速修正再出發。預測：是推動企業文化轉型的重要火車頭。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_20', 'A', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「精實創業家」。創新是為了極大化效率，追求用更聰明的方法解決問題。管理建議：非常適合負責自動化、數位轉型或流程優化專案。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_20', 'A', 'CIA_26', 'C', '與 CIA_26 (同理心) C聯動：表現為「冷酷的顛覆者」。為了推動創新方案而無視團隊成員的情緒壓力。風險預測：雖能達成變革，但過程中可能引發強烈的人際衝突與流失。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_20', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「卓越的守成者」。對現有規則極度忠誠且執行到位，但不具備優化意識。管理建議：適合維護既有成熟系統，但不宜指派其負責開發期專案。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_20', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「努力的跟隨者」。極想成功但缺乏原創思維，傾向於複製已證明的成功模式。預測：在成熟市場的執行力強，但難以應對藍海市場。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_20', 'C', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) A聯動：表現為「傳統捍衛者」。對變革有天然的抗拒感，認為穩定勝於一切。警示：在組織面臨轉型時，可能是最難被說服的人群，需給予充足的過渡期。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_20', 'C', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「渴望成長的模仿者」。雖想自我進步，但傾向於吸收外部現成知識而非自己創造新路徑。管理建議：適合透過外部培訓來引導其技能更新。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_21', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「高效產能機器」。不僅想做好，還要做得快。預測：能在最短時間內產出高品質結果，是組織中標準的「高潛力人才（HiPo）」。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_21', 'A', 'CIA_03', 'C', '與 CIA_03 (審慎) C聯動：表現為「速食決策者」。為了趕進度而犧牲思考深度。警示：容易因追求快而遺漏關鍵風險，需他人協助進行最終審核。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_21', 'A', 'CIA_06', 'C', '與 CIA_06 (條理性) C聯動：表現為「混亂的高效者」。不拘泥於辦公桌整潔或 SOP，只要能最快拿到結果，過程混亂也無所謂。管理建議：適合作為突擊隊員處理緊急任務。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_21', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「精實大師」。在追求無瑕疵的同時不斷優化動作，達成「一次就做對且最快」。預測：具備卓越的自我優化與流程設計能力。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_21', 'A', 'CIA_13', 'C', '與 CIA_13 (公正性) C聯動：表現為「捷徑尋找者」。為了提升效率不惜損害他人利益或遊走道德邊緣。警示：其效率可能建立在合規風險之上，需嚴格監控手段合法性。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_21', 'A', 'CIA_26', 'C', '與 CIA_26 (同理心) C聯動：表現為「冷酷的數據者」。視人為資源，為求團隊總產出極大化而忽略個別成員的身心狀況。風險：短期績效極高，但長期團隊流失率大。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_21', 'A', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「快樂的生產者」。對優化流程充滿熱情。預測：具備極強的抗燃盡能力，因為他們總能找到更輕鬆且高效的方式完成工作。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_21', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「傳統苦幹者」。非常努力且負責任，但往往使用舊方法、笨方法。管理建議：應指派其參加工作坊學習新工具，提升其數位化能力。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_21', 'C', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「耗時的工匠」。為了細節極限而嚴重拖慢進度。警示：容易在非核心細節上投入過多資源，需主管定義任務的「停損點」。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_21', 'C', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「步調緩慢的樂天派」。做事節奏慢但不感到壓力。管理預測：在高度競爭、節奏極快的環境（如電商、金融）中，會顯得格格不入。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_21', 'C', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) A聯動：表現為「僵化的官僚執行者」。嚴格遵守流程即使該流程已明顯不合時宜。警示：是組織冗長流程的維護者，缺乏變革動機。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_21', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「拖延的焦慮者」。因效率低導致任務堆積，進而引發焦慮與負面情緒。預測：在高壓截止日期前極易情緒失控。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_22', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「組織的鋼鐵基石」。具備極高的可靠性與服從度。預測：在嚴謹、高壓且需精確執行的環境（如航太、軍事、醫療）中表現最卓越。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_22', 'A', 'CIA_20', 'C', '與 CIA_20 (創新力) C聯動：表現為「守舊的官僚者」。過度依賴舊規，對任何改變都有天然抗拒。管理建議：不宜指派其負責開發期專案，但在維護既有成熟系統時極其稱職。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_22', 'A', 'CIA_05', 'A', '與 CIA_05 (衝動管理) A聯動：表現為「冷靜的制度執行者」。即便面對極大情緒壓力，也能管住行為不做出任何違規舉動。預測：適合處理敏感、保密且流程僵化的行政事務。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_22', 'A', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「表面服從者」。口頭高度配合公司規則，實則利用規則死角謀求私利。警示：此組合最具隱蔽性，需透過非正式溝通管道瞭解其真實動向。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_22', 'A', 'CIA_26', 'C', '與 CIA_26 (同理心) C聯動：表現為「死板的鐵面人」。執行制度時毫不留情，無視他人苦衷。管理風險：極易在基層引發反感，需留意其與團隊成員的磨合狀況。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_22', 'A', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「忠誠的受命者」。一旦認同指令，會不計代價地落實。預測：是主管最放心的「交辦對象」，通常不需要二次確認進度。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_22', 'C', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「破壞式創新者」。視規則為絆腳石，傾向於「先做再說，被抓到再道歉」。管理建議：適合研發或前線開拓，但必須配備一名行政助手協助合規收尾。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_22', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「自律的獨行俠」。對工作品質有高要求（盡責），但非常討厭形式化的規矩。預測：會產出高品質結果，但常因不填日報或不按流程申請而遭行政單位投訴。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_22', 'C', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「精明的規避者」。在不遵循規則前會精密計算過後果，確保自己不會受到懲罰。警示：其違規行為通常具備「戰略性」，難以透過簡單管理糾正。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_22', 'C', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「俠義的破局者」。會為了團隊利益或夥伴情誼而勇敢挑戰公司「不合理」的制度。管理預測：是潛在的基層意見領袖，若管理不當易形成對立。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_22', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「反叛的刺頭」。認為規則是用來約束平庸者的，自己應享有例外權。風險：極易公開挑戰主管權威，對組織紀律的殺傷力極大。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_22', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「易爆的刺客」。對規範有強烈排斥感，一旦被要求遵守規則，極易產生對抗性的負面情緒反應。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_23', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「多產的原創大師」。能將獨特的點子轉化為具體的作品或提案，而非流於空想。預測：能穩定產出具有高度辨識度的專業成果。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_23', 'A', 'CIA_06', 'A', '與 CIA_06 (條理性) A聯動：表現為「結構化的創意者」。能將天馬行空的想法整理成極具邏輯的體系。管理建議：適合作為產品架構師或內容策略開發者。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_23', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「極致美學追求者」。對原創內容的細節有近乎病態的要求。預測：能創造出具備極高品牌價值的巔峰之作，但開發週期可能較長。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_23', 'A', 'CIA_12', 'A', '與 CIA_12 (低物質傾向) A聯動：表現為「純粹的藝術家靈魂」。創作不為名利，只為表達獨特的自我。管理建議：難以用金錢激勵，應給予高度的自主權與創作空間。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_23', 'A', 'CIA_22', 'C', '與 CIA_22 (紀律遵循度) C聯動：表現為「反傳統的奇才」。其原創性往往建立在對舊有規定的否定之上。風險：可能在團隊中顯得格格不入，甚至挑釁現有流程。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_23', 'A', 'CIA_24', 'A', '與 CIA_24 (真實性) A聯動：表現為「忠於自我的創作者」。其點子不僅獨特，且反映其真實內在。預測：具備強大的個人魅力與品牌原創性，適合品牌代言或核心價值詮釋。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_23', 'A', 'CIA_35', 'A', '與 CIA_35 (生活熱情) A聯動：表現為「靈感不斷的發電機」。對生活充滿好奇，能從跨領域的體驗中汲取養分。預測：在腦力激盪（Brainstorming）會議中是不可或缺的點子來源。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_23', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「高產出的複刻者」。雖有強大成功渴望，但傾向於走已驗證的「安全牌」。管理警示：在需要顛覆式設計的環境中會顯得靈魂不足。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_23', 'C', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「務實的執行專家」。對處理已知領域的任務非常有信心，但對「無前例可循」的創意任務感到不安。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_23', 'C', 'CIA_20', 'A', '與 CIA_23 (獨創性) C 與 CIA_20 (創新力) A：表現為「改良型工程師」。擅長優化現有流程，但較難產出顛覆性的新概念。預測：是組織進行漸進式改進（Kaizen）的優選。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_23', 'C', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「圓滑的從眾者」。為人好相處，思維大眾化，不具威脅性。管理建議：適合作為前線服務或需要大量人際協作的標準化職務。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_23', 'C', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「勤奮的學習機器」。能快速吸收現有的知識體系，但較難發展出個人風格的見解。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_24', 'A', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「組織的道德羅盤」。其正直源於深層的內在信念而非恐懼懲罰。預測：在企業面臨倫理抉擇時，會是堅持價值觀而不妥協的關鍵力量。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_24', 'A', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「真誠的人道主義者」。對人的關懷不具政治目的，能建立極高質量的深度信任。管理建議：適合作為高階教練或員工關係調解者。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_24', 'A', 'CIA_29', 'C', '與 CIA_29 (人際適應力) C聯動：表現為「頑固的真誠者」。不願為了場面圓滑而掩飾想法，說話過於直接。警示：雖值得信任但易在社交中受挫，需主管保護其直言不諱的勇氣。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_24', 'A', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) C聯動：表現為「純粹的自我」。完全不在乎社會評價，僅追求對得起自己。預測：測評結果極具參考價值，其反饋通常是未經修飾的真相。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_24', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「情緒透明者」。高興或憤怒都寫在臉上，絕不隱藏。管理建議：雖有情緒但因透明而好預測，主管能輕易判讀其當下的心理狀態。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_24', 'C', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「盲從的組織人」。為了融入群體可以隨時修改自己的立場與偏好。管理警示：缺乏獨立見解，容易在團隊中形成集體盲思（Groupthink）。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_24', 'C', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「精明的合約者」。表面表現得不在意，實則內心精密計算每一分回報。警示：一旦感到不公，會使用非直接的方式進行報復或怠工。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_24', 'C', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「圓滑的變色龍」。擅長在不同場合展現不同的人格面具以獲取利益。預測：適合業務開發或公共關係，但內部管理時需警惕其承諾的真實度。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_24', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「隱性特權索求者」。內心認為自己高人一等，但在外表上會包裝成平易近人的樣子。管理風險：當其特權未獲滿足時，會展現出劇烈的被動攻擊（Passive-aggressive）。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_24', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「完美的模範人設」。行為完全符合職場教科書要求，但缺乏靈魂與感染力。管理建議：需透過深度對話挖掘其真實需求，防止其突然的職業燃盡。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_25', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「組織的榮譽戰士」。將個人成功與團隊勝敗深度綁定。預測：在競爭激烈的市場中，會為了團隊達標而爆發驚人鬥志，是優質的部門主管人選。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_25', 'A', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「公平的守護者」。追求集體利益的同時堅持公正不阿，防止團隊內部的分配不均。預測：在管理崗位上能極大化團隊信任感，降低內耗。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_25', 'A', 'CIA_14', 'A', '與 CIA_14 (謙虛) A聯動：表現為「無私的貢獻者」。願意默默付出不搶功，將光環留給團隊。管理建議：是建立高凝聚力文化的靈魂人物，需適時公開表揚其貢獻，以免其被忽視。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_25', 'A', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「逆境中的黏著劑」。在團隊面臨危機時，其強大的歸屬感會轉化為支撐同僚的韌性。預測：能有效防止團隊在壓力下瓦解。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_25', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「排外的護城河」。雖對團隊忠誠，但認為自己的小圈子應享有優於其他部門的特權。警示：易引發跨部門協作的衝突。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_25', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「專業的獨行俠」。工作極度負責，但只管好自己的事，不參與團隊事務。管理建議：適合獨立研究或專家職位，不宜強迫其負責團建。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_25', 'C', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「職場僱傭兵」。僅視組織為跳板，缺乏忠誠度。警示：隨時可能為了更高待遇離職，甚至帶走核心資源，需加強競業條款與資安控管。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_25', 'C', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「孤傲的顛覆者」。點子極多但常挑戰既有團隊共識。預測：其創新可能因缺乏群體支持而難以落地，需配備溝通力強的搭檔。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_25', 'C', 'CIA_26', 'A', '與 CIA_25 (集體意識) C 與 CIA_26 (同理心) A：表現為「選擇性關懷者」。同情個體，但對抽象的組織利益無感。行為預測：會為了下屬的私事而違反公司規章。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_25', 'C', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「計較的交易者」。對個人利益分毫不讓，完全依照合約行事。管理建議：以明確的獎酬與關鍵績效指標（KPI）來對話，勿談願景。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_25', 'C', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「圓滑的投機客」。表面人緣極佳，實則內心與組織極度疏離。警示：具備強大的帶風向能力，若對公司不滿，會成為潛在的輿論隱憂。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_25', 'C', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「自嗨的工作狂」。對工作本身充滿熱愛，但對團隊合作或組織規範感到煩躁。預測：是高產出的個人工作者，但不具備管理潛質。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_26', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「溫暖的執行者」。在追求工作產出的同時，會極力避免對他人造成困擾或負擔。預測：是極佳的團隊導師，能以身作則且耐心引導後進。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_26', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「周全的協調家」。在做決定前會細膩評估對相關人員的心理影響。管理建議：適合處理組織內複雜的人事異動或高難度的客戶關係。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_26', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「情感起伏大的照顧者」。雖極具愛心但情緒容易受他人影響。警示：容易因為過度同情而做出不理智的承諾，需注意心理邊界。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_26', 'A', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「仁慈的裁判」。堅持原則的同時，能以令人舒服的方式傳達紀律。預測：在管理崗位上能將「法、理、情」完美結合，深獲下屬愛戴。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_26', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「情感敏感者」。對外界情緒極度敏銳，容易感同身受但也容易被他人負能量引燃。風險：在高壓負面環境中極易產生情緒倦怠。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_26', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「冷酷的攀登者」。目標感極強且無視他人痛苦，視團隊成員為達成目標的工具。警示：高產出但伴隨高流失，需注意其對組織氛圍的破壞。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_26', 'C', 'CIA_06', 'A', '與 CIA_06 (條理性) A聯動：表現為「無情的標準作業機器」。凡事講究程序與邏輯，對他人的情緒訴求感到不耐與困惑。管理建議：適合處理冷冰冰的數據與流程，不宜負責第一線客服。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_26', 'C', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「掠奪型操縱者」。了解他人弱點（認知同理強）但不在乎其感受（情感同理弱），並藉此進行社交操弄。風險：職場霸凌的高潛在對象。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_26', 'C', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「鐵石心腸的倖存者」。能在混亂中保持冷靜，不被哀兵政策所動。預測：在執行裁員或重大改革等痛苦決策時，能展現出極強的心理剛性。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_26', 'C', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「精確的會計師人格」。只看數據與對等回報，不談人情。管理建議：以事實與契約為對話基礎，任何情感訴求對其皆無效。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_26', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「自我中心的特權者」。認為全世界應繞著他轉，完全無視他人需求。警示：對團隊合作極具毀滅性，需建立明確的人際邊界。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_27', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「無私的耕耘者」。不僅做事負責，且不計較短期得失。預測：在初創期或資源匱乏的專案中，是最穩定的戰力，不會因獎金遲發而輕易動搖。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_27', 'A', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「組織奉獻者」。願意為了團隊成功而超時工作或共體時艱。管理建議：應定期給予精神激勵與長期承諾，防止其因長期被「佔便宜」而最終崩潰。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_27', 'A', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「熱情的志工心態」。工作本身就是回報，對薪酬以外的價值（如成就感）極度重視，是企業文化的穩定核心。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_27', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「精明的績效導向者」。追求成功，但每一步都要求相對應的報酬。管理警示：若制度無法提供「即時且優渥」的反饋，其動能會迅速消失。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_27', 'C', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「風險與收益的精算師」。在投入任何心力前會先精密估算 ROI。預測：極少做白工，但也可能因此錯失需要先行投入的創新機會。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_27', 'C', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「心灰意冷的離職預備軍」。在挫折中感到不公平時，修復能力極差。警示：一旦其心裡那把「秤」失衡，會很快進入安靜離職（Quiet Quitting）狀態。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_27', 'C', 'CIA_32', 'A', '與 CIA_27 (權益公平感) C 與 CIA_32 (心理特權) A：表現為「職場霸凌或特權索求者」。認為付出是應得的，但回報必須遠超常人。管理風險：會破壞團隊的和諧與公平認知。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_27', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「戴著面具的交易者」。表面客氣，實則內心精密計算每一分得失。警示：通常在離職那天主管才發現其對薪資或福利積怨已久。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_27', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「易怒的維權者」。對微小的不公（如午餐津貼少了十元）會有極大的負面情緒反應。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_28', 'A', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「團隊的向心力來源」。不僅認同團體，且會公開表達對同事協助的感激。預測：能極大化團隊成員的心理回報感，降低離職意願。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_28', 'A', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「真誠的共感者」。能敏銳感知他人的付出並給予溫暖回饋。管理建議：適合作為團隊領導者或 HR，能營造極佳的工作氛圍。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_28', 'A', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「良性循環的發動機」。樂於付出且感激所得，不會斤斤計較。預測：在資源有限的環境下，仍能保持正向積極的心態。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_28', 'A', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) C聯動：表現為「純粹的感恩者」。其感激是發自內心的珍惜，而非社交辭令。預測：其建立的人際關係極為穩固且深厚，具備高度信任度。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_28', 'A', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「高韌性的樂觀派」。習慣從挑戰中看見學習的機會與他人的幫助。行為預測：面對挫折時復原極快，且能帶動團隊維持士氣。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_28', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「理所當然的索求者」。認為他人的幫助是應得的，極少表達謝意。警示：會迅速消磨團隊的合作熱情，導致周遭同事產生被剝削感。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_28', 'C', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「功利的表演者」。僅在對自己有利時才表現出感謝。風險預測：其人際關係往往是短暫且具備目的性的交易關係。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_28', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「自我中心的攀登者」。極度關注個人目標與成功，容易忽略過程中他人的支援與貢獻。管理警示：容易造成「收割成果」的負面印象。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_28', 'C', 'CIA_27', 'C', '與 CIA_27 (權益公平感) C聯動：表現為「計較的分配者」。更在意自己「沒得到什麼」而非「得到了什麼」，容易對現狀感到不滿。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_28', 'C', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「傲慢的專家」。將成功完全歸功於個人能力，忽視環境因素與同儕協助。管理風險：難以聽取他人建議，協作難度高。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_29', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「目標導向的社交家」。能為了達成商業目標而精準調整與不同利害關係人的溝通風格。預測：極具商務談判潛力。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_29', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「圓滑的談判專家」。在社交適應的同時保持警覺與風險意識。管理建議：適合作為高階採購或涉及重大利益的外部對接人。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_29', 'A', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「變色龍般的操縱者」。具備極高的適應力但動機不純。警示：能輕易贏得各方信任，但需警惕其利用社交技巧進行政治操弄。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_29', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「變革的推客」。能向不同部門的保守者推銷創新的點子，透過調整語境降低變革阻力。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_29', 'A', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「高 EQ 的和諧大師」。既能感同身受（同理），又能靈活應對（適應）。預測：是組織中處理人際衝突、建立跨部門信任的靈魂人物。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_29', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「優雅的權利追求者」。雖然內心自負，但懂得透過社交手段（偽裝適應）來獲得其想要的特權待遇。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_29', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「耿直的模範生」。做事極其到位但做人缺乏彈性，容易在與「風格不合」的同事協作時產生嚴重摩擦。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_29', 'C', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) A聯動：表現為「木訥的正人君子」。堅持原則且不屑於社交包裝，這類人值得信賴但可能在複雜的職場政治中被邊緣化。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_29', 'C', 'CIA_14', 'A', '與 CIA_14 (謙虛) A聯動：表現為「隱形的技術專家」。不愛社交也不愛表現，傾向於窩在自己的舒適圈。管理建議：適合獨立技術鑽研，不宜負責外務。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_29', 'C', 'CIA_28', 'A', '與 CIA_28 (感謝) A聯動：表現為「內斂的知恩者」。內心感激他人但不知如何適當地表達或與人互動，導致其社交意圖常被誤解。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_29', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「人際火藥桶」。社交適應度低且情緒控制差，易因他人的行為不符預期而直接爆發衝突。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_30', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「終極執行者」。不僅做事細心，且對結果負百分之百的責任。預測：是組織中最不需要追蹤進度的員工，其承諾即等於結果。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_30', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「熱血的救火隊」。雖行為易衝動出錯，但出錯後會第一時間承擔並拼命補救。管理建議：應肯定其擔當，同時輔導其降低出錯率。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_30', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「零瑕疵的承諾者」。對自己要求極高，且決不容許因個人疏忽導致計畫失敗。預測：產出品質極高，但心理壓力極大。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_30', 'A', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「職場清流」。堅持正道且對行為後果負責。預測：在面對利益誘惑或灰色地帶時，能基於強烈的責任感與道德感守住底線。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_30', 'A', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「不倒的基石」。在逆境中不僅能自保，還會因為自覺有責任「把事做好」而撐起團隊。管理建議：適合擔任關鍵專案的負責人（Owner）。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_30', 'A', 'CIA_22', 'C', '與 CIA_22 (紀律遵循度) C聯動：表現為「結果導向的破局者」。不在乎死板流程，甚至會為了確保「事情做好」而微調規則。預測：雖有違規風險，但其初衷是為了達成最終目標。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_30', 'C', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「推諉的天才」。自認能力強，因此一旦出錯，會傾向於歸咎環境、系統或同事太笨，而非自我反省。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_30', 'C', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「滑頭的操縱者」。擅長透過文字遊戲或社交技巧規避責任，發生問題時總是第一個「消失」或「撇清」。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_30', 'C', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「樂天的甩鍋者」。遇到問題不覺得是大事，樂觀地認為「船到橋頭自然直」，導致問題持續擴大。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_30', 'C', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「依賴團體的成員」。認同團隊但缺乏個人當責感，習慣躲在集體決策背後，缺乏獨立承擔的勇氣。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_30', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「職場巨嬰」。認為自己應得一切，但不願為任何失敗負責。警示：極度破壞團隊士氣，需建立明確的 KPI 責任制。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_31', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「進取型精英」。追求成功的同時，將自我提升視為達成目標的必要路徑。預測：會主動尋求回饋並迅速修正弱點，成長速度極快。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_31', 'A', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「謙遜的求知者」。雖對目前能力缺乏信心，但具備強烈變強的渴望。管理建議：是最佳培訓對象，只要給予資源，其回報率極高。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_31', 'A', 'CIA_16', 'A', '與 CIA_16 (希望) A聯動：表現為「願景實踐者」。不僅渴望成長（31），且具備設計成長路徑的能力（16）。預測：能自我規劃職涯路徑，不需要組織過多干涉。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_31', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「終身進化的變革者」。將創新視為一種學習與成長的機會。預測：在技術更迭極快的產業中，能始終保持競爭力。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_31', 'A', 'CIA_23', 'A', '與 CIA_23 (獨創性) A聯動：表現為「尋求獨特發展的創意人」。渴望發展出具備高度個人特色與原創性的技能體系。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_31', 'A', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「自律的修煉者」。基於責任感認為自己有義務「變得更好」以應對工作。預測：是組織內部轉型、接班人計畫的首選。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_31', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「穩定的守成勞動者」。做事負責但拒絕改變。警示：雖能處理現有工作，但若職責範疇發生質變，其適應困難度會極高。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_31', 'C', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「停滯的自負者」。認為現有能力已足夠，缺乏進一步發展的動力。管理風險：容易產生職場僵化，甚至抗拒新的數位工具或流程。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_31', 'C', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) C聯動：表現為「利潤導向的現狀者」。對成長本身無感，成長的動力僅來自於金錢激勵。管理建議：需將培訓與獎金掛鉤，否則其學習意願極低。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_31', 'C', 'CIA_15', 'C', '與 CIA_15 (心理資本) C聯動：表現為「心灰意冷的被動者」。對自我發展持悲觀態度，不相信努力可以改變現狀。警示：是組織中典型的「負資產」，需注意其消極情緒擴散。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_31', 'C', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「單一技能的狂熱者」。對目前的工作很有熱情，但不願意跳出舒適圈去學習跨領域技能。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_32', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「自負的野心家」。追求高成就，但認為組織必須先給予資源或特權作為前提，若不符合其「高標待過」則拒絕投入。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_32', 'A', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「精英主義者」。極度自信且認為自己應高人一等。管理風險：容易挑戰主管權威，認為既有規範不適用於自己。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_32', 'A', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「掠奪型員工」。不僅追求特權（32），且缺乏謙遜與誠實（10），可能為了獲取特殊利益而損人利己。警示：職場舞弊的高潛在群組。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_32', 'A', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「權力操縱者」。擅長透過政治手段或欺騙來維持其特權地位。風險預測：會破壞團隊的公平競爭環境。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_32', 'A', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「傲慢的索求者」。完全不隱藏自己的優越感，對其他「平庸」的同事缺乏尊重。行為預測：極易引發人際衝突，團隊凝聚力殺手。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_32', 'A', 'CIA_27', 'C', '與 CIA_27 (權益公平感) C聯動：表現為「不滿足的貪婪者」。對回報極度敏感，且永遠覺得自己拿得不夠多。管理建議：需建立明確的法制化契約，限制其特權索求。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_32', 'A', 'CIA_28', 'C', '與 CIA_28 (感謝) C聯動：表現為「忘恩負義的受益者」。視他人的幫助與公司的獎勵為理所當然，完全缺乏感激之心。預測：難以建立長期的情感連結，員工忠誠度低。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_32', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「職場火藥桶」。一旦未獲得預期的優待，會立刻產生劇烈的挫折感與憤怒情緒，出現被動攻擊行為。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_32', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「默默耕耘的典範」。不求特權，只求將事情做好。管理預測：是組織中最穩定、最可靠的「樑柱」，通常具備高滿意度。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_32', 'C', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「無私的團隊成員」。願意為了群體利益隱藏自我需求。管理建議：應主動給予這類人應有的獎酬，以免其被高特權者「吃掉」資源。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_32', 'C', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「高當責的勞動者」。相信回報源於責任與努力（30），而非身分或特權（32）。預測：具備最健康的績效觀念。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_33', 'A', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) A聯動：表現為「極度在意形象的正直者」。雖然內在誠實，但會過度修飾言辭以符合社會規範。管理預測：其測評結果可能比真實情況更「完美」，需結合面談觀察。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_33', 'A', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「高階偽裝者」。具備操縱傾向（11C）且極度在意正面形象（33A）。風險預測：極擅長職場政治，會精準提供主管「想聽的內容」，真實動機難以察覺。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_33', 'A', 'CIA_24', 'C', '與 CIA_24 (真實性) C聯動：表現為「人設經營者」。其展現的自我高度符合組織期望，但與內在價值觀可能嚴重脫節。警示：離職風險極具隱蔽性，往往在崩潰前一刻都表現得非常配合。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_33', 'A', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「社交變色龍」。適應力強且極度在意他人評價，是極佳的公共關係（PR）或服務業人選，但在內部管理時需警惕其表裡不一。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_33', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「隱性自負者」。內心認為應享特權，但為了維持良好形象（33A）會掩飾這種索求。管理風險：當其優越感未獲滿足時，會產生嚴重的被動攻擊。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_33', 'C', 'CIA_24', 'A', '與 CIA_24 (真實性) A聯動：表現為「坦蕩的求真者」。完全不在乎包裝，即便缺點也直白坦露。預測：此人的測評結果信效度極高，其呈現的數據即為真實的自我。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_33', 'C', 'CIA_29', 'C', '與 CIA_29 (人際適應力) C聯動：表現為「耿直的刺頭」。不在乎他人認可，也不願調整溝通方式以適應環境。管理建議：溝通成本高，但其反饋通常是最真實的「防腐劑」。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_33', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「真實的火藥桶」。對不滿情緒毫不掩飾，不會為了維持社交和諧而壓抑怒氣。警示：衝突強度高，需注意其對團隊氛圍的直接衝擊。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_33', 'C', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「鐵面無私者」。即便做法會得罪所有人，也會堅持正確的原則，因為他完全不被「社會期望」所左右。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_34', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「充滿激情的攀登者」。不僅想贏，且熱愛競爭與達標的過程。預測：在組織中能產生極大的正面渲染力，是帶動士氣的天然領袖。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_34', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「卓越的工匠」。對細節的苛求源於對工作的熱愛。預測：能產出具備「靈魂」的高品質成果，但在情緒過度投入時需注意燃盡風險。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_34', 'A', 'CIA_12', 'A', '與 CIA_12 (低物質傾向) A聯動：表現為「純粹的職人」。工作動機完全來自內在喜悅而非金錢回報。管理建議：應提供其高度的專業自主權，而非僅靠薪資激勵。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_34', 'A', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「韌性十足的熱愛者」。對工作的熱情使其能以樂觀心態看待挫折。預測：即便在組織動盪期，也能靠著內心對工作的喜愛而維持產能。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_34', 'A', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「高效的玩家」。熱愛優化流程，將解決問題視為一種樂趣。預測：會不斷自發性地尋找「更聰明的工作方式」。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_34', 'A', 'CIA_35', 'C', '與 CIA_35 (生活熱情) C聯動：表現為「典型的工作狂 (Workaholic)」。生活重心極度向工作傾斜。管理警示：雖短期產能極高，但需強制其休息以避免長期健康受損。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_34', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「枯燥的紀律執行者」。不愛工作但因盡責而完成任務。管理預測：產出穩定但缺乏創意與主動進取的能量，容易出現職業倦怠。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_34', 'C', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「消極的防禦者」。對工作無感且過於謹慎，傾向於推諉變革。管理風險：容易成為組織轉型中的隱形阻力。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_34', 'C', 'CIA_11', 'C', '與 CIA_11 (誠誠) C聯動：表現為「職場僱傭兵」。僅視工作為謀生工具，不惜透過操縱手段獲取最大利益。警示：對組織毫無忠誠度可言，隨時可能跳槽。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_34', 'C', 'CIA_27', 'C', '與 CIA_27 (權益公平感) C聯動：表現為「計較的打工仔」。不愛工作且對回報極度敏感。管理預測：稍有不公便會立刻消極怠工，管理成本極高。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_34', 'C', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「迷惘的求學者」。渴望成長但目前的工作並非其所愛。管理建議：應評估其崗位適配性（Job Fit），考慮內部調動。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_35', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「充滿生命力的開拓者」。不僅想贏，且過程中充滿感染力，能讓追隨者感到振奮。預測：極佳的業務與團隊領袖。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_35', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「熱情的火藥桶」。雖然活潑積極，但因活力過盛且缺乏控制力，容易在人際互動中顯得過於突兀。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_35', 'A', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「陽光的韌性者」。即使在逆境中也能靠著天生的熱情找到樂趣。預測：復原力極強，是組織內部最不容易心理受挫的群體。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_35', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「變革的發電機」。對新想法展現出純粹的熱愛，能以強大的動能推動從未嘗試過的專案。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_35', 'A', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「溫暖的能量散播者」。其熱情是利他的，能帶動同僚共同追求更美好的生活與工作目標。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_35', 'A', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「職業與生活高度融合的快樂者」。生命中的每一分鐘都在燃燒能量，離職風險與過勞感極低。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_35', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「嚴肅的工蜂」。做事一絲不苟但缺乏活力與笑容。管理建議：應肯定其品質，但避免其負責需要大量感染力、公關或團隊動員的任務。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_35', 'C', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「頹廢的自我懷疑者」。既不信自己能做好，也對周遭事物缺乏熱情。警示：易產生憂鬱情緒，需高度關注心理健康。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_35', 'C', 'CIA_19', 'C', '與 CIA_19 (樂觀) C聯動：表現為「陰沉的防禦者」。對未來不抱期待，且行事風格暮氣沉沉。管理風險：容易成為團隊中負能量的擴散點。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_35', 'C', 'CIA_28', 'C', '與 CIA_28 (感謝) C聯動：表現為「情感乾涸者」。對生活缺乏熱力，且對他人的好意也表現得冷淡、無感。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_35', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「焦慮的厭世者」。生活熱情低且易受刺激。預測：在組織中常以抱怨者的身分出現，難以建立和諧關係。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_36', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「焦慮的完美主義執行者」。雖然做事細緻，但一旦進度受阻或出現錯誤，情緒會迅速波動，產生巨大的心理內耗。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_36', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「職場火藥桶」。情緒燃點低且缺乏行為剎車，容易在衝突中脫口而出傷人的話或做出衝動決策。風險：人際關係高度緊張。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_36', 'A', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「自尊極度敏感者」。因自視甚高，任何指正或不同意見都會被其解讀為冒犯，引發強烈的防衛性憤怒。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_36', 'A', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「脆性情緒反應者」。面對挫折時情緒反應劇烈（36A）且難以自我修復（18C），容易陷入長期的低落或憤怒中。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_36', 'A', 'CIA_29', 'C', '與 CIA_29 (人際適應力) C聯動：表現為「社交防禦者」。不擅長管理社交緊張關係，且情緒容易被他人激發，常導致溝通破裂。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_36', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「憤怒的特權索求者」。認為應受優待（32A），一旦願望落空，會表現出極高的情緒激發強度。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_36', 'C', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「冰冷的策略家」。情緒極度穩定且思維嚴謹，在危機時刻能保持驚人的冷靜，進行最理性的判斷。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_36', 'C', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「情緒穩定的樂天派」。面對煩惱時反應淡定，能以積極且平穩的心態尋求解決方案，是團隊的定海神針。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_36', 'C', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「專注的高效機器」。不被瑣事干擾情緒，能持續維持產出動能，即使在混亂的變動中也不會自亂陣腳。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_36', 'C', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「溫和的傾聽者」。具備共情能力但自身情緒穩定，能包容他人的負面情緒而不受影響。管理建議：適合作為衝突調解人。');
INSERT INTO trait_interactions ("primary_trait_id", "primary_band", "trigger_trait_id", "trigger_band", "narrative") VALUES ('CIA_36', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「得體的職場專業人士」。為了形象（33A）與本性（36C），展現出極高的修養與情緒控制力，極少流露負面情感。');
